window.__D("text/maamarim-melukatim/c015",{"p":[[1500380045,"<h3>בס\"ד. ש\"פ אמור, י\"ט אייר, ה'תשל\"ז<sup data-n=\"2537\">*</sup></h3>\n<b>גל</b> עיני ואביטה נפלאות מתורתך<sup data-n=\"2538\">1</sup>, וכתב אדמו\"ר מהר\"ש במאמרו ע\"פ זה<sup data-n=\"2539\">2</sup>, דע\"פ מ\"ש בסידור שער הל\"ג בעומר<sup data-n=\"2540\">3</sup> שהרמז בתורה על ל\"ג בעומר הוא בפסוק<sup data-n=\"2541\">4</sup> עד הגל הזה, גם הפסוק גל עיני יתבאר על ל\"ג בעומר. וע\"פ הידוע שכל הענינים שבתורה הם בתכלית הדיוק, יש לומר, דזה שהענין דל\"ג בעומר שבפסוק גל עיני גו' למדין מהענין דל\"ג בעומר שבפסוק עד הגל הזה, הוא, כי בכדי לבוא לענין גל עיני גו' הוא ע\"י עד הגל הזה.\nב) <b>והנה</b> השייכות דפסוק זה לל\"ג בעומר יום ההסתלקות דרשב\"י (בפשטות) הוא, כי ענינו של רשב\"י הוא – שעל ידו הי' הגילוי דפנימיות התורה [וכמבואר בכ\"מ<sup data-n=\"2542\">5</sup>, שהגילוי דתורה הנגלית הי' ע\"י משה רבינו והגילוי דפנימיות התורה הי' ע\"י רשב\"י<sup data-n=\"2543\">6</sup>], ועיקר הגילוי הי' ביום הסתלקותו, כדאיתא בזהר<sup data-n=\"2544\">7</sup> שביום הסתלקותו גילה לתלמידיו \"מלין קדישין\" שלא גילה במשך כל ימי חייו (כי הענינים שגילה אז היו ענינים נעלים ביותר שאפילו רשב\"י הי' מקודם ירא לגלותם<sup data-n=\"2545\">8</sup>). וע\"י כתיבת המלין קדישין (ע\"פ הציווי שלו<sup data-n=\"2546\">9</sup>), נתגלו אח\"כ לכל ישראל, ועד שנתגלו באופן דיתפרנסון<sup data-n=\"2547\">10</sup>, בהבנה והשגה. שגם המשכת גילוי זה (הגילוי לכל ישראל ובאופן דיתפרנסון) היתה ביום הסתלקות רשב\"י (ע\"י כתיבתן של המלין קדישין אז, ע\"פ הציווי שלו). ולהוסיף, דע\"פ הידוע<sup data-n=\"2548\">11</sup> שביום הסתלקותו של אדם מתגלה הפנימיותשל כל עבודתו שעבד במשך כל ימי חייו, מובן, דביום הסתלקות רשב\"י, נתגלה גם הפנימיות של הסודות שגילה במשך כל ימי חייו. ובכל שנה ושנה, ביום ל\"ג בעומר, חוזר וניעור הגילוי שהי' בל\"ג בעומר בפעם הראשונה<sup data-n=\"2549\">12</sup> – גילוי פנימיות התורה (תורתו של רשב\"י). וכמובן גם מהמבואר בכ\"מ<sup data-n=\"2550\">13</sup> דבל\"ג בעומר הוא מתן תורה<sup data-n=\"2551\">14</sup> דפנימיות התורה, בדוגמת חג השבועות שהוא זמן מתן תורה בכלל. דמזה מובן, דכמו שמתן תורה בחג השבועות הוא בכל שנה ושנה, כמו\"כ מתן תורה דפנימיות התורה בל\"ג בעומר הוא בכל שנה ושנה. וזהו שענין ל\"ג בעומר מרומז בפסוק גל עיני ואביטה נפלאות מתורתך, כי נפלאות שבתורה הוא <i>פנימיות</i> התורה<sup data-n=\"2552\">15</sup>, וענין גל גו' נפלאות הוא גילוי (גל מלשון גילוי<sup data-n=\"2553\">16</sup>) הנפלאות דתורה (פנימיות התורה) שנמשך בג\"ל (בל\"ג בעומר).\nג) <b>ומבאר</b> בהמאמר<sup data-n=\"2554\">17</sup>, דבנפלאות שבתורה (פנימיות התורה) שתי דרגות. והענין הוא, דאיתא בזהר<sup data-n=\"2555\">18</sup> שבתורה יש לבוש, גוף, נשמה ונשמה לנשמה. גליא דתורה הוא הלבוש והגוף דתורה [הסיפורים דתורה – לבוש, וההלכות דתורה – הגוף], והנשמה דתורה היא פנימיות התורה, שנחלקת בכללות לשתי דרגות. רזין דאורייתא (סתים) – נשמתא, ורזין דרזין (סתימא דכל סתימין) – נשמתא לנשמתא. והבקשה גל עיני ואביטה נפלאות מתורתך (נפלאות לשון רבים) היא שיראה את שתי הדרגות דנפלאות שבתורה, רזין ורזין דרזין. ומבאר, שנשמתא היא בחינת נר\"ן, ונשמתא לנשמתא היא בחינת ח\"י. ואולי יש לומר, שהענינים דפנימיות התורה שגילה רשב\"י במשך כל ימי חייו<sup data-n=\"2556\">19</sup> הם בחינת נשמתא דאורייתא, והענינים שגילה ביום הסתלקותו<sup data-n=\"2556\">19</sup> הם בחינת נשמתא לנשמתא.<b>והנה</b> ברשימות הצ\"צ לתהלים עה\"פ גל עיני ואביטה נפלאות מתורתך<sup data-n=\"2557\">20</sup> מביא מאמר הזהר הנ\"ל שבתורה יש לבושא וגופא ונשמתא ונשמתא לנשמתא, ומבאר, שהבקשה גל עיני ואביטה נפלאות היא שיראה לא רק הלבוש לבד אלא גם נשמתא. ובהמשך הענין מביא פירוש השל\"ה<sup data-n=\"2558\">21</sup> דאביטה נפלאות הוא כוונת המצוות. ולאחרי שמביא פירוש השל\"ה ממשיך לבאר שנפלאות הוא פנימיות התורה, נשמתא דאורייתא. וצריך להבין, דלכאורה הי' צריך תחלה לסיים ביאור הפירוש שנפלאות הוא נשמתא דאורייתא <i>ולאח\"ז</i> להביא <i>עוד</i> פירוש שנפלאות הוא כוונת המצוות, ומזה שמביא פירוש זה באמצע הביאור שנפלאות הוא נשמתא דאורייתא, משמע, שהפירוש שנפלאות הוא כוונת המצוות נוגע לביאור והבנת הפירוש דאביטה נפלאות הוא שיראה נשמתא דאורייתא.\nד) <b>ויובן</b> זה בהקדים מ\"ש גל עיני גו' שמבקש מהקב\"ה שיפקח את עיניו, דלכאורה, כיון שהסיבה לזה שע\"ד הרגיל אין רואים את הנפלאות דתורה הוא (לא מצד החסרון דהכלים, אלא) לפי <i>שהנפלאות</i> הם מכוסים ונעלמים [ויש לומר, שההעלם דבחינת נשמתא דאורייתא הוא מפני שהיא מלובשת בהגוף דתורה (גליא דתורה) שמעלים על הנשמה, וההעלם דבחינת נשמתא לנשמתא דאורייתא הוא (לא שהיא מלובשת באיזה דבר שמעלים עלי', אלא) שמצד עצמה היא בהעלם, העלם שלמעלה מגילוי], הוה לי' לבקש שהקב\"ה יגלה את <i>הנפלאות דתורה</i><sup data-n=\"2559\">22</sup>, ומהי הבקשה גל <i>עיני</i> שהקב\"ה יפקח את עיניו. ונקודת הביאור בזה, ע\"פ מה דאיתא במדרש<sup data-n=\"2560\">23</sup>, משל למלך שגזר ואמר בני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי, כך כשברא הקב\"ה את העולם גזר ואמר השמים שמים לה' והארץ נתן לבני אדם<sup data-n=\"2561\">24</sup>, כשביקש ליתן התורה ביטל הגזירה ואמר התחתונים יעלו לעליונים והעליונים ירדו לתחתונים, ואני המתחיל, שנאמר<sup data-n=\"2562\">25</sup> וירד הוי' על הר סיני וכתיב<sup data-n=\"2563\">26</sup> ואל משה אמר עלה אל הוי'. ומבואר במק\"א<sup data-n=\"2564\">27</sup>, דהטעם שאומר התחתונים יעלו לעליונים לפני והעליונים ירדו לתחתונים, אף שירידת העליונים למטה היתה קודם, אני המתחיל, הוא, כי תכלית הכוונה דמתן תורה הוא התחתונים יעלו לעליונים [שיהיו כלי לגילוי אלקות, ויתירה מזה שגם המשכת הגילוי בהם תהי' מצד ענינם וע\"י עבודתם], אלא שבכדי שיוכל להיות עליית התחתונים למעלה הוא ע\"י ירידת העליונים למטה, שהיא ההתחלה והנתינת כח על עליית התחתונים למעלה. ועד\"ז הוא במתן תורה דפנימיות התורה שבל\"ג בעומר, שהכוונה בביטול הגזירה והמחיצה בין עליונים ותחתונים בנוגע לפנימיות התורה היא, שהגילוידפנימיות התורה שנמשך להאדם יהי' (גם) מצד האדם. וזהו גל <i>עיני</i> ואביטה נפלאות מתורתך, שהקב\"ה יפקח את עיני האדם ויראה את הנפלאות שבתורה (לא רק ע\"י שהנפלאות יהיו בגילוי, אלא גם) מצד ענינו של האדם.\n<b>ועפ\"ז</b> יש לבאר מ\"ש בהמאמר<sup data-n=\"2565\">28</sup> דפירוש גל עיני ואביטה נפלאות <i>מתורתך</i> הוא שראיית הנפלאות דתורה (נשמתא דאורייתא ונשמתא לנשמתא) תהי' מתורתך, מתורה הנגלית, דלכאורה, הרי העיקר הוא שיראה הנפלאות דתורה, ומהו היתרון בזה שיראה אותם ע\"י הענינים שבגליא דתורה. ויש לומר הביאור בזה, דכל הענינים שבעולם ושבאדם, התחלתם הוא בתורה<sup data-n=\"2566\">29</sup>. ולכן, ע\"י שראיית הנפלאות דתורה (דהאדם) היא ע\"י ענינים אלה שבגליא דתורה, היינו שהגוף והלבוש דתורה <i>עצמו</i> מגלה את הנשמה והנשמה לנשמה דתורה, עי\"ז נעשה עד\"ז גם בהאדם העוסק בתורה, דזה שרואה את הנפלאות דתורה הוא (גם) מצד ענינו דהאדם.\nה) <b>והנה</b> שני הענינים הנ\"ל שבביטול הגזירה והמחיצה בין עליונים לתחתונים שנתחדשו במתן תורה הם בכללות יותר תורה ומצוות. דענין ירידת העליונים למטה שנתחדש במתן תורה הוא בעיקר בתורה, וענין עליית התחתונים למעלה שנתחדש במתן תורה הוא בעיקר במצוות<sup data-n=\"2567\">30</sup>. והענין הוא, דמהחילוקים בין תורה למצוות הוא<sup data-n=\"2568\">31</sup>, דהתורה היא <i>דבר ה'</i>, חכמתו של הקב\"ה, אלא שירדה למטה ונתלבשה בשכל אנושי בכדי שהאדם יוכל להבינה ולהשיגה, והמצוות שהם ציוויים <i>להאדם</i>, הכוונה והמבוקש בהם היא (לא הציווי עצמו, אלא) <i>קיום</i> הציווי <i>שהאדם</i> מקיים. וזהו שהענין דירידת העליונים למטה הוא בעיקר בתורה, דהתורה, שהיא חכמתו של הקב\"ה, מקומה למעלה<sup data-n=\"2569\">32</sup>, וזה שהתורה ניתנה למטה ונתלבשה בשכל אנושי ובדברים גשמיים הו\"ע ירידת העליונים לתחתונים (משא\"כ בנתינת המצוות למטה אין מודגש כ\"כ הענין דירידת העליונים למטה, שהרי אדרבה, ענינם של המצוות (ציוויים) הוא <i>שהאדם</i> יקיים אותם). וענין התחתונים יעלו לעליונים הוא בעיקר במצוות. דבתורה, כיון שגם לאחרי שירדה למטה היא <i>דבר ה'</i>, לכן, גם בלימוד ועסק התורה דהאדם נרגש בעיקר ההמשכה מלמעלה, שהתורה שהיא חכמתו של הקב\"ה נמשכת ומתלבשת בשכלו של האדם, ולא הבירור והזיכוך דשכל האדם. והענין שהתחתונים יעלו לעליונים מודגש בעיקר במצוות, דכיון שענין המצוות (ציוויים) הוא <i>שהאדם</i> יקיים את המצוות (כנ\"ל), והכוונה בזה היא בכדי לצרף את הבריות<sup data-n=\"2570\">33</sup>, בכדי לברר ולזכך ולהעלות הכחות והאברים של האדם שמקיים את המצוה וגם את הדברים שבעולם שבהם מקיימים את המצוה ולעשותם כלים לאלקות, ענין המצוות הוא עליית התחתונים למעלה.<b>וע\"פ</b> מה שנתבאר לעיל (סעיף ד) שעיקר הכוונה בביטול הגזירה דמתן תורה הוא שהתחתונים יעלו למעלה, וכמו\"כ הוא בנוגע לביטול הגזירה והמחיצה בנוגע לפנימיות התורה (גל עיני ואביטה נפלאות מתורתך) שהעיקר הוא העלי' מלמטלמ\"ע, צריך לומר, דבאביטה נפלאות מתורתך נכלל גם ענין המצוות כמו שהם מצד נשמתא דאורייתא. ולכן מביא הצ\"צ פירוש השל\"ה דנפלאות מתורתך הם כוונת המצוות. והענין הוא, דבכדי שקיום המצוות יהי' כדבעי הוא ע\"י לימוד התורה, דתלמוד מביא לידי מעשה<sup data-n=\"2571\">34</sup>. ויש לומר, דבכדי שמעשה המצוה (הגוף של המצוה<sup data-n=\"2572\">35</sup>) יהי' כדבעי הוא ע\"י לימוד גליא דתורה (הגוף דתורה), ובכדי שכוונת המצוות (הנשמה דהמצוות<sup data-n=\"2572\">35</sup>) תהי' כדבעי הוא ע\"י לימוד פנימיות התורה (נשמתא דאורייתא).\nו) <b>והנה</b> כמו שבלימוד התורה (אפילו בנגלה דתורה, ומכש\"כ בפנימיות התורה) יש ריבוי מדריגות עד אין קץ, כמו\"כ הוא בקיום המצוות, אפילו במעשה המצוות ומכש\"כ בכוונת המצוות, שיש בזה ריבוי מדריגות. ועפ\"ז יובן מה שידוע<sup data-n=\"2573\">36</sup> שממעשה המצוות נעשים לבושים להנשמה בג\"ע התחתון ומכוונת המצוות נעשים לבושים בג\"ע העליון, דלכאורה, הרי גם בג\"ע התחתון עצמו, וכן בג\"ע העליון עצמו, יש ריבוי מדריגות<sup data-n=\"2574\">37</sup>, ואיך אפשר שבכל המדריגות יהיו אותם הלבושים. והביאור בזה, דבמעשה המצוות וכן בכוונת המצוות יש ריבוי מדריגות כנ\"ל.\n<b>והנה</b> הגם שכוונת המצוה היא נשמת המצוה ששייכת בכלל לנשמתא דאורייתא, מ\"מ, כו\"כ ענינים דכוונת המצוות הם גם בנגלה דתורה. הן בנוגע הכוונה הכללית<sup data-n=\"2575\">38</sup> דמצוות (שבכל המצוות בשוה) לקיים רצון ה' – דכוונה זו היא גם ע\"פ נגלה דתורה (אלא שע\"י לימוד פנימיות התורה, הכוונה והרצון דהאדם לקיים רצון ה' הוא באופן נעלה יותר<sup data-n=\"2576\">39</sup>), וגם הכוונות הפרטיות<sup data-n=\"2575\">38</sup> שבכל מצוה בפרט, הרי הטעם והכוונה דכו\"כ מצוות נתפרש גם בנגלה דתורה, גם ע\"פ דרך הפשט [ועד שהטעם דכו\"כ מצוות מפורש בקרא], ומכש\"כ ע\"פ דרך הרמז והדרוש, אלא שהטעם והכוונה דהמצוות שע\"פ דרך הסוד (פנימיות התורה) הוא נעלה הרבה יותר, ועי\"ז מיתוסף עומק וכו' גם בהטעם שע\"פ נגלה. ויש לומר, דכמו שבנוגע לראיית הנפלאות דתורה, הבקשה גל עיני ואביטה נפלאות מתורתך היא שראיית הנפלאות דתורה (נשמתא ונשמתא לנשמתא) תהי' <i>מתורתך</i>, מענינים אלה שבגליא דתורה, מהגוף דתורה וגם מהלבוש דתורה (כנ\"ל סעיף ד), עד\"ז הוא בנוגע לכוונת המצוות, שהנפלאות דכוונתהמצוות [כוונות האריז\"ל, ולמעלה יותר] צריכים לראותם מתוך הכוונות שע\"ד הפשט, ויתרה מזה – מתוך הכוונות ע\"ד הפשט המובנים לבן חמש למקרא [שהם דוגמת לבושא דאורייתא, הסיפורים דתורה, שגם תינוקות לומדים אותם].\nז) <b>ולהוסיף</b><b>,</b> דבכוונת המצוות, נוגע ענין זה [שענינים הכי נעלים ידעו מענינים אלה כמו שהם בפשטות] עוד יותר מאשר בתורה. כי היתרון בזה שידיעת הנפלאות היא מהענינים שבפשטות הוא שעי\"ז תהי' ידיעת הנפלאות דהאדם גם מצד עני<i>נו</i> (כנ\"ל סעיף ד), וכיון שענין המצוות הוא לצרף בהן את הבריות (כנ\"ל סעיף ה), לפעול בירור וזיכוך בהאדם המקיים את המצוה, [דעיקר הבירור והזיכוך הוא ע\"י כוונת המצוות<sup data-n=\"2577\">40</sup>, וכל שהכוונה היא נעלית יותר, הבירור והזיכוך הוא נעלה יותר], לכן, בענין המצוות נוגע עוד יותר שידיעת הנפלאות דכוונת המצוות תהי' מתוך הכוונות שבפשטות. ועפ\"ז יש לבאר מה שמביא הצ\"צ במאמר שרש מצות התפלה<sup data-n=\"2578\">41</sup> הלשון אני מתפלל לדעת זה התינוק. דלכאורה, במאמר שרש מצות התפלה מבאר ענין התפלה [בכלל, וגם כמה ענינים פרטיים דתפלה] ע\"פ קבלה, ועוד יותר – ע\"פ חסידות, ומה מקום במאמר זה להביא הענין דאני מתפלל לדעת זה התינוק. ויש לומר, שבזה מרמז, שהכוונות דתפלה בדרגות הכי נעלות צריכות להיות קשורות עם ענין התפלה כמו שהיא לדעת התינוק, הן בנוגע לכללות ענין התפלה – שידיעת ענין התפלה בדרגות הכי נעלות תהי' גם מענין התפלה כמו שתינוק מבין, והן בנוגע לביאור הענינים (הפסוקים, בקשות וכו') שאומרים בתפלה, שהביאורים הכי נעלים צריכים להיות בהתאם [ועד שידיעתם תהי' מתוך] פירוש המילות דתפלה כמו שתינוק מבין. והגם שענין זה הוא בכל הענינים שבתורה, מ\"מ, כיון שענין התפלה היא העלאה מלמטה למעלה, בירור וזיכוך <i>האדם</i>, לכן בתפלה ענין זה נוגע יותר (ע\"ד שנתבאר לעיל בנוגע למצוות). ולכן, במאמר שרש מצות <i>התפלה</i> מובא הענין דאני מתפלל לדעת זה התינוק.\nח) <b>וזהו</b> הקשר דשני הפסוקים שבהם מרומז הענין דל\"ג בעומר, גל עיני ואביטה נפלאות מתורתך ועד הגל הזה, כי הגל שבין לבן ליעקב הוא דוגמת הגזירה והמחיצה בין העליונים להתחתונים שהיתה קודם מתן תורה. ומבואר בסידור שער הל\"ג בעומר<sup data-n=\"2579\">42</sup>, דבהגל שבין לבן ליעקב, שני ענינים. הגל שבין לבן העליון (שלמעלה מיעקב) ליעקב, והוא הפרסא שבין עולמות הא\"ס שלמעלה מאצילות ואצילות. והגל שבין יעקב ולבן התחתון, הפרסא שבין אצילות לבי\"ע. והרמז דל\"ג בעומר בפסוק זה הוא, שע\"י רשב\"י נתברר הגל והמחיצה<sup data-n=\"2580\">43</sup>, המחיצה שבין לבן העליון ליעקב וגם המחיצה שבין יעקב ללבן התחתון. היינו, שגם בבי\"ע ועד בעולם העשי' יהי' גילוי האצילות וגם גילוי האוא\"ס שלמעלה מאצילות. וענין זה הוא גםהתוכן דפסוק השני שמרמז על ל\"ג בעומר, גל עיני ואביטה נפלאות מתורתך, שגם בענינים שבנגלה דתורה (בי\"ע), וגם בלבושא דאורייתא, בהסיפורים דתורה (עשי'<sup data-n=\"2581\">44</sup>), יהי' בגילוי הנפלאות דתורה, בחי' נשמתא דאורייתא (אצילות) וגם בחי' נשמתא דנשמתא (למעלה מאצילות).\nט) <b>ולהוסיף</b><b>,</b> דע\"פ הידוע שכל הענינים שבתורה הם בתכלית הדיוק, צריך לומר, דזה שהפסוק עד הגל הזה [שמדבר בענין <i>הגל והמחיצה</i> שבין לבן ליעקב] מרמז על ל\"ג בעומר שענינו הוא <i>בירור</i> הגל והמחיצה, הוא, כי זה שהסימן והעדות על אני לא אעבור אליך גו' אתה לא תעבור אלי גו'&lt;4&gt; הי' שעשו גל, ולא שעשו חומה, הוא לרמז שעשיית המחיצה מלכתחילה היא באופן שיש נתינת מקום שיהי' אני <i>אעבור</i> אליך ואתה תעבור אלי<sup data-n=\"2582\">45</sup>. והיינו, שהכוונה בעשיית המחיצה בין העליונים והתחתונים מלכתחילה היא בכדי שאח\"כ יהי' <i>החיבור</i> דעליונים ותחתונים. וזה שבתחלה הי' צריך להיות המחיצה בין העליונים להתחתונים, הוא, כי הכוונה דדירה בתחתונים היא שהדירה תהי' בתחתון שאין תחתון למטה ממנו<sup data-n=\"2583\">46</sup>, ולכן היתה התהוות התחתונים ע\"י מחיצה, דלא רק שבפועל אין מאיר בהם הגילוי דהעליונים אלא שישנה <i>מחיצה</i> ביניהם שהוא סימן ועדות שיהי' <i>לא</i> אעבור אליך <i>ולא</i> תעבור אלי<sup data-n=\"2584\">47</sup>, בכדי שע\"י העבודה דישראל יהי' החיבור גם דתחתונים אלה [שיש <i>גזירה</i><sup data-n=\"2585\">48</sup> שלא יתחברו עם העליונים] עם העליונים. וזהו שהרמז דל\"ג בעומר הוא בפסוק עד הגל הזה, כי זה שרשב\"י בירר הגל והמחיצה הוא שעל ידו נתגלה ענין הפנימי דהצמצום עצמו<sup data-n=\"2586\">49</sup>, שהכוונה בהצמצום [שהיא ענינו הפנימי] היא בשביל הגילוי.\n<b>וזהו</b> שהרמז דל\"ג בעומר בפסוק גל עיני ואביטה נפלאות מתורתך למדין מהרמז דל\"ג בעומר שבפסוק עד הגל הזה, כי עיקר החידוש והעילוי דגל עיני ואביטה נפלאות מתורתך הוא שראיית הנפלאות דתורה תהי' (לא רק מפני <i>שהנפלאות</i> יהיו בגילוי, אלא) ע\"י גל <i>עיני</i>, שהקב\"ה יפקח את עיני האדם ויראה האדם את הנפלאות דתורה מצד ענינו של האדם (כנ\"ל סעיף ד), ובכדי שהאדם התחתון יוכל לראות הנפלאות דתורה מצד ענינו, הוא ע\"י הענין דל\"ג בעומר המרומז בעד הגל הזה – גילוי ענינו הפנימי דהצמצום, שהצמצום הוא בשביל הגילוי.\nיו\"ד) <b>וע\"י</b> לימוד והפצת פנימיות התורה, תורתו של רשב\"י, ובפרט כמו שנתגלתה בתורת החסידות, גילוי באופן דיתפרנסון, הבנה והשגה, ועד שהשכלדהאדם הלומד נעשה חד עם הענין שלומד<sup data-n=\"2587\">50</sup> [שהוא ע\"ד המבואר לעיל בענין גל עיני, שראיית הנפלאות דתורה היא מצד ענינו של האדם עצמו], זוכים לגילוי פנימיות התורה שיהי' לע\"ל, שהגילוי אז יהי' נוסף על מצד מלמעלה אלא שזה יהי' ענינו דהעולם, כמ\"ש הרמב\"ם<sup data-n=\"2588\">51</sup> ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד כו'<sup data-n=\"2589\">52</sup> שנאמר<sup data-n=\"2590\">53</sup> כי מלאה הארץ דיעה את ה' כמים לים מכסים, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, בקרוב ממש.\n**********",[["2537","*","יצא לאור ב<b>קונטרס ל\"ג בעומר – תנש\"א</b>, \"לקראת ל\"ג בעומר . . <i>יום ה'</i>,<i> ל\"ג בעומר</i>,<i> ה'תנש\"א</i>\"."],["2538","1","תהלים קיט, יח."],["2539","2","שבהמשך חייב אדם לברך תרל\"ח פכ\"ג (ע' לט ואילך)*. וראה שם פכ\"ה (ע' מא)."],["2540","3","ד\"ה עד הגל הזה (דש, ג ואילך)."],["2541","4","ויצא לא, נב."],["2542","5","סידור שם (דש, סע\"ב). ד\"ה לה\"ע הילולא דרשב\"י עטר\"ת (סה\"מ עטר\"ת ס\"ע תיט ואילך). ועוד."],["2543","6","מובן בפשטות, שבמתן תורה [שהי' ע\"י משה רבינו] <i>ניתן</i> גם פנימיות התורה**, אלא <i>שהגילוי</i> דפנימיות התורה הי' ע\"י רשב\"י."],["2544","7","אד\"ז בזח\"ג רפד, ב."],["2545","8","ראה אד\"ז שם (רצא, סע\"א) \"מלין <i>דדחילנא</i> לגלאה\"."],["2546","9","ראה אד\"ז שם (רפד, ב) \"ר' אבא יכתוב\". ויש לומר, דמהטעמים שצוה לכתוב הדברים שאמר אז דוקא, הוא, כי בענינים נעלים צריך פעולה מיוחדת שיהיו שייכים להעולם."],["2547","10","ראה תקו\"ז ת\"ו בסופו \"כמה ב\"נ לתתא <i>יתפרנסון</i> מהאי חיבורא דילך כו'\". ובכסא מלך שם, דפירוש \"יתפרנסון\" הוא \"<i>יפורשו</i> מאמריו העמוקים כו' <i>שיבינו</i> כו'\". וראה לקו\"ש ח\"ג ע' 873."],["2548","11","ראה סידור שם (דש, סע\"א ואילך). וראה אגה\"ק ביאור לסימן ז\"ך (קמז, סע\"א) וסימן כח (קמח, א).\n*) <i>ראה ב</i>\"<i>מפתח</i>\"<i> לההמשך</i>,<i> שפרקים כג-כה דההמשך הם מאמר בפני עצמו</i>.<i> ולהעיר</i>,<i> שלכאורה</i>,<i> התחלת המאמר הוא </i>\"<i>גל עיני</i>\",<i> אלא שניתוסף בתחילתו </i>\"<i>וזהו שאמר דהע\"ה</i>\"<i> בכדי לקשרו עם המאמרים שלפניו</i>.\n**) <i>כולל גם פנימיות התורה שתתגלה לע\"ל</i>.<i> וכידוע שמתן תורה לא יהי' עוד הפעם (סה\"מ תרנ\"ו ע' שנו</i>.<i> המשך תרס\"ו ע' כג</i>.<i> שם ע' תקמו</i>.<i> תער\"ב ח\"א ע' שסו</i>.<i> סה\"מ עטר\"ת ע' רצא</i>.<i> תרפ\"ה ע' קצט</i>.<i> ה'תש\"ט ע' 57</i>.<i> ועוד)</i>."],["2549","12","ראה סה\"מ ה'תש\"ד ע' 13 ואילך. ובכ\"מ."],["2550","13","המשך תרס\"ו ע' ריט. סה\"מ ה'תש\"ד ע' 211."],["2551","14","כ\"ה הלשון (\"מתן תורה\") בהמשך תרס\"ו שם. ובסה\"מ ה'תש\"ד שם \"הנתינה דפני' התורה\". ולכאורה הכוונה היא <i>להגילוי</i> דפני' התורה – ראה לעיל הערה 6."],["2552","15","ראה הקדמת הרמב\"ם לפירוש המשניות (ד\"ה אחר כן ראה), דאביטה נפלאות הו\"ע דבש וחלב תחת לשונך* (שה\"ש ד, יא), ובמס' חגיגה (יג, א)** דדבש וחלב הו\"ע מעשה מרכבה – אוה\"ת (יהל אור) לתהלים עה\"פ (ע' תסא)."],["2553","16","מצודת ציון עה\"פ (תהלים קיט, יח)."],["2554","17","פכ\"ג (ע' לט)."],["2555","18","ח\"ג קנב, א."],["2556","19","מהחילוקים בין נר\"נ (נשמתא) לח\"י (נשמתא לנשמתא) הוא, דנר\"נ הם מלובשים בגוף וח\"י הם למעלה מהתלבשות בגוף. ויש לומר, דענין ההסתלקות הוא שהנשמה יוצאת מהגבלת כלי הגוף, דבכללות הו\"ע ח\"י שלמעלה מהתלבשות בגוף. וכאשר רשב\"י \"<i>בעא</i> לאסתלקא מן עלמא\" (לשון הזהר שבהערה 7), (הגם שנשמתו היתה בהתלבשות בהגוף), האירה אצלו בחינה זו, ולכן גילה אז בחינת נשמתא דנשמתא (שבתורה).\n*) <i>בפיה\"מ להרמב\"ם שם </i>\"<i>ולגלות לו הסודות הגנוזות כו' ואביטה נפלאות</i>\".<i> ויש לומר</i>,<i> דב</i>\"<i>סודות הגנוזות</i>\"<i> נכלל גם מעשה בראשית [כיון שאין דורשין בהם ברבים</i>,<i> רמב\"ם הל' יסודי התורה פ\"ד ה\"י]</i>,<i> ולכן מביא הצ\"צ מ\"ש הרמב\"ם דנפלאות הו\"ע דבש וחלב שקאי על מעשה מרכבה</i>.\n**) <i>וראה גם רמב\"ם הל' יסודי התורה ספ\"ב</i>."],["2557","20","אוה\"ת (יהל אור) לתהלים ס\"ע תנט ואילך."],["2558","21","בתחלתו (ב, א)."],["2559","22","וכמו \"אראנו נפלאות\" (מיכה ז, טו) שהקב\"ה יראה את <i>הנפלאות</i>. ולהעיר מהמבואר באוה\"ת לתהלים שם ובהמשך הנ\"ל שם פכ\"ה, דאביטה נפלאות הוא כענין \"אראנו נפלאות\"."],["2560","23","תנחומא וארא טו. שמו\"ר פי\"ב, ג. ועוד."],["2561","24","תהלים קטו, טז."],["2562","25","יתרו יט, כ."],["2563","26","משפטים כד, א."],["2564","27","לקו\"ש ח\"ח ע' 23."],["2565","28","פכ\"ג (ריש ע' מ)."],["2566","29","ע\"ד אסתכל באורייתא וברא עלמא (זח\"ב קסא, א-ב)."],["2567","30","להעיר מהידוע (תו\"א בתחלתו (ושם ב, א). ובכ\"מ. ובארוכה בלקו\"ש ח\"ט ע' 65) דתורה היא המשכה מלמעלמ\"ט ומצוות העלאה מלמטלמ\"ע."],["2568","31","ראה ספר השיחות תשמ\"ח ח\"א ע' 213. ח\"ב ע' 666."],["2569","32","וראה תניא פ\"ד (ח, ב) \"התורה ירדה ממקום כבודה כו'\"."],["2570","33","ב\"ר רפמ\"ד. וש\"נ."],["2571","34","קידושין מ, ב. ב\"ק יז, א."],["2572","35","ראה תניא רפל\"ח. של\"ה רמט, סע\"ב. וראה בהנסמן במפתח פסוקים ומחז\"ל בתניא (קה\"ת תשמ\"ה) ע' צ הערה 11."],["2573","36","אגה\"ק סכ\"ט (קנ, ב). תו\"א שמות נג, ג. ובכ\"מ."],["2574","37","תו\"א מקץ לב, ד. ובכ\"מ. וראה בהנסמן לעיל ע' רכד הערה 36."],["2575","38","ראה לקמן ח\"ד ע' טו, ובהנסמן שם הערה 25, שבקיום המצוות צ\"ל שתי כוונות, כוונה כללית וכוונה פרטית."],["2576","39","להעיר מתניא פל\"ט (נג, ב) \"כמו שאין אדם עושה דבר בשביל חבירו למלאות רצונו אא\"כ אוהבו או ירא ממנו, כך אי אפשר לעשות לשמו ית' באמת למלאות רצונו לבד בלי זכרון והתעוררות אהבתו ויראתו\" – והדרך לבוא לאהבתו ויראתו היא לימוד פנימיות התורה (כמובן גם מרמב\"ם הל' יסודי התורה פ\"ב ה\"ב)."],["2577","40","להעיר מסה\"מ ה'תש\"ב ע' 53."],["2578","41","פ\"ח (בסהמ\"צ להצ\"צ קיח, א)."],["2579","42","דש, ג ואילך. וראה בארוכה תו\"ח ויצא לז, א ואילך. המשך תער\"ב ח\"א פק\"ז (ע' רו) ואילך."],["2580","43","המשך חייב אדם לברך תרל\"ח הנ\"ל פכ\"ה (ע' מב). ושם, שזהו ע\"ד ענין מחצתי ואני ארפא (האזינו לב, לט. וראה קה\"ר פ\"א, ד) שיהי' לע\"ל."],["2581","44","ראה לקו\"ת ויקרא (ה, סע\"א) מפע\"ח (שער הנהגת הלימוד), שתלמוד ומשנה הם בבריאה וביצירה, ומקרא הוא בעשי'. ובהמשך הענין שם (ה, ב), שהסיפורים דתורה הם \"דברים שלא ניתנו להתלבש למטה בחכמה ושכל כלל\". ומזה מובן, שעיקר הענין ד\"מקרא בעשי'\" הוא <i>בהסיפורים</i> דתורה שבכתב."],["2582","45","ראה גם לקו\"ש ח\"ה ע' 136. ושם, דזה שיש נתינת מקום שיהי' \"אעבור\" ו\"תעבור\" התנו <i>בפירוש</i> בהדיבור שלהם בענין הגל – לא תעבור גו' <i>לרעה</i>, ובפי' רש\"י שם: אבל אתה עובר לפרקמטיא."],["2583","46","תניא רפל\"ו."],["2584","47","ובלשון המדרש (הובא לעיל ס\"ד) \"<i>שגזר</i> ואמר בני רומי לא ירדו לסוריא ובני סוריא לא יעלו לרומי\"."],["2585","48","ראה הערה הקודמת."],["2586","49","ראה המשך תער\"ב ח\"ב ס\"ע תתקלב ואילך. לעיל ס\"ע קצג ואילך. ובכ\"מ."],["2587","50","ראה תניא פ\"ה (ט, ב)."],["2588","51","בסיום וחותם ספרו."],["2589","52","היינו, שזה (ידיעת ה') הוא העסק (והענין) דהעולם."],["2590","53","ישעי' יא, ט."]]],[1500380046,"<h3>בס\"ד. ש\"פ במדבר, מבה\"ח וער\"ח סיון ה'תשכ\"ט<sup data-n=\"2591\">*</sup></h3>\n<b>בחודש</b> השלישי לצאת בני ישראל מארץ מצרים ביום הזה באו מדבר סיני<sup data-n=\"2592\">1</sup>, ואיתא בגמרא<sup data-n=\"2593\">2</sup>, כתיב הכא ביום הזה באו מדבר סיני וכתיב התם<sup data-n=\"2594\">3</sup> החודש הזה לכם ראש חדשים, מה להלן ראש חודש אף כאן ראש חודש. והקשו בתוספות<sup data-n=\"2595\">4</sup>, דבמס' פסחים<sup data-n=\"2596\">5</sup> איתא (עה\"פ<sup data-n=\"2597\">6</sup> וידבר ה' אל משה במדבר סיני בשנה השנית גו' בחודש הראשון), אתיא מדבר ממדבר, כתיב הכא במדבר סיני וכתיב התם<sup data-n=\"2598\">7</sup> וידבר ה' אל משה במדבר סיני באוהל מועד באחד לחודש השני, מה להלן בר\"ח אף כאן בר\"ח, וכיון שגם בפסוק בחודש השלישי כתיב מדבר, אמאי לא יליף הכא מדבר ממדבר. וצריך להבין, דלכאורה, הילפותא מהגז\"ש הזה הזה מגלה שפירוש ביום הזה הוא בר\"ח, משא\"כ באם היו למדין מהגז\"ש מדבר מדבר [שהלימוד הוא רק שהענין שנאמר בכתוב (באו מדבר סיני) הי' בר\"ח] לא הי' מובן הפירוש דביום הזה [ועוד יתרון בהגז\"ש הזה הזה על הגז\"ש מדבר מדבר, כי החודש הזה פירושו הוא ר\"ח<sup data-n=\"2599\">8</sup>, משא\"כ מדבר סיני ואחד לחודש (ר\"ח) הם שני ענינים]<sup data-n=\"2600\">9</sup>, ומהי סברת התוספות דהוה לי' למילף מדבר ממדבר<sup data-n=\"2601\">10</sup>.\nב) <b>ויובן</b> זה ע\"פ המבואר בתו\"א ד\"ה זה<sup data-n=\"2602\">11</sup>, דעיקר<sup data-n=\"2603\">12</sup> קבלת התורה הוא כמ\"ש (בהתחלת הענין דמ\"ת<sup data-n=\"2604\">13</sup>) וידבר אלקים את כל הדברים האלה לאמר, דפירוש תיבת לאמר בפסוק זה הוא שבשעת מתן תורה ניתן הכח לכל אחד מישראל,שלימוד התורה שלו [כל הדברים האלה, שקאי גם על כל התורה כולה<sup data-n=\"2605\">14</sup>] יהי' באופן דלאמר, לחזור הדברים שהקב\"ה אומר, כמ\"ש<sup data-n=\"2606\">15</sup> תען לשוני אמרתך, שהתורה היא אמרתך, שלשוני תען כעונה אחר האומר. וזוהי השייכות דמתן תורה לחג השבועות, דבחג השבועות הוא המשכת הכתר [וכידוע<sup data-n=\"2607\">16</sup> בפירוש הכתוב<sup data-n=\"2608\">17</sup> תספרו חמישים יום, שבחג השבועות נמשך שער הנו\"ן דבינה, ושער הנו\"ן הוא הכתר<sup data-n=\"2609\">18</sup>], וזה שבמ\"ת ניתן הכח שלימוד התורה דישראל יהי' בתכלית הביטול, שאינו מציאות לעצמו כלל והוא רק כעונה אחר הקורא, הוא לפי שבמ\"ת נמשך גילוי הכתר.\n<b>וזהו</b> בחודש השלישי גו' ביום הזה באו מדבר סיני, שבר\"ח סיון היתה ההכנה לקבלת התורה, כי בר\"ח הוא מולד הלבנה, שאז (בעת המולד) היא נקודה בלבד, וזה מורה על הביטול שלה, דלית לה מגרמה כלום<sup data-n=\"2610\">19</sup>. וכן הוא בישראל שדומין ומונין ללבנה<sup data-n=\"2611\">20</sup>, שבר\"ח הוא זמן המוכשר לגלות כח הביטול שישנו בכ\"א מישראל. ולכן בר\"ח סיון הוא ההכנה לקבלת התורה, שלימוד התורה דהאדם יהי' בביטול, כעונה אחר הקורא.\nג) <b>וממשיך</b> בהמאמר עוד ביאור בזה שבר\"ח סיון הוא ההכנה לקבלת התורה, דבצאת ישראל ממצרים התחילו לספור ספירת העומר<sup data-n=\"2612\">21</sup>, שהיא הכנה לקבלת התורה, וז' השבועות דספירת העומר (שבעה שבועות תספר לך<sup data-n=\"2613\">22</sup>) הם כנגד ז' המדות, ובר\"ח סיון שהוא יום הג' דשבוע הז' ישנם כבר ג' המדות חג\"ת (שהם עיקרי המדות) דספירת המלכות, וכאילו שישנו כבר כל שבוע הז', ולכן בר\"ח סיון באו מדבר סיני כי אז נשלם עיקר ההכנה למ\"ת.\n<b>ויש</b> לומר, דזה שמבאר בהמאמר שני ביאורים בזה שבר\"ח סיון הוא ההכנה לקבלת התורה, הוא, כי בההכנה לקבלת התורה שני ענינים. השלימות דהאדם, שבכדי שיהי' ראוי לקבל התורה צריך להיות בתכלית השלימות<sup data-n=\"2614\">23</sup>. והביטול שלו. דכיון שהתורה היא למעלה באין ערוך מהאדם (במכ\"ש מזה שהיא למעלה מעולמות העליונים), לכן, כאשר האדם הוא מציאות, המציאות שלו היא (כמו) היפך התורה<sup data-n=\"2615\">24</sup>, ובכדי שהאדם יקבל את התורה הוא ע\"י הביטול שלו. ולכן מבאר בהמאמר, דזה שבר\"ח סיון באו מדבר סיני והיו מוכנים לקבל התורה, הוא, כי בר\"ח סיון ישנם שניהענינים. זה שבר\"ח הוא מולד הלבנה, שאז היא נקודה בלבד, ביטול. וזה שבר\"ח סיון נשלמו עיקרי המדות (גם) בספירת המלכות – שלימות האדם. ושני ענינים בהשלימות דהאדם שנעשית ע\"י ספירת העומר. שספירת העומר הו\"ע בירור וזיכוך המדות, ושע\"י ספירת העומר הוא המשכת מ\"ט שערי בינה<sup data-n=\"2616\">25</sup>.\nד) <b>וזהו</b> ביום הזה באו מדבר סיני, ומבאר בתו\"א, דמדבר הוא מלשון דיבור, ונקרא מדבר בתוספת מ' (דמ' הוא מאותיות האמנתי\"ו שמורים על הקטנת הענין<sup data-n=\"2617\">26</sup>) להורות שהדיבור הוא בביטול. [וענין זה שייך גם למדבר כפשוטו, ארץ לא זרועה<sup data-n=\"2618\">27</sup>, דכשהדיבור הוא ע\"פ שכלו ורצונו, השכל והרצון הם הזריעה שעי\"ז הוא צמיחת הדיבור. וענין מדבר ארץ לא זרועה הוא שהדיבור דתורה שמדַבר הוא דבר ה' ואינו זרוע משכלו ורצונו<sup data-n=\"2619\">28</sup>]. וסיני הוא שירדה שנאה לאומות העולם<sup data-n=\"2620\">29</sup>, והוא שהתורה נקראת תושי'<sup data-n=\"2621\">30</sup> לפי שמתשת כח הסט\"א. ויש לומר, דזה שביום הזה באו מדבר הוא לפי שביום הזה (ר\"ח) הלבנה [וכן ישראל שמונין ללבנה] היא נקודה בלבד, וזה שביום הזה באו סיני שירדה שנאה ליצה\"ר<sup data-n=\"2622\">31</sup> הוא לפי שביום הזה (ר\"ח סיון) נשלם הבירור של עיקרי המדות דנפש הבהמית.\nה) <b>וצריך</b> להבין, דלפי הנ\"ל, זה שבר\"ח סיון נשלמו עיקרי המדות הוא ביאור בשלימות האדם, ובהדרוש שבתו\"א מקשר זה עם זה שבר\"ח הוא מולד הלבנה, ענין הביטול. וי\"ל הביאור בזה, דענין מולד הלבנה הוא (לא הביטול שלה, אלא אדרבה<sup data-n=\"2623\">32</sup>) שנולד מציאותה, ע\"י שנמשך בה אור השמש. וזה שבעת המולד היא רק נקודה בלבד, שזה מורה על הביטול שלה (כנ\"ל), הוא, <i>שהמציאות</i> דהלבנה, האור שלה, היא בבחינת ביטול, שנרגש בה שהאור שבה הוא לא משל עצמה ורק שמקבלת מהשמש. ועד\"ז הוא בישראל שמונין ללבנה, דענין הביטול דר\"ח בעבודת האדם הוא <i>שהמציאות</i> שלו היא בביטול. [ויש לומר דזהו שמבואר בתו\"א דזה שר\"ח נקרא יום הזה (סתם) הוא כי יום הזה הוא אהבה שבבחינת ביטול [דיום הוא אור כמ\"ש<sup data-n=\"2624\">33</sup> ויקרא אלקים לאור יום ואהבה היא אור, וזה הוא יחו\"ע (שלכן משה רבינו נתנבא בזה<sup data-n=\"2625\">34</sup>), ויום הזה הוא אהבה שבבחינת ביטול דיחו\"ע], כי מהטעמים על זה שאהבהנק' בשם אור, הוא, לפי שאהבה היא התפשטות<sup data-n=\"2626\">35</sup> [ולכן היראה שהיא כיווץ (היפך ההתפשטות) נקראת בשם חושך<sup data-n=\"2627\">36</sup>], והביטול דר\"ח הוא לא באופן שמתבטל ממציאותו (דוגמת הביטול דיראה), כי אם, שההתפשטות (המציאות) שלו היא בביטול]. ועפ\"ז יש לבאר הקשר דשני הענינים שבר\"ח סיון (ביטול הלבנה והשלמת עיקרי המדות), כי ענין מולד הלבנה הוא שהמציאות הוא בביטול.\nו) <b>ועפ\"ז</b> יש לבאר מה שהקשו התוספות דהוה לי' למילף מדבר ממדבר, כי זה שבר\"ח סיון באו לבחינת מדבר הוא ביטול נעלה יותר מזה שר\"ח נק' יום הזה. דענין יום הזה הוא שהוא במציאות (ועד למציאות דהתפשטות, יום) אלא שהמציאות שלו היא בביטול (הזה), משא\"כ זה שבר\"ח סיון באו לבחינת מדבר [שהדיבור שלו אינו דיבור עצמו כלל, ופה האדם הוא רק כלי לדבר הוי' המדַבר על ידו, וע\"ד דבר ה' בפי הנביא<sup data-n=\"2628\">37</sup>] הוא ביטול המציאות. וכיון שעיקר המעלה דר\"ח סיון הוא שבו באו להביטול דמדבר, לכן מקום לומר שהרמז בכתוב (שזה הי' בר\"ח סיון) הוא בתיבת מדבר<sup data-n=\"2629\">38</sup>. וזה שהלימוד בגמרא הוא מביום הזה, הוא, כי הענין דיום הזה שבר\"ח סיון הוא נעלה יותר גם מהביטול דמדבר, כדלקמן.\nז) <b>ויובן</b> זה ע\"פ מה שאמרו רז\"ל<sup data-n=\"2630\">39</sup> בשעה שהקדימו ישראל נעשה לנשמע באו מלאכי השרת וקשרו לכל אחד מישראל שני כתרים אחד כנגד נעשה ואחד כנגד נשמע. וידוע הדיוק בזה<sup data-n=\"2631\">40</sup>, דבתחלת המאמר בשעה שהקדימו כו' משמע דזה שקשרו להם שני כתרים הוא מפני שהקדימו נעשה לנשמע, ובסיום המאמר אומר אחד כנגד נעשה ואחד כנגד נשמע, דשני הכתרים הם עבור נעשה ונשמע עצמם. ומבאר אדמו\"ר מהר\"ש במאמרו ד\"ה בשעה שהקדימו שנאמר בש\"פ במדבר לפני מאה שנה<sup data-n=\"2632\">41</sup>, דנעשה הוא קבלת עול מלכות שמים ונשמע הוא קבלת עול מצוות. וענין הקדמת נעשה לנשמע הוא כמאמר רז\"ל<sup data-n=\"2633\">42</sup> למה קדמה פרשת שמע לוהי' אם שמוע כדי שיקבל עליו עול מלכות שמים תחלה ואח\"כ יקבל עליו עול מצוות. ומבאר שם, דפרשה ראשונה היא רצוא ומסירת נפש ופרשה שני' היא שוב. וכמו שברצוא ושוב, בתחלה צ\"ל רצוא ואח\"כ שוב, עד\"ז הוא בקבלת עומ\"ש וקבלת עול מצוות, שלפני קבלת עול מצוות צ\"ל קבלת עומ\"ש. ועפ\"ז מבאר שם<sup data-n=\"2634\">43</sup> מה שארז\"ל בשעה שהקדימוכו', אף ששני הכתרים הם כנגד נעשה ונשמע עצמם [אחד כנגד נעשה ואחד כנגד נשמע], כי בכדי שיהי' השוב (נשמע) צ\"ל קדימת הרצוא (נעשה). וממשיך בהמאמר שם, דזה שקשרו להם שני כתרים (כתרים דוקא), הוא, כי כתר הוא מקיף, סובב, ויש בזה ב' ענינים, עליית ממלא בסובב והמשכת סובב בממלא. ולכאורה הכוונה, דכתר שכנגד נעשה (רצוא) הוא עליית ממלא בסובב וכתר שכנגד נשמע (שוב) הוא המשכת סובב בממלא.\n<b>ויש</b> לומר, דזה שמוסיף בהמאמר שזה שקשרו להם שני כתרים הוא כי כתר הוא מקיף, הוא, כי מלשון רז\"ל בשעה שהקדימו כו' קשרו להם שני כתרים משמע שהדיוק דהקדימו נעשה לנשמע שייך לשני הכתרים שכנגד נעשה ונשמע (ולא לנעשה ונשמע עצמם), ולכן מבאר דכתר הוא מקיף וסובב ושני הכתרים הם שני ענינים בסובב, כי זהו ביאור על זה שקשירת שני הכתרים היתה דוקא ע\"י שהקדימו נעשה לנשמע (כדלקמן). וזה שמבאר לפנ\"ז דזה שצריך להקדים נעשה לנשמע הוא כי נעשה ונשמע הם כמו רצוא ושוב, הוא ביאור על זה שהכתר שכנגד נשמע (מקיף וסובב) הוא דוקא כשהנשמע הוא לאחרי הקדימה דנעשה. כי מקיף וסובב הוא למעלה משייכות לעולמות, וכיון שנשמע הוא שוב והמשכה למטה, לכן, זה שקשרו כתר (מקיף וסובב שלמעלה מעולם) כנגד נשמע (המשכה למטה) הוא דוקא מפני שהנשמע הי' לאחרי ההקדמה דנעשה<sup data-n=\"2635\">44</sup>, רצוא ועלי' למעלה.\nח) <b>וצריך</b> ביאור, הרי כללות הענין דקבלת עול, גם קבלת עול מצוות (נשמע), הוא ביטול, דענין הביטול הוא שהאדם <i>יוצא</i> ממציאותו, וקשירת הכתר שכנגד נשמע הוא דוקא כשהנשמע הוא לאחרי הקדימה דנעשה. וי\"ל הביאור בזה ע\"פ הידוע<sup data-n=\"2636\">45</sup> שהמקיף דכתר הוא אמיתית המקיף שלמעלה מהמקיף השייך לפנימי. דזהו החילוק בין כתר לגלגלתא, דגלגלתא הוא מקיף השייך לפנימי, בדוגמת הגולגולת שבאדם שמקיף את המוח אבל שייך אליו, שהרי הגולגולת היא מגופו כמו המוח. והמקיף דכתר הוא מקיף שלמעלה משייכות לפנימי, בדוגמת כתר כפשוטו שהוא עטרה על המוח והגולגולת ואין לו קשר אליהם (שהרי הכתר הוא מאבנים טובות ולא מגוף האדם). והגם שגם גלגלתא נק' בשם כתר, זהו בכללות, אבל עיקר הכתר הוא המקיף שאינו שייך לפנימי (שלמעלה מהמקיף דגלגלתא). וע\"ד הרצון שבאדם, דרצון הוא מקיף על כל הכחות והאברים, שיש בו שתי מדריגות<sup data-n=\"2637\">46</sup>. הרצון לעשות איזה דבר ע\"י הכחות שלו, דרצון זה עם היותו שולט על כל הכחות לפי שהוא מקיף עליהם, מ\"מ, זה עצמו שהוא רוצה בפעולת הכחות, הוא הוכחה שיש לו שייכות אליהם – מקיף דגלגלתא. והוא ירידה לגבי הרצון עצמו כמו שהוא למעלה מהרצון לעשות – מקיף דכתר.<b>והנה</b> זה שבחג השבועות הוא המשכת הכתר, הוא אמיתית הכתר שלמעלה מגלגלתא<sup data-n=\"2638\">47</sup>. ועד\"ז הוא בנוגע לשני הכתרים שכנגד נעשה ונשמע שנמשכו בערב חג השבועות<sup data-n=\"2639\">48</sup>, שהם מקיפים שלמעלה משייכות לפנימי<sup data-n=\"2640\">49</sup>. ועפ\"ז יש לבאר שקשירת הכתר שכנגד נשמע היתה דוקא ע\"י שהקדימו נעשה לנשמע, כי הביטול דקבלת עול מצוות הוא ביטול להרצון, וכיון שהמצוות הם ציוויים <i>להאדם</i>, הרי הרצון דמצוות הוא ע\"ד הרצון (דהאדם) שרוצה לעשות ע\"י הכחות שלו, מקיף דגלגלתא. והמשכת המקיף דכתר (מקיף שלמעלה משייכות לפנימי) הוא ע\"י הביטול דקבלת עול מלכות שמים, ביטול לבעל הרצון. וע\"י שהקדימו נעשה לנשמע, קשרו להם שני כתרים אחד כנגד נעשה ואחד כנגד נשמע, כי ע\"י הקדמת נעשה לנשמע, גם הביטול דקבלת עול מצוות הוא באופן שנרגש בו בגילוי<sup data-n=\"2641\">50</sup> שהוא בא מהביטול דקבלת עול מלכות שמים, ביטול לבעל הרצון.\n<b>וביאור</b> העילוי שנעשה בהביטול דנשמע ע\"י הקדמת הביטול דנעשה, יובן בהקדים, דכמו שלמעלה, הביטול דקבלת עול מצוות הוא להרצון (גילוי) והביטול דקבלת עומ\"ש הוא לבעל הרצון, עד\"ז הוא בנוגע להאדם, שהביטול דקבלת עול מצוות הוא בהגילויים דהאדם, שיעשה כל מה שיצטווה ויתירה מזו שזה (לעשות מה שנצטווה) יהי' הרצון שלו, והביטול דקבלת עומ\"ש הוא בהאדם עצמו, שכל מציאותו הוא זה שהוא עבדו של המלך, מלך מלכי המלכים הקב\"ה. ומזה מובן, שהמעלה דקבלת עומ\"ש לגבי קבלת עול מצוות היא גם בענין הביטול. דבקבלת עול מצוות, נשאר אצלו ובו מציאות שאינה בטילה<sup data-n=\"2642\">51</sup>, ואמיתית הביטול הוא בקבלת עומ\"ש, שכל מציאותו הוא זה שהוא עבד המלך. [וזה שצ\"ל (גם) קבלת עול מצוות הוא בכדי שהביטול יהי' (גם) בנוגע לקיום התומ\"צ בפועל<sup data-n=\"2643\">52</sup>]. וכאשר הביטול דנשמע (קבלת עול מצוות) הוא לאחרי וע\"י הקדמת הביטול דנעשה (קבלת עומ\"ש), שנרגש<i>בגילוי</i> דזה שמקבל עליו לעשות כל מה שיצטווה הוא מפני שהוא עצמו עבדו של המלך, אזי, גם הביטול דנשמע הוא בכל מציאותו (בנוגע לכחות הגלויים שלו), ואין שייך כלל שלא יקיים הציווי.\nט) <b>ויש</b> להוסיף, דכמו שברצוא ושוב, תכלית הכוונה דהרצוא הוא בשביל השוב שלאחרי הרצוא<sup data-n=\"2644\">53</sup>, עד\"ז הוא בנעשה (קבלת עומ\"ש) ונשמע (קבלת עול מצוות) שהם כמו רצוא ושוב, שתכלית הכוונה דנעשה הוא שיביא לנשמע. וע\"י הקדמת נעשה לנשמע, שנעשה הוא הקדמה לנשמע, מיתוסף עילוי בנעשה. כי הביטול דנעשה (מצד עצמו), עם היותו ביטול דמס\"נ שהוא ביטול הכי נעלה, הוא הביטול של האדם<sup data-n=\"2645\">54</sup>, וע\"י שהנעשה הוא הקדמה לנשמע לקבל עליו עול מצוות (שוב והמשכה למטה), עי\"ז נשלמת הכוונה דנתאוה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"2646\">55</sup>, כוונת העצמות<sup data-n=\"2647\">56</sup>. ויש להוסיף, שהמעלה דנשמע שע\"י הקדימה דנעשה על הענין דנעשה עצמו הוא גם בהביטול. כי הביטול דנעשה (מצד עצמו) הוא <i>שאינו</i> מציאות לעצמו (והוא רק עבדו של המלך), וע\"י הקדמת נעשה לנשמע, שהביטול דנשמע הוא דוגמת הביטול דנעשה, הביטול הוא גם בהמציאות דהאדם.\nיו\"ד) <b>ועד\"ז</b> הוא בשני הענינים שבר\"ח סיון, הביטול דיום הזה והביטול דמדבר<sup data-n=\"2648\">57</sup>, שהמעלה דהביטול דיום הזה על הביטול דמדבר הוא בשני ענינים. שהביטול דיום הזה (שהאהבה היא בביטול) הוא גם בהמציאות דהאדם. ושעי\"ז דוקא נשלמת הכוונה דדירה בתחתונים.\n<b>ויש</b> להוסיף, דזה שהביטול דיום הזה נמשך גם בהמציאות דהאדם [וגם לאחרי הביטול שנמשך בהמציאות הוא (לא ביטול היש, אלא) ביטול במציאות], הוא ע\"י המשכת העצמות, שבכח העצמות הוא לחבר שני הפכים (ביטול ומציאות).\n<b>ויש</b> לומר שזה מרומז גם בלשון הכתוב ביום הזה. דהנה מבואר בלקו\"ת<sup data-n=\"2649\">58</sup>, שלשון \"זה\", שהוא דבר שאפשר להראות עליו באצבע ולומר זה, הוא רק בהקב\"ה, כמ\"ש<sup data-n=\"2650\">59</sup> זה א-לי ואנוהו, כי מלוא כל הארץ כבודו<sup data-n=\"2651\">60</sup>. ומבואר במק\"א<sup data-n=\"2652\">61</sup> דאמיתית הענין ד\"זה\" הוא רק בהעצמות. כי פירוש \"זה\" הוא שהדבר שאומרים עליו \"זה\", הואמציאותו של הדבר, וכיון שכל הנמצאים, כולל גם הגילויים הכי נעלים, מציאותם אינה מצד עצמם ותלוי' ברצון העצמות<sup data-n=\"2653\">62</sup>, א\"א לומר עליהם בשלימות זה הדבר, ואמיתית הענין ד\"זה\" הוא רק בהעצמות. וזהו ביום הזה, שגם המציאות דהתפשטות (יום) הוא בביטול (הזה), הוא ע\"י גילוי כח העצמות, יום (גילוי) הזה.\nיא) <b>ויש</b> לומר, שזהו גם הקשר דביום הזה עם (מדבר) סיני, שירדה שנאה לאומות העולם שלא קיבלו בו את התורה<sup data-n=\"2654\">63</sup>. דכמו<sup data-n=\"2655\">64</sup> שישראל קיבלו התורה מפני שכפה הקב\"ה עליהם הר כגיגית&lt;39&gt; התגלות האהבה לישראל<sup data-n=\"2656\">65</sup> – ואוהב את יעקב<sup data-n=\"2657\">66</sup>, כמו\"כ הוא בנוגע לאוה\"ע שלא קיבלו את התורה שזהו מפני שירדה שנאה לאוה\"ע – ואת עשו שנאתי<sup data-n=\"2657\">66</sup>. וזה שואוהב את יעקב ואת עשו שנאתי הוא לא מפני המעלה דישראל, כי זה גופא שהחזירה הקב\"ה (לתורה) על כל אומה ולשון<sup data-n=\"2658\">67</sup> מוכיח שנתינת התורה היא ממקום נעלה ביותר, שכל המעלות, כולל גם המעלה דבנים אתם לה' אלקיכם<sup data-n=\"2659\">68</sup>, אינם תופסים מקום שם, ושניהם (ישראל ואוה\"ע) שוים – הלא אח עשו ליעקב<sup data-n=\"2657\">66</sup>, אלא שבבחירתו החפשית בחר להיות ואוהב את יעקב ואת עשו שנאתי. וזהו הקשר דביום הזה עם מדבר סיני, דזה שירדה שנאה לאוה\"ע הוא לפי שכך בחר בבחירתו החפשית (כנ\"ל), ואמיתית ענין הבחירה הוא רק בהעצמות, זה. ועד\"ז הוא גם בנוגע להענין דסיני שירדה שנאה ליצה\"ר (שבישראל), שעי\"ז ניתן הכח לברר המדות דנפש הבהמית, שהוא ע\"י גילוי כח העצמות. דזה שנפש האלקית בטילה לאלקות, כולל שגם ההתפשטות שלה (האהבה) היא בביטול, אינו חידוש כ\"כ, ועיקר הענין דגילוי כח העצמות, יום הזה, הוא בזה שבאו מדבר סיני, בירור וזיכוך הגוף ונה\"ב.\n<b>אלא</b> שאעפ\"כ עיקר הביאור (באריכות ובפרטיות) בהדרוש שבתו\"א בהמעלה דר\"ח סיון הוא בענין הביטול דבחינת מדבר, כי המעלה בזה שגם המציאות הוא בטל [בירור המדות דנה\"ב, ועד\"ז שהמציאות (אהבה) דנפש האלקית היא בביטול] היא שעי\"ז מתגלה כח העצמות (כנ\"ל), אבל בכדי לעורר ולהמשיך הענין דמתן תורה (המשכת העצמות) הוא ע\"י הביטול הבא מעצם הנשמה, דביטול זה מגיע בהעצמות.\n<b>ויש</b> לקשר זה עם שבר\"ח סיון היו כל ישראל כאיש אחד בלב אחד<sup data-n=\"2660\">69</sup>, ואמר הקב\"ה הרי השעה שאתן להם את תורתי<sup data-n=\"2661\">70</sup>, כי זה שהיו כאיש אחד בלב אחד הוא ע\"יהגילוי דשרש הנשמה שלמעלה מהנשמה המלובשת בגוף, וכמבואר בתניא<sup data-n=\"2662\">71</sup> שכל ישראל הם אחים ממש הוא (דוקא) מצד שרש נפשם, ולכן זה שהיו כאיש אחד<sup data-n=\"2663\">72</sup> הגיע בהעצמות ונתעורר אצלו כביכול הרצון ליתן להם את תורתו.\nיב) <b>וזהו</b> בחודש השלישי גו' ביום הזה גו', דהגם שהענין דיום הזה הוא בכל ר\"ח, עיקר הענין דיום הזה הוא ב(ראש) חודש השלישי. והענין הוא (כמבואר בדרושי הצ\"צ<sup data-n=\"2664\">73</sup>), דחודש הראשון הוא בחינת סיהרא, מלכות. דהגם שגם בר\"ח ניסן יש היחוד דשמשא וסיהרא (ז\"א ומלכות), מ\"מ, בר\"ח ניסן, העיקר הוא המלכות. וחודש אייר נק' זיו<sup data-n=\"2665\">74</sup>, הוא היסוד שמאיר במלכות<sup data-n=\"2666\">75</sup>. וזה שהיסוד נקרא זיו הוא לפי שהוא זיו והארה בלבד. ובחודש השלישי מקבלת המלכות מת\"ת, דבת\"ת הוא הגילוי דהוי' שהוא שם העצם<sup data-n=\"2667\">76</sup>. היינו שהגילוי דחודש השלישי הוא לא זיו (כהגילוי דחודש אייר), אלא גילוי העצם. ולכן, עיקר הענין דיום הזה הוא בר\"ח סיון, בחודש השלישי.\n<b>וע\"י</b> ההכנה לקבלת התורה בחודש השלישי ביום הזה (ר\"ח סיון) – הן בבירור המדות דנפש הבהמית (סיני), והן בהביטול (מדבר) דנפש האלקית, ובפרט בהענין דכאיש אחד בלב אחד [שזו (אהבת ישראל) היא כל התורה כולה ואידך פירושה הוא<sup data-n=\"2668\">77</sup>] – זוכים לקבלת התורה בשמחה ובפנימיות, וממשיכים זה על כל השנה כולה.\n**********",[["2591","*","יצא לאור ב<b>קונטרס ראש חודש סיון – תש\"נ</b>, \"לקראת ראש חודש סיון . . <i>ער\"ח סיון</i>,<i> חודש השלישי</i>,<i> שנת ה'תש\"נ</i>\"."],["2592","1","יתרו יט, א."],["2593","2","שבת פו, ב."],["2594","3","בא יב, ב."],["2595","4","ד\"ה וכתיב – שבת שם. וראה תוד\"ה ממאי – פסחים ו, ב."],["2596","5","שם."],["2597","6","בהעלותך ט, א."],["2598","7","פרשתנו (במדבר) א, א."],["2599","8","ראה להלן הערה 10."],["2600","9","להעיר שלשון הגמרא בפסחים שם הוא \"מה להלן <i>ב</i>ר\"ח אף כאן <i>ב</i>ר\"ח\", ובשבת שם \"מה להלן ר\"ח אף כאן ר\"ח\". ויש לומר, כי \"החודש הזה\" וכן \"ביום הזה\" (לאחרי הלימוד דגז\"ש) הם <i>ר\"ח</i>, משא\"כ \"במדבר סיני\"."],["2601","10","ואף שבפסוק וידבר גו' במדבר סיני מפורש בכתוב עצמו \"באחד לחודש\" משא\"כ בפסוק \"בחודש הזה\" ההוכחה שזה הי' בר\"ח הוא \"דאמרינן במדרש שהראהו הקב\"ה למשה באצבע\" (לשון התוספות שם) – הרי זהו גם הפירוש בפשטות הכתובים (פרש\"י בא שם)."],["2602","11","יתרו סו, סע\"ג ואילך (ועם הגהות – באוה\"ת יתרו ע' תשעב ואילך. שם כרך ח ע' ב'תתקעה ואילך). וראה גם הוספות לתו\"א יתרו (קח, סע\"ג ואילך). ד\"ה זה בסה\"מ תקס\"ז ע' קמו ואילך. תו\"ח יתרו שסו, ב ואילך [בהוצאה החדשה – ח\"ב רנא, א ואילך]. סה\"מ תרנ\"ה ע' פח ואילך. ועוד."],["2603","12","כ\"ה בתו\"א שם סז, ב. וראה לקמן הערה 57."],["2604","13","יתרו כ, א."],["2605","14","ראה ד\"ה וידבר גו' אנכי גו' ה'תשכ\"ח ס\"א (לקמן ע' שכו). <i>וש\"נ.</i>"],["2606","15","תהלים קיט, קעב."],["2607","16","לקו\"ת פרשתנו (במדבר) יב, א. <i>ועוד.</i>"],["2608","17","אמור כג, טז."],["2609","18","לקו\"ת שם. וראה גם הוספות לתו\"א שם (קט, ג)."],["2610","19","זהר ח\"א קפא, א. וראה גם שם לג, ב. רמט, ב. ח\"ב קמה, ב. רטו, א. ח\"ג קיג, ב. ועוד."],["2611","20","סוכה כט, א. ב\"ר פ\"ו, ג."],["2612","21","כ\"ה הלשון בתו\"א שם (סז, ג). וי\"ל שהכוונה היא להעבודה דספירת העומר ברוחניות."],["2613","22","ראה טז, ט."],["2614","23","ולהעיר מתנחומא יתרו ח [ועד\"ז בבמדב\"ר פ\"ז, א] \"אינו דין שאתן את תורתי לבעלי מומין\"."],["2615","24","ראה עירובין נה, רע\"א: לא בשמים היא, לא תמצא [התורה] בגסי רוח. וראה סוטה ה, א: כל אדם שיש בו גסות הרוח, אמר הקב\"ה אין אני והוא יכולין לדור בעולם."],["2616","25","ויש לומר, שבירור וזיכוך המדות הוא שלא יהי' בו חסרון ומום, והמשכת מ\"ט שע\"ב הו\"ע השלימות (\"אתר שלים\") <i>בדוגמת</i> \"כלי\" לשער הנו\"ן (ראה לקו\"ת במדבר יב, ב. שה\"ש כד, סע\"א ואילך)."],["2617","26","הובא בתורה אור שם סז, ריש ע\"ד. סה\"מ תקס\"ז שם ע' קנב. תו\"ח שם שעג, ב [שם רנה, ד]."],["2618","27","לשון הכתוב – ירמי' ב, ב."],["2619","28","סד\"ה זה תרנ\"ה (סה\"מ תרנ\"ה ע' צד). וראה גם תו\"ח שם [שם רנה, ב]."],["2620","29","שבת פט, סע\"א ואילך."],["2621","30","סנהדרין כו, ב."],["2622","31","כ\"ה בסה\"מ תרנ\"ה שם. ובכ\"מ."],["2623","32","להעיר מהידוע בפירוש הכתוב (שמואל-א כ, יח) מחר חודש ונפקדת כי יפקד מושבך, ד\"יפקד מושבך\" הוא <i>בערב</i> ר\"ח, ובר\"ח הוא \"<i>ונפקדת</i>\" (לעיל ח\"א ע' שמג. ובכ\"מ)."],["2624","33","בראשית א, ה."],["2625","34","ספרי (הובא בפרש\"י) ר\"פ מטות."],["2626","35","וראה ספר הערכים-חב\"ד כרך ב ערך אור – ביחס לחושך ע' תקמד. <i>וש\"נ</i>. וראה גם הוספות לתו\"א שם (קט, ג) \"התפעלות אהבה שהוא נק' אור שמאיר בהתפשטות\"."],["2627","36","נסמן בספר הערכים שם."],["2628","37","תו\"ח שם [שם רנו, א]."],["2629","38","ועפ\"ז יומתק לשון הגמרא (פסחים ו, ב) \"אתיא מדבר ממדבר\" ולא \"מדבר סיני ממדבר סיני\" (וכן בקושיית התוספות \"אמאי לא יליף הכא <i>מדבר ממדבר</i>\") – כי המעלה דר\"ח היא הביטול דמדבר."],["2630","39","שבת פח, א."],["2631","40","ד\"ה בשעה שהקדימו תרכ\"ט (דלקמן בפנים). ד\"ה הנ\"ל שבהמשך תרס\"ו (ע' תמז) ובהמשך תער\"ב בתחילתו. ובכ\"מ."],["2632","41","משנת אמירת מאמר זה (תשכ\"ט) – נדפס בסה\"מ תרכ\"ט ע' קפד ואילך."],["2633","42","ברכות יג, א במשנה."],["2634","43","בסוף המאמר – ע' קצב."],["2635","44","היינו שהענין ד\"נשמע\" עצמו אפשר להיות גם בלי הקדימה ד\"נעשה\" [אלא שאז אינו שייך לכתר]. וראה לקמן הערה 50."],["2636","45","המשך תרס\"ו ע' רעג."],["2637","46","ראה המשך הנ\"ל שם ע' רפא."],["2638","47","בהוספות לתו\"א יתרו שם בסיום המאמר (קי, א-ב) נזכר הלשון גלגלתא דאריך. אבל מהמשך הענין שם משמע, שמדובר שם בדרגא דרצון שלמעלה מרצון לעשות – ראה שם, שהדיבור שתלוי בבחירה ורצון שרשו הוא בהתפשטות הרצון והדיבור שאינו תלוי ברצונו (בחינת מדבר) מגיע בפנימיות הכתר, רצון הפשוט, רעוא דכל רעוין."],["2639","48","כי הקדמת נעשה לנשמע היתה בחמישי בסיון – פרש\"י עה\"פ משפטים כד, ד."],["2640","49","ראה הוספות לתו\"א שם (קט, א) שמקשר הענין דב' הכתרים עם זה שעל כל דיבור ודיבור פרחה נשמתן (ראה שבת פח, ב) – והרי הענין דפרחה נשמתן הוא (לכאורה) בדרגא שלמעלה מהרצון לעשות."],["2641","50","ועפ\"ז יובן מה שארז\"ל (הובא לעיל ס\"ז) \"שיקבל עליו עול מלכות שמים תחלה ואח\"כ יקבל עליו עול מצוות\" – דלכאורה, בלי קבלת עול מלכות שמים <i>אי אפשר</i> להיות עול מצוות [בדוגמת מלך בו\"ד, <i>שהעול</i> לקיים גזירותיו שייך דוקא לאחרי שקבלו אותו למלך עליהם (ראה מכילתא (ויל\"ש) עה\"פ יתרו כ, ג)], וא\"כ, כשמקבל עליו עול מצוות, זה עצמו מוכיח שקיבל עליו עול מלכות שמים, ולמה צריך <i>לצוות</i> שיקבל עליו עול מלכות שמים תחלה. ויש לומר, שהציווי לקבל עליו עומ\"ש תחלה הוא שהקבלת עומ\"ש תהי' ה\"תחילה\" דקבלת עול מצוות, היינו שבעול המצוות שלו יורגש בגילוי הביטול דעול מלכות שמים, כדלקמן בפנים."],["2642","51","ויתירה מזו, דכיון שהמציאות שאינה בטילה היא <i>עצם מציאותו</i> [שהוא העצם (גם) דכחותיו הגלויים] – גם הביטול שבכחות הגלויים שלו אינו בשלימות, דהגם שמקבל עליו עול מצוות – נשאר אצלו (בהעלם עכ\"פ, גם בדרגת ההעלם דכחות הגלויים) נתינת מקום שאפשר לפעמים לא לקיים הציווי."],["2643","52","כי הביטול דקבלת עול מלכות שמים (מצד עצמו) הוא באופן דרצוא והעלאה למעלה ואינו שייך לקיום המצוות – ראה סה\"מ תרכ\"ט שם (ע' קץ)."],["2644","53","ראה בארוכה סה\"מ תרמ\"ט ע' רנו ואילך. ובכ\"מ."],["2645","54","ראה סה\"מ תרכ\"ט שם (ע' קצב)."],["2646","55","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2647","56","ראה לעיל ח\"ב ע' כד. ובכ\"מ."],["2648","57","ועד\"ז הוא בדיבור דתורה והשגת התורה, דמעלת הדיבור דתורה היא שהוא באופן דעונה אחר הקורא* – <i>ביטול</i>; ומעלת ההשגה דתורה היא – שגם השכל דהאדם (ה\"מציאות\" שלו) נעשה חד עם התורה."],["2649","58","ראה לב, ג."],["2650","59","בשלח טו, ב. וראה פרש\"י עה\"פ. שמו\"ר ספכ\"ג."],["2651","60","ישעי' ו, ג."],["2652","61","ראה ד\"ה זה היום תחלת מעשיך, דכ\"ט אלול ה'תשל\"ג (סה\"מ תשל\"ג ע' 485). ובכ\"מ.\n*) <i>ראה הוספות לתו\"א שם (בתחילת המאמר)</i>,<i> דזה שצריך ללמוד תורה בדיבור דוקא</i>,<i> אף שעיקר ענין הלימוד הוא ידיעת התורה</i>,<i> הוא</i>,<i> כי דוקא הדיבור דתורה הוא באופן דכעונה אחר הקורא</i>."],["2653","62","ראה סה\"מ ה'תשי\"א ע' 25 ואילך. וראה שם ס\"ע 35."],["2654","63","שבת פט, סע\"א ובפרש\"י שם."],["2655","64","בהבא לקמן ראה (עד\"ז) לקו\"ש ח\"ד ע' 1309."],["2656","65","תו\"א מג\"א צח, ד. לקו\"ת ראה כב, א. ובכ\"מ."],["2657","66","מלאכי א, ג."],["2658","67","ע\"ז ב, ב. ובכ\"מ."],["2659","68","ראה יד, א."],["2660","69","פרש\"י עה\"פ יתרו יט, ב."],["2661","70","ויק\"ר פ\"ט, ט. דא\"ז פ' השלום. וראה גם תנחומא באבער יתרו ט. וראה לקו\"ש חכ\"א שיחה א' וב' לפ' יתרו (ע' 100 ואילך)."],["2662","71","פרק לב. וראה לקו\"ש ח\"ד ע' 1059."],["2663","72","שזה נעלה יותר גם מזה שכל ישראל הם <i>אחים</i>. וי\"ל, שבכדי להיות \"כאיש אחד\" הוא ע\"י גילוי <i>עצם</i> הנשמה (שלמעלה גם מדרגת הנשמה שלמעלה מהתלבשות בגוף)."],["2664","73","אוה\"ת יתרו ד\"ה זה (ס\"ע תשעב ואילך)."],["2665","74","מלכים-א ו, א. ר\"ה יא, א. זח\"ג קיז, ב."],["2666","75","זח\"ג שם, הובא בלקו\"ת במדבר ג, א. אוה\"ת בהעלותך ע' שסז."],["2667","76","כס\"מ הל' עכו\"ם פ\"ב ה\"ז. פרדס שער יט (שער שם בן ד). מו\"נ ח\"א פס\"א ואילך. עיקרים מאמר ב' פכ\"ח."],["2668","77","שבת לא, א."]]],[1500380047,"<h3>בס\"ד. אור לה' סיון, ערב חג השבועות, ה'תשמ\"ט<sup data-n=\"2669\">*</sup></h3>\n<b>אנכי</b> הוי' אלקיך אשר הוצאתיך מארץ מצרים<sup data-n=\"2670\">1</sup>, דפסוק זה הוא דיבור הראשון דעשרת הדברות שניתנו במתן תורה בו' סיון<sup data-n=\"2671\">2</sup>, לאחרי שהקדימו ישראל נעשה לנשמע [ובאו מלאכי השרת וקשרו לכל אחד מישראל שני כתרים אחד כנגד נעשה ואחד כנגד נשמע<sup data-n=\"2672\">3</sup>] בחמישי בסיון<sup data-n=\"2673\">4</sup>. ומובא בכמה דרושים דרבותינו נשיאינו<sup data-n=\"2674\">5</sup> השאלה הידועה דגדולי ישראל<sup data-n=\"2675\">6</sup>, הרי בריאת שמים וארץ הוא פלא גדול יותר מיצי\"מ. דביצי\"מ, אף שהיו כמה נסים, הרי נוסף לזה שאין זה ביאור מספיק על זה שאומר אשר הוצאתיך מארץ מצרים דוקא, מכיון שגם קודם יצי\"מ וכן לאחרי יצי\"מ היו כו\"כ נסים<sup data-n=\"2676\">7</sup>, הנה ענין הנס הוא שינוי מיש ליש, ובריאת שמים וארץ הוא יש מאין. ונוסף לזה שבריאה יש מאין הוא פלא גדול יותר, הנה גם הכח האלקי שבבריאה יש מאין הוא כח נעלה יותר, כידוע<sup data-n=\"2677\">8</sup> שבריאה יש מאין היא רק בכח העצמות שמציאותו מעצמותו. [ויש לומר, דזה שהמציאות דיש הנברא היא מציאות אמיתית<sup data-n=\"2678\">9</sup>, הוא מפני שהתהוותו היא מהעצמות, יש האמיתי<sup data-n=\"2679\">10</sup>]. ולמה אומר אשר הוצאתיך מארץ מצרים, דלכאורה הול\"ל אשר בראתי שמים וארץ.\nב) <b>ויש</b> להוסיף, דזה שלכאורה הול\"ל אשר בראתי שמים וארץ, הוא גם לפי שבריאת שמים וארץ ומתן תורה (דאנכי הוי' אלקיך הוא הפתיחה דמ\"ת) שייכים זל\"ז. דבריאת שמים וארץ מתחדשת בכל רגע ורגע, כתורת הבעש\"ט עה\"פ<sup data-n=\"2680\">11</sup> לעולם הוי' דברך נצב בשמים (הובא בספר תניא קדישא<sup data-n=\"2681\">12</sup>) שכח האלקי מהוה תמיד את הנברא מאין ליש. ומכיון שבריאה והתהוות יש מאין היא בכח העצמות, מובן, שהבריאה שבכל רגע ורגע היא יש מאין ממש מהעצמות. ועד\"ז הוא בתורה<sup data-n=\"2682\">13</sup>,שנתינתה (והמשכתה) היא מהעצמות (אנכי), והמשכתה מהעצמות היא בכל רגע<sup data-n=\"2683\">14</sup> כמ\"ש<sup data-n=\"2684\">15</sup> נותן התורה לשון הוה, שלכן ארז\"ל<sup data-n=\"2685\">16</sup> בכל יום<sup data-n=\"2686\">17</sup> יהיו בעיניך חדשים, חדשים ממש.\n<b>והנה</b> הכח על זה שבכל יום יהיו בעיניך חדשים, ניתן במ\"ת. וכידוע<sup data-n=\"2687\">18</sup> בפירוש הכתוב<sup data-n=\"2688\">19</sup> וידבר אלקים את כל הדברים האלה לאמר, שהפירוש דתיבת לאמר בפסוק זה הוא לא לאמר לאחרים (כמו כל לאמר שבמקרא) שהרי (נשמות) כל ישראל היו במעמד הר סיני ושמעו הדברות מהקב\"ה עצמו, ופירוש לאמר כאן הוא שבשעת מ\"ת ניתן הכח לכאו\"א מישראל שבכל הדורות לאמר את כל הדברים האלה (שקאי גם על כל התורה כולה<sup data-n=\"2689\">20</sup>), שלימוד התורה שלו יהי' באופן דלאמר, שאומר הדברים שהקב\"ה אומר עכשיו, כמו בשעת מתן תורה. שלכן מה להלן באימה וביראה וברתת ובזיע אף כאן כו'<sup data-n=\"2690\">21</sup>. ועפ\"ז מודגש עוד יותר השייכות דענין ההתחדשות למתן תורה, כיון שהכח על זה שיהיו בעיניך חדשים ניתן במתן תורה.\nג) <b>והנה</b> ע\"פ הידוע שגם שאלה בתורה היא תורה, תורת אמת, מובן, דזה שמובא בכמה דרושים שההתחלה דמ\"ת הי' צ\"ל בבריאת שמים וארץ הוא גם אליבא דאמת. דנוסף לזה שהתחלת כל התורה היא בראשית ברא אלקים את השמים ואת הארץ<sup data-n=\"2691\">22</sup>, וכן התחלת משנה תורה (להרמב\"ם)<sup data-n=\"2692\">23</sup> היא לידע שיש שם מצוי ראשון והוא ממציא כל נמצא וכל הנמצאים כו' לא נמצאו אלא מאמיתת המצאו [ולהוסיף, שבההתחלה דמשנה תורה מבואר לא רק ענין הבריאה בכללות (כבהתחלת תושב\"כ) אלא גם שכל הנמצאים נמצאו <i>מאמיתת</i> המצאו, היינו שהבריאה היא בכח העצמות יש <i>האמיתי</i>, וכן – שהבריאה היא בכל רגע ורגע כמ\"ש בהמשך הענין שם<sup data-n=\"2693\">24</sup> דאם יעלה על הדעת שהוא אינו מצוי אין דבר אחר יכול להמצאות, שהכוונה בזה היא שגם לאחרי שנמצאו הנמצאים – באם לא יהי' מצוי (בהם), תיבטל מציאותם. דשני ענינים אלו שבתורת החסידות, שהבריאה היא בכח העצמות ושהבריאה היא בכל רגע, כתבם הרמב\"ם בסגנון <i>דהלכה</i>], הנה נוסף לזה – גם בההתחלה דמתן תורה ישנו הענין דבריאת שמים וארץ, אלא שענין זה הוא בהחלק דתושבע\"פ דפסוקראשון דמ\"ת<sup data-n=\"2694\">25</sup>, <i>הפירוש</i> דתורה שבכתב<sup data-n=\"2695\">26</sup>. וי\"ל הביאור בזה, דע\"י עסק התורה באופן דיהיו בעיניך חדשים, מגלים גם החידוש בהבריאה<sup data-n=\"2696\">27</sup> שהיא מתחדשת בכל רגע מאין ליש. וע\"פ המובא לעיל דתיבת לאמר שבהתחלת מ\"ת הוא הנתינת כח על יהיו בעיניך חדשים, שעי\"ז מגלים (כנ\"ל) החידוש דהבריאה, הרי, שבההתחלה דמ\"ת (עוד <i>לפני</i> עשרת הדברות) יש (ברמז עכ\"פ) הענין דחידוש הבריאה.\n<b>אלא</b> שאעפ\"כ ההתחלה דמ\"ת בגילוי (בתושב\"כ) היא אנכי ה\"א אשר הוצאתיך מארץ מצרים, כי הכוונה דבריאת העולם ודמתן תורה היא בשביל ישראל, אַז זיי זאָלן דורכגיין הענין דמצרים מלשון מיצר וגבול ושיהי' אצלם היציאה מכל מיצרים וגבולים, הוצאתיך מארץ מצרים, ואפילו מבית עבדים, שיהיו מושללים מעבדות לבו\"ד ואיזו שהיא, כי לי בני ישראל עבדים<sup data-n=\"2697\">28</sup>, לי לעצמות ומהות, ושטרי קודם<sup data-n=\"2698\">29</sup>. ויש לקשר זה עם הענין שמתן תורה הי' לאחרי שהקדימו ישראל נעשה לנשמע<sup data-n=\"2699\">30</sup>, דהגם שהגילוי דמתן תורה הי' מצד למעלה, ואני המתחיל<sup data-n=\"2700\">31</sup>, הי' צריך להיות תחלה הקדמת נעשה לנשמע, הביטול לבעל הרצון, ועי\"ז דוקא ניתנה התורה ונמשכה מהעצמות. כולל גם הנתינת כח שהי' במ\"ת (\"לאמר\", כנ\"ל) שבכל יום יהיו בעיניך חדשים.\nד) <b>והימים</b> האלה נזכרים ונעשים<sup data-n=\"2701\">32</sup>, שבכל שנה ושנה חוזרים ונמשכים אותם הענינים כמו שהיו בפעם הראשונה, ויתירה מזו, שבכל שנה הם בדרגא נעלית יותר, דמעלין בקודש<sup data-n=\"2702\">33</sup>. וכיון שכל הענינים תלויים במעשינו ועבודתינו<sup data-n=\"2703\">34</sup>, לכן, בכל שנה צריך להוסיף ולהעלות בקודש גם בההכנות למתן תורה, הוספה בהענין דויחן לשון יחיד כאיש אחד בלב אחד שהי' בר\"ח סיון<sup data-n=\"2704\">35</sup>, וכן בההכנות שהיו לאחרי ר\"ח סיון (שמיד אחר ר\"ח התחיל משה להתעסק עמהם בענין קבלת התורה<sup data-n=\"2705\">36</sup>),ועאכו\"כ בההכנה דהקדמת נעשה לנשמע, שהיא ההכנה העיקרית למתן תורה כמובן גם מזה שהכנה זו דהקדמת נעשה לנשמע היא בחמישי בסיון שהוא הערב של ששי בסיון שבו ניתנה התורה. והוא, שבמשך היום יתבוננו בהענין דהקדמת נעשה לנשמע, התבוננות המתאימה שמביאה לידי פועל, שבכל ענין דעבודת ה', צריך לכל לראש לקיימו בפועל (נעשה), ולאחרי זה להבין את הענין בחב\"ד שלו (נשמע). ואף שיום זה (חמישי בסיון) הוא ערב יו\"ט שישנם בו כמה טרדות דהכנות צרכי החג, הרי ידועה תורת כ\"ק מו\"ח אדמו\"ר<sup data-n=\"2706\">37</sup> שבחג השבועות ועד\"ז בערב (ומעין) חגה\"ש אין שליטה (כ\"כ) להצד שכנגד, ולכן הוא זמן המוכשר לעשות הכל לטובת לימוד התורה והעבודה כו'.\n<b>ומובן</b> בפשטות, דנוסף להכנות הנ\"ל ששייכים להימים שלפני חגה\"ש, מתחיל מר\"ח סיון, צריך להיות ובמכ\"ש השתדלות מיוחדת בנוגע להענינים השייכים לחגה\"ש עצמו, מתחיל מההשתדלות שכאו\"א מישראל, אנשים נשים וטף, יהיו בבית הכנסת בעת קריאת עשרת הדברות, וכמדובר כמה פעמים<sup data-n=\"2707\">38</sup>, דזה שבכל שנה בחגה\"ש ניתנה התורה מחדש ע\"ד כמו שהי' בפעם הראשונה מתגלה בעיקר בהקריאה דעשרת הדברות, כמאמר רז\"ל<sup data-n=\"2708\">39</sup> אמר הקב\"ה לישראל בני היו קורין את הפרשה הזאת בכל שנה ואני מעלה עליכם כאילו אתם עומדין לפני הר סיני ומקבלין את התורה, שלכן צריך לשמוע פרשה זו באימה וביראה וכו' כאילו עומדים לפני הר סיני, וזהו גם מהטעמים על גודל ההשתדלות שכל בני ישראל, גם הקטני קטנים(ות) יהיו בבית הכנסת בעת קריאת עשרת הדברות, כמדובר כמה פעמים בארוכה [ולהוסיף, שההשתדלות שהטף יהיו בביהכ\"נ בעת קריאת עשה\"ד שייך גם לההכנה דבנינו עורבים אותנו<sup data-n=\"2709\">40</sup>, שי\"ל שכולל גם הפירוש דעורבים מלשון תערובת שכל ישראל מעורבים זה בזה, ועורבים מלשון עריבות ומתיקות שכל ישראל ערבים ומתוקים זה לזה<sup data-n=\"2710\">41</sup>]. ועד\"ז החלטות טובות להוסיף בלימוד התורה, נגלה דתורה ופנימיות התורה, ועד שיפוצו מעינותיך חוצה, כולל גם ההשתדלות לארגן כינוסי תורה באסרו חג השבועות זמן מתן תורתנו או בימים הסמוכים לזה<sup data-n=\"2711\">42</sup>. וכאמור לעיל, שבכל שנה צריך להוסיף בכל ענינים אלו ביתר שאת וביתר עוז, הן בנוגע לההכנות השייכים להימים שלפני זמן מתן תורתנו, והן בנוגע להחלטות טובות (וההשתדלות) בנוגע להענינים השייכים לזמן מתן תורתנו והימים שלאחריו.\n<b>וכאמור</b> לעיל, שבכל שנה צריך להוסיף בההכנות למ\"ת ובפרט בההכנה דהקדמת נעשה לנשמע (בערב חג השבועות), ועי\"ז גם הענין דמתן תורה וקבלתהתורה בחג השבועות הוא בדרגא נעלית יותר, ועד באין ערוך. ועד שבכל שנה, כל ענינים אלו (מ\"ת וקבלת התורה, וכן ההכנות לזה) הם חדשים ממש. ובפרט בשנה זו (תשמ\"ט), ערב שנת תש\"נ שי\"ל – רמז ר\"ת תהא שנת נסים (וגם בשנה זו, ערב תש\"נ, טועמים כבר מהנסים בתש\"נ<sup data-n=\"2712\">43</sup>), צריכה להיות ההכנה ביתר שאת וביתר עוז. וע\"י ההוספה מדי שנה בשנה בההכנות למתן תורה, מיתוסף גם בהענין דמתן תורה, ועד להוספה שבאין ערוך ובאופן של חידוש. דהגם שהענין דמתן תורה, ובאופן של חידוש, הוא במשך כל ימי השנה (כנ\"ל ס\"ב), הרי עיקר הענין דמתן תורה (באופן חדש לגמרי) הוא בחגה\"ש זמן מתן תורתנו.\nה) <b>והנה</b><b>,</b> כמו שבמתן תורה בפעם הראשונה נעשה תוקף בקיום העולם כמאמר חז\"ל<sup data-n=\"2713\">44</sup> עה\"פ<sup data-n=\"2714\">45</sup> ארץ יראה ושקטה, שעד יום הששי בסיון ארץ יראה, וביום הששי בסיון, כשישראל קיבלו את התורה, שקטה, עד\"ז הוא בכל שנה ושנה, שע\"י ההוספה במתן תורה ובקבלת התורה נעשית הוספה בהתוקף דקיום העולם. וע\"ד משנת\"ל (ס\"ג) שע\"י עסק התורה באופן דיהיו בעיניך חדשים מגלים גם החידוש שישנו בהעולם, שהוא מתחדש בכל רגע מאין ליש בכח העצמות. דיש לומר שענין זה [גילוי כח האלקי שמהוה את העולם מאין ליש] הוא אמיתית הענין דשקטה. ועפ\"ז יש להוסיף, דזה שבכל שנה צריך להוסיף בההכנות למתן תורה וקבלת התורה, נכלל בזה גם הוספה בג' העמודים שעליהם העולם עומד, תורה עבודה וגמ\"ח<sup data-n=\"2715\">46</sup>. ובפרט בצדקה, דנוסף לזה שהוא אחד העמודים דהעולם, הוא (גם) כללות כל התורה, כמבואר בתו\"א ד\"ה בחודש השלישי<sup data-n=\"2716\">47</sup>. ולכן נוסף על הסיום (כנהוג) בעשיית כל אחד ואחת לשליח במצות צדקה – צריך להיות בערב חג השבועות, ערב זמן מתן תורתנו, הוספה מיוחדת בנתינת הצדקה, ועד שנתינת הצדקה ביום זה תהי' באופן של פתיחה חדשה, דע\"י פתיחה זו נעשה גם הוספה בההשפעה מידו הפתוחה (המלאה הפתוחה הקדושה והרחבה<sup data-n=\"2717\">48</sup>) בנוגע לכל הענינים, ובפרט בהענין דמתן תורה, מתחיל מהדיבור הראשון אנכי גו' אשר הוצאתיך מארץ מצרים, שיוצאים מכל המיצרים וגבולים, ונעשים חד עם אנכי נותן התורה.\n<b>וענין</b> זה (דיציאה ממיצרים וגבולים) בא בהנשמה כמו שהיא מלובשת בגוף, לאורך ימים ושנים טובות, גוף בריא ונשמה בריאה. וע\"י לימוד גליא דתורה (הגוףדתורה<sup data-n=\"2718\">49</sup>) ופנימיות התורה (נשמתא דאורייתא<sup data-n=\"2718\">49</sup>) ששניהם הם תורה אחת, נעשים גם הגוף והנשמה של האדם הלומד מציאות אחת, מציאות שהיא חד עם אנכי, נותן התורה.\n<b>וע\"י</b> שמכריזים על ענינים אלו בבית גדול, בית שמגדלין בו תורה<sup data-n=\"2719\">50</sup> ובית שמגדלין בו תפלה<sup data-n=\"2720\">51</sup>, דתפלה הוא בקשת כל צרכיו, הן צרכיו הרוחניים והן צרכיו הגשמיים, הנה עי\"ז ניתוסף עוד יותר בכל הנ\"ל, שהקב\"ה עוזר לקיים את כל ההחלטות (שהם גם בקשה ותפלה) דההכנות למתן תורה, וגם ממלא הבקשות בנוגע לההמשכה דמ\"ת [ובפרט שנמצאים בבית שמגדלין בו תורה], שהמשכת התורה תהי' בשלימות ובאופן חדש לגמרי כנ\"ל, ועד לתורה חדשה מאתי תצא<sup data-n=\"2721\">52</sup> בגאולה האמיתית והשלימה ע\"י משיח צדקנו. ולהוסיף, דענין מתן תורה הוא – נתינת התורה למטה בארץ, ובאופן ש<i>לא</i> בשמים היא<sup data-n=\"2722\">53</sup>. וכמחז\"ל<sup data-n=\"2723\">54</sup> שהקב\"ה אומר למלאכי השרת אני ואתם נלך אצל ב\"ד של מטה כו'.\n<b>ועפ\"ז</b> כשישראל למטה פוסקים פס\"ד ע\"פ תורה שהגיע כבר זמן הגאולה (כי כלו כל הקצין<sup data-n=\"2724\">55</sup> וישראל כבר עשו תשובה<sup data-n=\"2725\">56</sup>) – כן יקום ותיכף ומיד באה הגאולה.\nו) <b>ולהוסיף</b> שחג השבועות שייך למשה רבינו<sup data-n=\"2726\">57</sup>, דמשה<sup data-n=\"2727\">58</sup> קיבל תורה מסיני ומסרה וכו' עד לאנשי כנסת הגדולה שהם אמרו העמידו תלמידים הרבה, שבזה (תלמידים הרבה) נכלל כל אחד מישראל, אנשים נשים וטף. [ויש לומר דפירוש <i>העמידו</i> תלמידים הרבה הוא גם שכל אחד מהתלמידים (היינו כל א' מישראל) נעשה עמוד, שעל ידו מתקיימים כל ג' העמודים שעליהם העולם עומד].\n<b>וחג</b> השבועות שייך לדוד המלך ולהבעש\"ט<sup data-n=\"2726\">57</sup> שיום ההילולא שלהם הוא בחגה\"ש. ומכיון שהענין דחידוש הבריאה הוא פירוש הבעש\"ט על הפסוק לעולם ה'דברך נצב בשמים, פסוק בתהלים שנאמר ע\"י דוד נעים זמירות ישראל, לכן, ימי חגה\"ש הם מסוגלים ביחוד ללימוד והפצת התורה באופן דהעמידו תלמידים הרבה, ושהלימוד וההפצה בכל יום, ועאכו\"כ בכל שנה, יהיו באופן דמעלין בקודש ועד באופן של חידוש, שע\"י החידוש בתורה נתגלה (כנ\"ל) החידוש דהבריאה, שכל הנבראים מתחדשים מאין ליש בכל רגע.\n<b>ועד\"ז</b> הוא לאידך, שע\"י לימוד והפצת הענין דחידוש הבריאה בכל רגע, שהוא מהענינים העיקריים דתורת החסידות, עי\"ז מקרבים וממהרים את הגאולה העתידה, שאז יהי' אמיתית החידוש בתורה, תורה חדשה מאתי תצא. ויש לומר, דזהו גם הקשר דהתחלת התורה עם ההתחלה דמתן תורה, דהתחלת התורה הוא בראשית ברא אלקים את השמים ואת הארץ, ומזה באים לוידבר אלקים את כל הדברים גו' לההתחלה דמ\"ת אנכי ה\"א אשר הוצאתיך מארץ מצרים שבזה נכלל גם גאולה העתידה דכימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"2728\">59</sup>. ועד\"ז הוא במשנה תורה (להרמב\"ם) שההתחלה היא שיש שם מצוי ראשון והוא ממציא כל נמצא וכל הנמצאים משמים וארץ ומה שביניהם לא נמצאו אלא מאמתת המצאו [די\"ל שמשמים וארץ ומה שביניהם הוא ע\"ד את השמים ואת הארץ, את השמים לרבות צבא השמים ואת הארץ לרבות צבא הארץ<sup data-n=\"2729\">60</sup>], ומזה באים להסיום דמשנה תורה – ענין הגאולה, ועד להסיום והחותם דמשנה תורה<sup data-n=\"2730\">61</sup> – כי מלאה הארץ דיעה את הוי' כמים לים מכסים<sup data-n=\"2731\">62</sup>.\nז) <b>וע\"י</b> מעשינו ועבודתינו, ובפרט בההכנות למתן תורה וקבלת התורה, ובפרט לאחרי שסיימו כבר ספירת העומר וביררו כל המדות מחסד שבחסד עד מלכות שבמלכות, דספירת העומר היא הכנה למתן תורה שמתחלת באנכי גו' אשר הוצאתיך מארץ מצרים (ענין הגאולה), ובפרט שבהמשך לספה\"ע אומרים עלינו לשבח כו' עד להסיום והי' הוי' למלך על כל הארץ ביום ההוא יהי' הוי' אחד ושמו אחד<sup data-n=\"2732\">63</sup>, [דענין והי' הוי' למלך על כל הארץ שייך לספירת המלכות ובפרט מלכות שבמלכות], ולאחרי זה אומרים אך צדיקים יודו לשמך ישבו ישרים את פניך<sup data-n=\"2733\">64</sup>, וכל זה הכריזו בצבור במקום שמגדלין בו תורה ומגדלין בו תפלה, הרי בודאי שמיד תבוא הגאולה, ותהי' השלימות דמלכות – מלכות בית דוד, וגם מלכותו של משה<sup data-n=\"2734\">65</sup> וכן דהבעש\"ט ודכל הנשיאים שלאחריו, ודמאן מלכי רבנן<sup data-n=\"2735\">66</sup>, וכל זה יהי' מיד, דלא עיכבן אפילו כהרף עין<sup data-n=\"2736\">67</sup>, ומתוך שמחה וטוב לבב, ולמטה מעשרה טפחים, ותיכף ומיד ממש.\n**********",[["2669","*","יצא לאור בשעתו, \"בזה הננו מוציאים לאור . . <i>מוצחה\"ש וש\"ק תשמ\"ט</i>\"."],["2670","1","יתרו כ, ב. ואתחנן ה, ו."],["2671","2","שו\"ע אדה\"ז או\"ח ר\"ס תצד."],["2672","3","שבת פח, א."],["2673","4","פרש\"י משפטים כד, ד."],["2674","5","ד\"ה למען תזכור בס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' תא ואילך (וראה בהנסמן בהערות שם). ד\"ה אנכי ה' אלקיך תרכ\"ו (סה\"מ תרכ\"ו ע' ס). עטר\"ת (סה\"מ עטר\"ת ע' שס ואילך). ד\"ה החודש ה'ש\"ת פ\"ב ואילך (סה\"מ ה'ש\"ת ע' 20 ואילך). ועוד."],["2675","6","ראב\"ע עה\"פ יתרו שם, ד\"ה שאלני ר\"י הלוי."],["2676","7","כמו שמדייק בד\"ה אנכי תרכ\"ו בתחלתו."],["2677","8","אגה\"ק ס\"כ (קל, ריש ע\"ב). וראה בארוכה סה\"מ תש\"ז ע' 238 (וראה גם אגה\"ק שם), דנוסף לזה <i>שהתהוות</i> היש היא בכח העצמות, הנה גם בהיש עצמו יש דוגמת הענין דמציאותו מעצמותו."],["2678","9","ראה בארוכה סה\"מ תרכ\"ט ע' קמח ובכ\"מ, שהעולם הוא מציאות ולא דמיון."],["2679","10","וראה ביאוה\"ז לאדהאמ\"צ בשלח מג, ג."],["2680","11","תהלים קיט, פט."],["2681","12","שעהיוה\"א בתחלתו."],["2682","13","ראה סה\"מ עטר\"ת ע' תלח-ט וסה\"מ ה'ש\"ת ע' 116 ואילך, דזה שהתורה מתחדשת תמיד היא דוגמת ההתחדשות דמע\"ב."],["2683","14","ראה סה\"מ עטר\"ת שם (וראה גם שם ע' תמז), שהתורה \"צריכה להתחדש תמיד מן העצמות\"."],["2684","15","בברכת התורה."],["2685","16","פרש\"י יתרו יט, א. עקב יא, יג. תבוא כו, טז. וראה גם המכתב דר\"ח סיון שנה זו (נדפס גם בהתוועדויות תשמ\"ט ח\"ג ע' 236. ובכ\"מ). וש\"נ."],["2686","17","ראה סה\"מ ה'ש\"ת שם ע' 117 בענין המחדש בטובו בכל יום תמיד מע\"ב, ד\"בכל יום\" הוא לאו דוקא אלא בכל רגע. ולהעיר שכן הוא במרז\"ל בכל יום יהיו בעיניך חדשים, שהכוונה היא בכל רגע."],["2687","18","תו\"א יתרו סז, ב. לקו\"ת שה\"ש מב, א. ובכ\"מ."],["2688","19","יתרו כ, א."],["2689","20","ראה חגיגה ג, ב ובכמה מדרשי רז\"ל – הובאו בלקו\"ת במדבר טו, ג."],["2690","21","ברכות כב, א."],["2691","22","בראשית א, א."],["2692","23","הל' יסוה\"ת פ\"א ה\"א."],["2693","24","שם ה\"ב. וראה בה\"פירוש\" שם ה\"ג."],["2694","25","ועד\"ז הוא לאידך, דזה ש\"לא הי' צריך להתחיל את התורה אלא מהחודש הזה לכם\" (פרש\"י ר\"פ בראשית), ענין יציאת מצרים – הכוונה בזה היא, שהתורה <i>מתחלת</i> בהחודש הזה לכם, אלא שענין זה הוא בתושבע\"פ דהתחלת התורה."],["2695","26","דתורה בפירושה ניתנה (הקדמת הרמב\"ם לספר היד בתחלתה)."],["2696","27","דכיון שכל הענינים שבעולם נמשכים מענינם בתורה (זח\"ב קסא, סע\"א ואילך) – לכן, ע\"י גילוי הענין בתורה, נתגלה גם הענין בעולם, שמשתלשל ממנו."],["2697","28","בהר כה, נה."],["2698","29","פרש\"י שם."],["2699","30","ראה אוה\"ת במדבר ע' קסד, שע\"י שהקדימו נעשה לנשמע \"עוררו למעלה בחי' גילוי רעד\"ר כו' גרמו ענין מ\"ת\"."],["2700","31","תנחומא וארא טו. שמו\"ר פי\"ב, ג. ועוד."],["2701","32","אסתר ט, כח. וראה רמ\"ז בס' תיקון שובבי\"ם, הובא ונתבאר בס' לב דוד להחיד\"א פכ\"ט."],["2702","33","ברכות כח, א. וש\"נ."],["2703","34","לשון אדה\"ז בתניא רפל\"ז."],["2704","35","יתרו יט, ב ובפרש\"י."],["2705","36","שו\"ע אדה\"ז סוף הל' פסח (סו\"ס תצד). וע\"פ מ\"ש בפנים יומתק מה שמאריך בשו\"ע שם בפרטי הענינים שהיו בהימים שלפני מ\"ת – אף שענינו דהשו\"ע הוא הלכות ופסקי דינים וטעמיהם – כי גם זה הוא <i>הלכה</i>, שבכל יום (בכל שנה) צריכה להיות העבודה בהענין שהי' ביום זה בפעם הראשונה. [אלא שעפ\"ז צע\"ק שאינו מביא שם הענין דהקדמת נעשה לנשמע]."],["2706","37","\"היום יום\" ג' וד' סיון."],["2707","38","לקו\"ש חכ\"ג ע' 250 ואילך."],["2708","39","פסיקתא דר\"כ (הובא ברוקח סרצ\"ו) עה\"פ בחודש השלישי."],["2709","40","שהש\"ר פ\"א, ד."],["2710","41","ראה ס' השיחות תש\"א ע' 144. אגרות קודש אדמו\"ר מהוריי\"צ ח\"א ע' שפד. ע' תפא."],["2711","42","ראה גם שיחת ש\"פ אחרי שנה זו (תשמ\"ט) ס\"ט ואילך (התוועדויות תשמ\"ט ח\"ג ע' 68 ואילך). וראה גם שם ע' 72 ואילך (בקשר לעריכת כינוסי תורה בהמשך לחגה\"פ)."],["2712","43","ראה שו\"ע אדה\"ז או\"ח סו\"ס רנ."],["2713","44","שבת פח, א."],["2714","45","תהלים עו, ט."],["2715","46","אבות פ\"א מ\"ב.\nלהעיר מהמבואר בד\"ה צאינה וראינה עזר\"ת (ע' רכה) וד\"ה בשעה שהקדימו תשי\"ב (תורת מנחם – התוועדויות ח\"ה ס\"ע 228 ואילך), דנוסף לשני הכתרים שכנגד נעשה וכנגד נשמע – יש גם כתר שלישי כנגד <i>שהקדימו</i> נעשה לנשמע. ושם, שזהו\"ע ג' העטרות שבויק\"ר פ' קדושים (פכ\"ד, ח), שנים נתן בראש בניו [כתר שכנגד נעשה וכתר שכנגד נשמע] ואחד נטל לעצמו [הכתר <i>דהקדמת</i> נעשה לנשמע]. וע\"פ הידוע (סה\"מ עטר\"ת ע' שפז, שצה. ובכ\"מ) שג' העטרות שבויק\"ר שם הם ג' הקוין דתורה עבודה וגמ\"ח – מובן, שג' קוין אלו שייכים לחמישי בסיון (שאז הקדימו נעשה לנשמע ונמשכו כל הג' כתרים)."],["2716","47","סז, ג."],["2717","48","ברכה השלישית דברכת המזון."],["2718","49","זח\"ג קנב, א."],["2719","50","דע\"י שמגדלין בו תורה שנקראת בשם בית, גם הבית (כפשוטו) נעשה בית גדול. דזהו גם מהטעמים שהקיום דבית בישראל הוא* כשהבית קשור עם תורה."],["2720","51","מגילה כז, א."],["2721","52","ישעי' נא, ד. ויק\"ר פי\"ג, ג."],["2722","53","שלכן אין משגיחין בבת קול (ב\"מ נט, ב), דענין זה נתחדש במ\"ת. ולהעיר משבת פט, א \"תורה היכן היא כו' נתתי' לארץ\", שלכאורה, מכיון שתורה היא דבר רוחני, הרי ע\"י נתינתה לארץ אין הכרח (לכאורה) שתנטל מהשמים ואפשר להיות כמדליק מנר לנר. וע\"פ הנ\"ל מובן, כי נתינת התורה לארץ היתה באופן ש(בנוגע <i>לפס\"ד</i>) <i>ניטלה</i> מן השמים. וע\"ד וכמארז\"ל \"אמר להם הקב\"ה לישראל, לשעבר הי' בידי כו' מכאן ואילך הרי מסורה בידכם כו'\" (שמו\"ר פט\"ו, ב)."],["2723","54","דב\"ר פ\"ב, יד. וראה שמו\"ר שבהערה הקודמת."],["2724","55","סנהדרין צז, ב."],["2725","56","כפס\"ד כ\"ק מו\"ח אדמו\"ר שאנחה של יהודי היא תשובה גדולה (\"היום יום\" ג' תמוז. אגרות קודש שלו ח\"ג ס\"ע תקנא. סה\"מ תרפ\"ז ע' ד)."],["2726","57","ע\"ד השייכות דחגה\"ש למשה רבינו, לדוד המלך ולהבעש\"ט – ראה בארוכה לקו\"ש ח\"ח ע' 21 ואילך. ע' 249 ואילך. ועוד."],["2727","58","אבות רפ\"א.\n*) <i>להעיר מהל' ת\"ת לאדה\"ז פ\"ד ה\"ח (מסנהדרין צב</i>,<i> א) כל בית כו'</i>."],["2728","59","מיכה ז, טו."],["2729","60","ראה פרש\"י עה\"פ בראשית א, יד."],["2730","61","סוף הל' מלכים."],["2731","62","ישעי' יא, ט."],["2732","63","זכרי' יד, ט."],["2733","64","תהלים קמ, יד."],["2734","65","ויהי בישורון מלך זה משה (מדרש תהלים בתחלתו. שמו\"ר פמ\"ח, ד. הובא ברמב\"ן ברכה לג, ה)."],["2735","66","ראה גיטין סב, א. נדרים כ, ב."],["2736","67","מכילתא ופרש\"י בא יב, מא."]]],[1500380048,"<h3>בס\"ד. ליל א' דחג השבועות (לפנות בוקר) ה'תשכ\"ה<sup data-n=\"2737\">*</sup></h3>\n<b>בשעה</b><sup data-n=\"2738\">1</sup> שעלה משה למרום אמרו מלאכי השרת לפני הקב\"ה, רבש\"ע, מה לילוד אשה בינינו, אמר להן לקבל תורה בא, אמרו לפניו, חמדה<sup data-n=\"2739\">2</sup> גנוזה כו' אתה מבקש ליתנה לבשר ודם כו' תנה הודך על השמים<sup data-n=\"2740\">3</sup>, אמר לו הקב\"ה למשה החזיר להן תשובה כו', אמר לפניו, רבש\"ע, תורה שאתה נותן לי מה כתיב בה<sup data-n=\"2741\">4</sup> אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים כו', למצרים ירדתם כו' תורה למה תהא לכם, שוב מה כתיב בה<sup data-n=\"2742\">5</sup> לא יהי' לך אלקים אחרים, בין עמים אתם שרויין שעובדין ע\"ז, שוב מה כתיב בה<sup data-n=\"2743\">6</sup> זכור את יום השבת לקדשו, כלום אתם עושים מלאכה שאתם צריכין שבות, שוב מה כתיב בה<sup data-n=\"2744\">7</sup> לא תשא, משא ומתן יש ביניכם, שוב מה כתיב בה<sup data-n=\"2745\">8</sup> כבד את אביך ואת אמך, אב ואם יש לכם, שוב מה כתיב בה<sup data-n=\"2746\">9</sup> לא תרצח לא תנאף לא תגנוב, קנאה יש ביניכם יצה\"ר יש ביניכם. [ויש לומר, שבהתשובה דמשה רבינו על טענת המלאכים, שני ענינים בכללות. למצרים ירדתם היא תשובה בנוגע לכללות התורה, דכיון שהטעם על כללות הענין דמתן תורה הוא אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים, לכן, כיון שלמצרים ירדתם (בתמי') תורה למה תהא לכם, ולאח\"ז מוסיף שוב מה כתיב בה, שגם הציוויים הפרטים שבתורה (לא יהי' לך, זכור את יום השבת, וכו') שייכים לישראל ולא למלאכים].\n<b>וצריך</b> להבין, דבקשת המלאכים תנה הודך על השמים היתה שתנתן להם תורה כמו שהיא ברוחניות, ומה השיב להם משה כלום אתם עושים מלאכה וכו'. גם צריך להבין מה שהשיב משה בנוגע להמצוות לא תרצח לא תנאף לא תגנוב קנאה יש ביניכם יצה\"ר יש ביניכם, דכיון שהמלאכים אין קנאה ביניהם ואין להם יצה\"ר לכן אין צריך לצוות ולהזהיר אותם על מצוות אלו, דלכאורה עדיפא הוה לי' למימר, שגם המצוות עצמם (כמו שהם בגשמיות) אינם שייכים למלאכים (כמו שאמר לפנ\"ז בנוגע למצות שבת, לא תשא, וכיבוד אב ואם).\n<b>והענין</b> הוא, דבהטעם על זה שהתורה ניתנה למטה בארץ דוקא, שני ענינים. לפי שההמשכה שע\"י המצוות היא כשקיום המצוות הוא בגשמיות, וגם לפישע\"י קיום המצוות למטה נעשה הבירור דנפש הבהמית<sup data-n=\"2747\">10</sup>. וזהו שאמר משה כלום אתם עושים מלאכה כו' יצה\"ר יש ביניכם, דהטעם שהתורה לא ניתנה בשמים למלאכים הוא כי אז היו חסרים שני הענינים. כלום אתם עושים מלאכה שאתם צריכים שבות, ולכן אין שייך שיקיימו מצות שבת בגשמיות ועד\"ז הוא בנוגע לא תשא, כיבוד אב ואם. יצה\"ר יש ביניכם<sup data-n=\"2748\">11</sup> ולכן אין שייך אצלם בירור נפש הבהמית.\nב) <b>ויש</b> לומר, דבהשייכות דבירור נפש הבהמית (יצה\"ר יש ביניכם) למתן תורה, שני ענינים. שע\"י קיום המצוות שניתנו במתן תורה נעשה בירור נפש הבהמית, כנ\"ל. ושבירור נפש הבהמית הוא גם הכנה למתן תורה. שלכן סופרים ספירת העומר לפני חג השבועות, כי ספירת העומר הוא בירור המדות דנפש הבהמית, ועי\"ז זוכים בחגה\"ש למתן תורה<sup data-n=\"2749\">12</sup>. ועפ\"ז, הענין דיצה\"ר יש ביניכם (ענין האחרון שבתשובת משה) הוא ע\"ד הענין דלמצרים ירדתם (ענין הראשון שבתשובת משה), שבהשייכות דיצי\"מ למתן תורה, שני ענינים. שע\"י מתן תורה, המשכת וגילוי אנכי הוי' אלקיך, נעשה אשר הוצאתיך מארץ מצרים<sup data-n=\"2750\">13</sup>, ושיציאת מצרים היא הקדמה והכנה למתן תורה, כפירוש הפשוט באנכי הוי' אלקיך אשר הוצאתיך מארץ מצרים, דאשר הוצאתיך מארץ מצרים הוא טעם על אנכי הוי' אלקיך<sup data-n=\"2751\">14</sup>. וצריך להבין, דענין מתן תורה הוא (כמ\"ש בהפתיחה דמתן תורה) אנכי הוי' אלקיך, שאנכי הוא מהותו ועצמותו נעשה הוי' אלקיך<sup data-n=\"2752\">15</sup>, ואיך שייך שע\"י העבודה דבירור נפש הבהמית תהי' המשכת אנכי.\nג) <b>והנה</b> איתא במדרש<sup data-n=\"2753\">16</sup> עה\"פ<sup data-n=\"2754\">17</sup> וספרתם לכם ממחרת השבת גו' שבע שבתות תמימות תהיינה אימתי הן תמימות בזמן שישראל עושין רצונו של מקום. וע\"פ המבואר בכ\"מ<sup data-n=\"2755\">18</sup> דענין עושין רצונו של מקום הוא דוקא ע\"י האהבה דבכל מאדך, למעלה ממדידה והגבלה, מובן, דמ\"ש במדרש אימתי הן תמימות בזמן שישראל עושין רצונו של מקום, הוא, כשהעבודה דספה\"ע קשורה עם האהבה דבכל מאדך. [ולהעיר, דבמק\"א ארז\"ל<sup data-n=\"2756\">19</sup> דשבע שבתות תמימות הוא דשבע השבתות דספה\"ע מתחילות באחד בשבת ומסיימות בשבת שבשבת, שאז הם שבע שבתות תמימות.ויש לומר הקשר דשני הפירושים, דבאותם השנים ששבע שבתות דספה\"ע מתחילות באחד בשבת ומסיימות בשבת<sup data-n=\"2757\">20</sup>, בנקל יותר, שהעבודה דספה\"ע תהי' באופן דבכל מאדך]. ולכאורה יש לומר, שהשייכות דעושין רצונו של מקום (בכל מאדך) לספירת העומר, היא, כי ספירת העומר היא הכנה למתן תורה, וכיון שההכנה למתן תורה צריכה להיות בשני ענינים, יציאת מצרים ובירור נפש הבהמית, לכן, צריך להיות בספירת העומר (נוסף להענין דבירור המדות דנה\"ב, גם) העבודה דבכל מאדך, למעלה ממדידה והגבלה, היציאה ממצרים מלשון מיצר והגבלה. וצריך להבין דלפ\"ז, העבודה דבכל מאדך היא הכנה מוכרחת למתן תורה, ומזה שאמרו אימתי הן תמימות כו' משמע שעיקר הענין דספה\"ע, הכנה למתן תורה, הוא בירור המדות דנה\"ב, והעבודה דבכל מאדך שייכת רק לשלימות ההכנה למ\"ת. וביותר אינו מובן, דכיון שענין מתן תורה הוא הגילוי דאנכי, מהותו ועצמותו שלמעלה מעלה מגדר השתלשלות<sup data-n=\"2758\">21</sup>, הרי העבודה המתאימה להמשכת גילוי זה הוא לכאורה העבודה דבכל מאדך (למעלה מהשתלשלות שבאדם), ואעפ\"כ, <i>עיקר</i> העבודה דספה\"ע הוא בירור המדות דנפש הבהמית [שבכדי לברר המדות דנה\"ב הוא דוקא ע\"י שנפש האלקית <i>מתלבשת</i> בנפש הבהמית<sup data-n=\"2759\">22</sup>], ועי\"ז נמשך הגילוי דאנכי.\nד) <b>ויובן</b> זה בהקדים מ\"ש<sup data-n=\"2760\">23</sup> כמים הפנים לפנים כן לב האדם לאדם, ומבואר בחסידות<sup data-n=\"2761\">24</sup> דלב האדם לאדם קאי לא רק על שני בני אדם, דלב האדם באהבתו לחבירו מעורר אהבת חבירו אליו, אלא גם על אדם התחתון ואדם העליון, דכפי אופן העבודה של אדם התחתון, אתערותא דלתתא, כן הוא אופן האתערותא דלעילא, ההמשכה מאדם העליון לאדם התחתון, כמים הפנים לפנים<sup data-n=\"2762\">25</sup>. ויש לומר, שהדמיון דלב האדם לאדם למים הפנים לפנים הוא<sup data-n=\"2763\">26</sup>, דכמו שבמים הפנים לפנים, זה שנראה להאדם אותה הצורה שהוא מראה בהמים הוא לפי שע\"י הסתכלותו בהמים נעשים (נראים) בהמים צורת הפנים המסתכלת בהם וצורה זו נראית אח\"כ לאדם המסתכל, כן הוא בלב האדם לאדם, דזה שע\"י העבודה והאתערותא דלתתא של אדם התחתון נעשה אתערותא דלעילא והמשכה מאדם העליון לאדם התחתון, הוא, כי העבודה דאדם התחתון עולה מלמטה למעלה, לאדם העליון, ועי\"ז נעשה בו (דוגמת) ענין זה, ואח\"כ נמשך ענין זה (שנעשה באדם העליון) מלמעלה למטה, לאדם התחתון. ולהוסיף, דבמשל המים, זה שפני האדם שמסתכל בהמים נראים בהמים, הוא רקשנראה כן לעין הרואה, ובהנמשל, ע\"י העבודה דאדם התחתון נעשה<sup data-n=\"2764\">27</sup> (דוגמת) ענין זה באדם העליון (ולא רק שנראה כן)<sup data-n=\"2765\">28</sup>.\n<b>והנה</b><sup data-n=\"2766\">29</sup> כמו שלב האדם לאדם הוא (לא רק כפשוטו, אלא) גם ברוחניות (באדם העליון ואדם התחתון), כמו\"כ הוא גם בנוגע להתחלת הכתוב כמים הפנים לפנים, שמדבר (לא רק במים כפשוטם, אלא) גם במים העליונים, היינו הפשיטות דאוא\"ס שלמעלה מציור אדם. וענין כמים הפנים לפנים הוא, דהגם שאוא\"ס הוא פשוט בתכלית הפשיטות ואין שייך בו ציור דספירות, מ\"מ, ע\"י העלאת מ\"ן דהספירות לאוא\"ס, נעשים בו ספירות – עשר ספירות הגנוזות<sup data-n=\"2767\">30</sup>, וע\"ס הגנוזות הם כמו מקור שמהם נמשכים ע\"ס הגלויות [ע\"ד שני הענינים דכמים הפנים לפנים במים כפשוטם, שדמות הפנים המסתכלת בהם נראית בהמים, העלאה מלמטה למעלה, ושהדמות הנראית בהמים היא נראית אח\"כ להאדם המסתכל, המשכה מלמעלה למטה].\n<b>וצריך</b> להבין, דמזה שנאמר כמים הפנים לפנים כן לב האדם לאדם משמע, דענין מים הפנים לפנים הוא פשוט יותר מענין לב האדם לאדם, ולכאורה, הרי האין ערוך דציור (\"פנים\") לגבי פשיטות (\"מים\") הוא הרבה יותר מהאין ערוך של הציור דאדם התחתון לגבי הציור דאדם העליון [כמאמר הידוע<sup data-n=\"2768\">31</sup> יותר משאין ערוך עשי' לגבי אצילות אין ערוך אצילות לגבי אוא\"ס], ועפ\"ז, זה שע\"י העלאת מ\"ן נעשה ציור דספירות באוא\"ס הוא לכאורה חידוש גדול הרבה יותר מזה שהציור דאדם התחתון נעשה באדם העליון, ומזה שנאמר כמים הפנים לפנים כן לב האדם לאדם משמע, דענין מים הפנים לפנים הוא פשוט יותר<sup data-n=\"2769\">32</sup>.\nה) <b>ולכאורה</b> אפשר לבאר זה בהקדים דהטעם על זה שכשמסתכלים במים נראית בהם דמות הפנים המסתכלת בהם הוא לפי שהמים הם חומר זך וצלול שפשוט מכל הגוונים<sup data-n=\"2770\">33</sup> [משא\"כ כשמסתכלים בדבר שיש בו ציור, הציור (הגוון) של הדבר הוא סותר להציור של הפנים שמסתכל בו<sup data-n=\"2771\">34</sup>], ולכן, הענין דמים הפנים לפנים (שע\"י העלאת מ\"ן נעשה ציור באוא\"ס), הוא פשוט יותר מהענין דלב האדם לאדם. אבל ביאור זה צריך לביאור נוסף, דלכאורה, זה שבדבר הפשוט נראים כלהציורים הוא דוקא כשהגוונים והדבר פשוט הם באותו הסוג, היינו ששניהם הם גשמיים (כמו המים והפנים שמסתכלים בהם) או ששניהם הם רוחניים [ע\"ד סברא פשוטה שמצד פשיטותה היא יכולה להצטייר הן בציור דחסד והן בציור דגבורה<sup data-n=\"2772\">35</sup>, ששניהם (הסברא והציורים דחו\"ג) הם רוחניים], אבל אין שייך שבדבר הפשוט יהיו נראים ציורים שמסוג אחר [כמו סברא שכלית, שאין שייך שתצטייר בלובן ואודם (גשמיים), וכן לאידך שאין שייך שבמים גשמיים יהיו נראים ציורים דחו\"ג], וכיון שאוא\"ס הוא מופשט לא רק מהציור דספירות אלא גם מהמציאות דספירות [דכמו שענין רוחני הוא מופשט מהמציאות דגשמיות<sup data-n=\"2773\">36</sup>, עד\"ז הוא בנוגע לאוא\"ס שהוא מופשט מהמציאות דספירות. כי המציאות דספירות הוא שהם נתפסים באיזה גדר (חכמה, בינה, וכו'), וכיון שאוא\"ס הוא פשוט בתכלית הפשיטות ואין שייך בו תפיסא, הרי הוא מופשט מהמציאות דספירות], ואיך שייך שע\"י העלאת מ\"ן יצטיירו בו ספירות.\n<b>והביאור</b> בזה, ע\"פ הידוע<sup data-n=\"2774\">37</sup> דזה שאתערותא דלתתא מעוררת וממשכת אתערותא דלעילא [גם האתעדל\"ע שבבחינת אדם העליון, אצילות], הוא לא ע\"פ טעם ושכל, דכיון שנברא הוא באין ערוך לגבי בורא, הרי ע\"פ שכל אין מקום שעבודת הנבראים תעורר (תפעול <i>שינוי</i><sup data-n=\"2775\">38</sup>) בהענינים דלמעלה, אלא לפי שכן עלה במחשבה הקדומה דא\"ק [שלפני האצילות] שע\"י עבודת הנבראים תהי' התעוררות והמשכת הענינים דאצילות. ומזה מובן במכש\"כ בהענין דמים הפנים לפנים, דזה שע\"י העלאת מ\"ן דבחינת פנים, ע\"ס דאצילות, נעשה אתערותא דלעילא בבחינת מים העליונים, בהפשיטות דאוא\"ס שלמעלה מבחינת אדם, הוא לפי שכן עלה ברצונו ית', בעצמות אוא\"ס שלמעלה גם מבחינת מים. ויש לומר, דע\"י שעלה ברצונו ית' שע\"י העלאת מ\"ן דבחינת פנים (ע\"ס דאצילות) תהי' ההמשכה מבחינת מים העליונים, עי\"ז, נעשה להם שייכות לבחינת הפנים שממשיכים אותם, <i>בדוגמת</i> מים כפשוטם, שהם והפנים (שמסתכלים בהם) הם באותו הסוג. ולכן, האתעדל\"ע בבחינת המים שע\"י העלאת מ\"ן דהספירות הוא (לא רק התעוררות שתהי' המשכת אוא\"ס בספירות, אלא גם) שבהפשיטות דאוא\"ס עצמו נעשה ענין הספירות, ע\"ס הגנוזות, בדוגמת מים כפשוטם, שנראית בהם עצמם הפנים המסתכלת בהם.\nו) <b>ויש</b> לומר, דהטעם על זה שעלה ברצונו שההמשכה דלמעלה (אתערותא דלעילא) תהי' ע\"י אתערותא דלתתא דוקא, הוא<sup data-n=\"2776\">39</sup>, כי השורש דישראל (דעיקר עניןאתעדל\"ת הוא ע\"י עבודתם של ישראל) הוא בעצמות. וכמ\"ש הרב המגיד<sup data-n=\"2777\">40</sup> בפירוש מאמר רז\"ל<sup data-n=\"2778\">41</sup> ישראל עלו במחשבה, שהוא כמשל אדם שיש לו בן, שמצד גודל אהבתו אליו, נחקקה צורת הבן במחשבתו. וכיון שאצלו ית' העבר והעתיד אחד, לכן נחקקה צורתם של ישראל במחשבתו ית' גם קודם שנבראו. דזהו גם ענין במי נמלך בנשמותיהן של צדיקים<sup data-n=\"2779\">42</sup>, שהתענוג דהקב\"ה בעבודת הצדיקים הי' גם לפני הבריאה (ועי\"ז היתה הבריאה)<sup data-n=\"2780\">43</sup>. וכיון שהתענוג דעבודת ישראל הוא בעצמותו ית' שלמעלה מכל הגילויים<sup data-n=\"2781\">44</sup>, לכן עלה ברצונו ית' (גם בבחינת הגילויים) שההמשכה והגילוי דלמעלה תהי' ע\"י עבודה דוקא. ועי\"ז נעשה עד\"ז גם בנוגע לכללות הענין דהעלאת מ\"ן (העלאת מ\"ן דספירות וכיו\"ב), שעלה ברצונו ית' שההמשכה דאוא\"ס תהי' ע\"י העלאת מ\"ן דהספירות. ועד\"ז הוא גם במחשבה הקדומה דא\"ק, דזה שעלה במחשבה הקדומה דא\"ק שההמשכה דלמעלה תהי' ע\"י אתערותא דלתתא דוקא, הוא, כי השורש דישראל הוא בעצמות א\"ק [וכמבואר במק\"א<sup data-n=\"2782\">45</sup> דזה שא\"ק הוא בציור אדם<sup data-n=\"2783\">46</sup> (אדם קדמון) הוא הציור דנשמות ישראל שעלו במחשבה הקדומה דא\"ק], ומזה נמשך גם בהמחשבה דא\"ק שבנוגע להשתלשלות, שכל ההמשכות [ההמשכה מאצילות לבי\"ע, וגם ההמשכה מלמעלה מאצילות לאצילות] יהיו ע\"י עבודה, העלאת מ\"ן.\nז) <b>וביאור</b> הענין דג' מדריגות הנ\"ל באוא\"ס שלמעלה מע\"ס הגנוזות [לאחרי שעלה ברצונו שיהי' תפיסת מקום להעלאת מ\"ן [שגם דרגא זו היא למעלה מע\"ס הגנוזות, כיון שע\"ס הגנוזות הם \"הפנים\" שנעשו באוא\"ס ע\"י (<i>לאחרי</i>) העלאת מ\"ן], כמו שהוא מצד עצמו (לפני עליית רצון הנ\"ל) שבדרגא זו אין שייך העלאת מ\"ן, ועצמות אוא\"ס ששם מושרש הענין דהעלאת מ\"ן] בפרטיות יותר, יובן בהקדים אופן ההעלם דע\"ס הגנוזות<sup data-n=\"2784\">47</sup>. דבהעלם יש שני אופנים<sup data-n=\"2785\">48</sup>, העלם שישנו במציאות, כמו אש שבתוך הגחלת, שעם היותו נעלם ומכוסה בהגחלת הוא מציאות אש, ולכן בכדי לגלות אותו מהעלמו אין צריך לטירחא (דע\"י שנופחים בהגחלת מתגלה האש).והעלם שאינו במציאות, כמו אש שבצור החלמיש, שאינו מציאות אש ורק כח האש, ולכן, הוצאת אש מהצור היא ע\"י הכאה, בטירחא ויגיעה. ובכחות הנפש הוא החילוק בין כחות הנעלמים לכחות הכלולים בנפש. שההעלם דכחות הנעלמים, כמו כח המשכיל, הוא העלם שישנו במציאות, וההעלם דכחות הכלולים בנפש, כמו כח השכל ההיולי העצמי, הוא <i>העלם שאינו</i> במציאות. וההעלם דע\"ס הגנוזות הוא העלם שאינו במציאות<sup data-n=\"2786\">49</sup>. כי זה שהע\"ס שלמעלה מאצילות הן גנוזות ונעלמות הוא לפי שהן כלולות באוא\"ס, ע\"ד התכללות הכחות בנפש, וההעלם דכחות הכלולים בנפש הוא העלם שאינו במציאות, כנ\"ל.\n<b>והנה</b> גם העלם שאינו במציאות הוא איזה מציאות, אלא שהמציאות שלו היא זה שהוא מקור למציאות. וכמו כח האש שבצור החלמיש, שהוא כח ומקור לאש. ומזה מובן, דזה שיש בהצור כח האש הוא דבר נוסף על הצור. וכמו\"כ הוא בכחות הכלולים בנפש, שהם <i>כחות</i> (ולא נפש), ויתירה מזו, שהם כמו מקור לכחות הגלויים. ולכן, המשל דכחות הכלולים בנפש על ע\"ס הגנוזות הוא בע\"ס דעקודים, אבל בהדרגות דע\"ס הגנוזות שלמעלה מעקודים<sup data-n=\"2787\">50</sup>, אין שייך לומר גם שהם בהעלם שאינו במציאות, אלא שאינם מציאות כלל, כהלשון (המובא בכ\"מ<sup data-n=\"2788\">51</sup>) אין מציאות לגנוזות. כי זה שנתחדש בהענין דע\"ס הגנוזות הוא רק יכולת – שיכול להיות התהוות ע\"ס וכל זמן שלא נתהוו הספירות לא ישנה מציאות דספירות, גם לא מציאות דמקור לספירות. והמשל על זה הוא משם האדם<sup data-n=\"2789\">52</sup>, דזה שנתחדש בהאדם ע\"י שיש לו שם הוא רק שבאם יקראו אותו בשמו יהי' פונה (נמשך) להקוראים אותו. דמציאותה של המשכה זו (שנפנה לקוראיו בשמו) מתחילה בעת שקוראין אותו בשמו, ולפני שקוראין אותו בשמו לא ישנה ההמשכה, גם לא מקור לההמשכה, וזה שנתחדש ע\"י שיש לו שם הוא רק יכולת – שיכולה להיות ההמשכה דנפנה לקוראיו בשמו.\n<b>והנה</b> כמו שהוא בנוגע לשם האדם (ראובן, שמעון), עד\"ז הוא בנוגע לשמות התואר והמעלה, דכשקוראין לאדם בשם חכם או חסיד וכיו\"ב, ע\"י שבחים אלה מעוררים את כח החכמה והחסד שבו שיומשכו מההעלם אל הגילוי. ומבואר בתו\"א<sup data-n=\"2790\">53</sup>ובכמה דרושים<sup data-n=\"2791\">54</sup>, דעשר ספירות הגנוזות הם עשרה שמות, שע\"י הקריאה בהם, תהי' התהוות הספירות. והיינו, דכשעלה ברצונו ית' להוות הספירות, האציל תחלה עשרה שמות<sup data-n=\"2792\">55</sup>, שכל ענינם הוא רק דכאשר יקראו אותו ית' באחד משמות אלה, תתהווה אז (ע\"י הקריאה) אותה הספירה השייכת לשם זה [דע\"י שיקראו אותו בשם חכם, תתהווה ספירת החכמה, וע\"י שיקראו אותו בשם חסיד, תתהווה ספירת החסד] – בדוגמת אדם, שע\"י שקוראין אותו חכם וחסיד, נעשה המשכת החכמה והחסד. אלא שבאדם, ההמשכה ע\"י שקוראין אותו חכם וחסיד, היא רק מן ההעלם אל הגילוי, ולמעלה, ע\"י קריאת השמות נעשה עצם מציאות הספירות, דקודם הקריאה לא היו ספירות כלל, גם לא בהעלם. ע\"ד ההמשכה שע\"י קריאת שם האדם (שנפנה כשקוראין אותו בשמו), שכל מציאותה נעשית ע\"י הקריאה בשם ולפני הקריאה בשם לא היתה בהעלם (כנ\"ל).\nח) <b>והנה</b> מבואר לעיל (סעיף ד-ה) בפירוש הכתוב כמים הפנים לפנים, דכמו שבמים כפשוטם, ע\"י ההסתכלות בהם, נראית בהם דמות הפנים שמסתכלת בהם, עד\"ז הוא במים העליונים, פשיטות דאוא\"ס, שע\"י העלאת מ\"ן דהספירות (פנים) לאוא\"ס, נעשה בו ענין הספירות – ע\"ס הגנוזות. וזה שע\"י העלאת מ\"ן נעשה ספירות באוא\"ס הוא מפני שגם לפנ\"ז יש לו שייכות לספירות [בדוגמת מים, דזה שנראית בהם דמות הפנים שמסתכלת בהם הוא לפי שהמים והפנים הם באותו סוג המציאות], וצריך ביאור, דכיון שגם ע\"ס הגנוזות (הפנים הנראים בהמים) הם רק יכולת לספירות (כנ\"ל סעיף ז), ולאידך, גם האוא\"ס שלמעלה מע\"ס הגנוזות (המים שבהם נראים הפנים) יש לו שייכות לספירות, מהו החילוק שבין שני הענינים. וי\"ל הביאור בזה, דענין היכולת על איזה דבר הוא – <i>שהדבר</i> יכול להיות. דהגם שיכולת אינו מקור להדבר וענינו הוא זה שהעצם הוא יכול [כידוע החילוק בין כח ליכולת<sup data-n=\"2793\">56</sup>], מ\"מ, זה שהעצם הוא יכול, הוא – שביכולת העצם הוא שיהי' כך וכך. והשייכות דאוא\"ס לספירות (דמים לפנים) הוא (לא שמצד האוא\"ס יכול להיות <i>ספירות</i>, אלא אדרבה) שציור הספירות יכול להיות <i>באוא\"ס</i>. והגם שגם ענין זה הוא ירידה לגבי אוא\"ס כמו שהוא מצד עצמו, דבאוא\"ס מצד עצמו אין יחס כלל לענין הספירות [וכנ\"ל סעיף ה שהוא ע\"ד סברא שכלית שאין לה שום שייכות עם גוונים, לובן ואודם], אלא שלאחרי שעלה ברצונו שיהי' תפיסת מקום להעלאת מ\"ן דהספירות עי\"ז נעשה לו שייכות להספירות (כנ\"ל), מ\"מ, התפיסת מקום דהעלאת מ\"ן דהספירות הוא שהמ\"ן שלהם יתפוס מקום <i>אצלו</i>, שעל ידי ההעלאה תהי' המשכת <i>אוא\"ס</i>, ולכן, השייכות דאוא\"ס לספירות שנעשית ע\"י שהעלאת מ\"ן דהספירות תופסת מקום אצלו, היא זה <i>שבאוא\"ס</i> אפשר להיות ציור הספירות. ולכן, היכולת לספירות, כיון שענינה היא שיכול להיות <i>ספירות</i>, נקרא בשם ספירות, עשר ספירות הגנוזות, ונאמר בזה לשון האצלה[וכמובא לעיל סעיף ז מהדרושים האציל עשרה שמות], ויתירה מזה, דזה שנעשה באוא\"ס היכולת לספירות הוא לא מצד האוא\"ס אלא ע\"י העלאת מ\"ן דהספירות. והירידה כביכול באוא\"ס שיהי' באופן שע\"י העלאת מ\"ן נראים בו הפנים דהספירות, אין זה שנאצל בו איזה ענין, אלא הוא האוא\"ס עצמו, דוגמת המים שהם באופן כזה שנראית בהם הפנים המסתכלת בהם.\nט) <b>והנה</b> מבואר בהדרושים<sup data-n=\"2794\">57</sup>, שהפנים הנראים בהמים, מכיון שהם מצד הפנים המסתכלים ולא מצד המים, לכן הם לא דבר נבדל מהמים אלא המים עצמם. דבאם הפנים הנראים היו נמשכים מהמים, אזי היו דבר מובדל שנתהווה מהמים (וע\"ד דגים שבים). אבל כיון שהפנים הנראים הם לא מצד המים, אינם דבר נבדל שנתהווה מהמים אלא המים עצמם. – ועד\"ז הוא בהנמשל, דכיון דזה שבאוא\"ס ישנם עשר ספירות הגנוזות הוא ע\"י העלאת מ\"ן דהספירות (ולא שנתהוו מאוא\"ס), לכן אינם דבר נבדל מאוא\"ס אלא הוא אוא\"ס עצמו. ועפ\"ז, בע\"ס הגנוזות שני ענינים. דבחיצוניות, ענינם הוא – יכולת <i>לספירות</i>, ובפנימיות, הם – אוא\"ס.\n<b>והנה</b> מבואר לעיל סעיף ד' דבמים הפנים לפנים, שני ענינים. שדמות הפנים המסתכלת בהמים נראית בהמים, ושדמות זו נראית אח\"כ להאדם המסתכל בהם. היינו, שהדמות הנראית להאדם היא הדמות הנראית בהמים. ועד\"ז הוא בהנמשל, שע\"י העלאת מ\"ן דפנים התחתונים, ע\"ס דאצילות, נעשים פנים (ע\"ס הגנוזות) בהמים (פשיטות דאוא\"ס), ואח\"כ נמשכים ומתגלים הפנים העליונים שבהמים (ע\"ס הגנוזות) מלמעלה למטה ומזה נעשים פנים התחתונים, ע\"ס דאצילות. היינו שענינם דע\"ס הגלויות (בפנימיות) הוא – הגילוי דע\"ס הגנוזות, בדוגמת דמות הפנים הנראית לאדם המסתכל בהמים שהיא הדמות הנראית בהמים (ע\"ס הגנוזות). וע\"פ הנ\"ל שהדמות הנראית בהמים היא המים עצמם, מובן, שגם הפנים התחתונים (ע\"ס דאצילות), שהם הגילוי דפנים העליונים, ענינם הפנימי הוא – מים, פשיטות דאוא\"ס. ועפ\"ז יובן מ\"ש כמים הפנים לפנים כן לב האדם לאדם, דכמו שבמים (פשיטות דאוא\"ס), ע\"י העלאת מ\"ן נעשה בהם פנים (ספירות), כמו\"כ הוא באדם העליון, שע\"י העלאת מ\"ן דאדם התחתון נעשה הציור והדמות דאדם התחתון באדם העליון. דלכאורה, הרי הטעם על זה שבמים נראית דמות הפנים המסתכלת בהם הוא לפי שמים הם פשוטים, משא\"כ כשמסתכלים בדבר שיש בו ציור, הציור של הדבר הוא <i>סותר</i> לצורת הפנים המסתכלת בו (כנ\"ל סעיף ה), וכיון שאדם העליון (ע\"ס דאצילות) הוא בחינת ציור, איך שייך שיהי' בו הציור דאדם התחתון. והביאור בזה, דע\"י העבודה של אדם התחתון מתגלית הפנימיות דאדם העליון, ע\"ס דאצילות, שענינם הוא – הגילוי דע\"ס הגנוזות (פנים הנראים בהמים), ועד שהם המים (פשיטות דאוא\"ס) עצמם. וע\"י שמתגלה (ע\"י העבודה דאדם התחתון) הפנימיות דאדם העליון, שהוא הפשיטות דאוא\"ס, אפשר להיות בו הציור דאדם התחתון<sup data-n=\"2795\">58</sup>. ועפ\"ז יש לומרדכמים הפנים לפנים הוא גם טעם וביאור על כן לב האדם לאדם. דענין מים הפנים לפנים הוא שהפנים התחתונים הנראים מחוץ להמים (ע\"ס הגלויות) הם חד עם הפנים העליונים הנראים בהמים (ע\"ס הגנוזות) ועד שהם חד עם המים עצמם (פשיטות דאוא\"ס), וזהו הטעם על לב האדם לאדם, שבאדם העליון נעשה הציור דאדם התחתון.\n<b>ולהוסיף</b><b>,</b> דע\"פ המבואר לעיל (סעיף ו) דזה שעלה ברצונו שההמשכה דלמעלה תהי' ע\"י אתעדל\"ת הוא כי שורש האתעדל\"ת הוא בעצמות אוא\"ס שלמעלה גם מהאור כמו שהוא מצד עצמו קודם שעלה ברצונו ענין האתעדל\"ת, יש לומר, דנוסף לזה שע\"י העבודה דאדם התחתון מתגלה הפנימיות דאדם העליון שהוא חד עם הפשיטות דאוא\"ס כמו שהוא בבחינת מים [האור שיש לו שייכות לציור, דוגמת מים כפשוטם שגם לפני שמסתכלים בהם הם באופן שאפשר להיות נראה בהם הפנים שמסתכלת בהם], הנה ע\"י העבודה דאדם התחתון נמשך גם גילוי עצמות אוא\"ס שלמעלה גם מהאור כמו שהוא מצד עצמו.\nיו\"ד) <b>והנה</b><sup data-n=\"2796\">59</sup> העבודה שעל ידה מתגלה הפנימיות דאדם העליון היא בכללות העבודה דבירור נפש הבהמית. כי זה שע\"ס הגלויות הם (בחיצוניות) כמו דבר נבדל <i>שנתהוו</i> מע\"ס הגנוזות הוא מצד הפרסא בין ע\"ס הגנוזות לע\"ס הגלויות. וע\"י זיכוך נפש הבהמית נעשה זיכוך הפרסא שבין למעלה מאצילות (ע\"ס הגנוזות) ואצילות (ע\"ס הגלויות), ועי\"ז נרגש בגילוי בהע\"ס דאצילות שהם הגילוי דע\"ס הגנוזות, וכנ\"ל שהפנים שבמים <i>הם</i> הנראים להאדם. ולהוסיף, דע\"י בירור וזיכוך נה\"ב נעשה זיכוך כל הפרסאות, וגם הזיכוך דצמצום הראשון, ועי\"ז, החיבור דע\"ס הגלויות עם ע\"ס הגנוזות הוא עם כל הדרגות שבע\"ס הגנוזות, כולל גם ע\"ס הגנוזות שלפני הצמצום. ועד\"ז הוא לאידך, שע\"י זיכוך נפש הבהמית מזדככת גם הפרסא שבין אצילות לבי\"ע [דעיקר ההעלם הוא ע\"י פרסא זו], ועי\"ז נעשה החיבור דאדם התחתון עם אדם העליון. והעבודה שעל ידה נמשך הגילוי דעצמות אוא\"ס היא העבודה שמצד הנשמה (שלמעלה מהתלבשות בגוף ונה\"ב), דבכללות הוא העבודה דרעותא דלבא. כי זה שע\"י העבודה דישראל נמשך גילוי עצמות אוא\"ס הוא מצד מעלת הנשמות, דעלו במחשבה (כנ\"ל סעיף ו), ולכן המשכת גילוי זה הוא ע\"י רעותא דלבא.\nיא) <b>והנה</b> בהחידוש שנתחדש במתן תורה [בפעם הראשונה, ועד\"ז במתן תורה שבכל שנה], שני ענינים. המשכת וגילוי עצמות אוא\"ס לישראל – אנכי הוי' אלקיך, והמשכת גילוי זה הוא ע\"י רעותא דלבא. וביטול הגזירה והמחיצה בין עליונים ותחתונים<sup data-n=\"2797\">60</sup>, בכל העולמות. והמשכת גילוי זה הוא ע\"י בירור נפשהבהמית. ולכן בספירת העומר, שהיא ההכנה למתן תורה, צ\"ל שני הענינים, בירור המדות דנפש הבהמית, והאהבה דבכל מאדך (רעותא דלבא).\n<b>וזהו</b> מ\"ש וספרתם לכם גו' מיום הביאכם את עומר התנופה גו', דענין עומר <i>התנופה</i> גו' הוא כמ\"ש<sup data-n=\"2798\">61</sup> והניף את העומר גו' לרצונכם, לרצונכם הוא רעותא דלבא, וע\"י רצון זה (דהאדם) עושים וממשיכים רצונו של מקום. וזהו אימתי הן תמימות בזמן שישראל עושין רצונו של מקום, דהמשכה זו הו\"ע התמימות, אמיתית השלימות.\n**********",[["2737","*","יצא לאור ב<b>קונטרס חג השבועות – תנש\"א</b>, \"לקראת חג השבועות . . <i>ימי הגבלה</i>,<i> סיוון</i>,<i> שנת ה'תנש\"א</i>\"."],["2738","1","שבת פח, סע\"ב ואילך."],["2739","2","בש\"ס שם: חמודה, אבל כ\"ה (חמדה) בעין יעקב כאן. ועוד."],["2740","3","תהלים ח, ב."],["2741","4","יתרו כ, ב."],["2742","5","שם, ג."],["2743","6","שם, ח."],["2744","7","שם, ז."],["2745","8","שם, יב."],["2746","9","שם, יג."],["2747","10","להעיר מסה\"מ תרע\"ח ע' קסז ואילך וסה\"מ תש\"ו ע' 104 ואילך, דזה שהמצוות דהאבות ריחות היו אבל אנו שמן תורק שמך (שהש\"ר פ\"א, ג (א)), הוא, מצד שני ענינים: כי אצל האבות לא היו העלמות והסתרים מצד הגוף (נה\"ב), ולא הי' להם מצוות בגשמיות."],["2748","11","וגם \"בין עמים אתם שרויין שאתם עובדין ע\"ז\" הוא דוגמת \"יצר הרע יש ביניכם\", ואדרבה יצה\"ר שהוא דוגמת \"שד משדין נוכראין\" (בין עמים אתם שרויין) ועד שצריך להזהירו שלא יעבוד ע\"ז."],["2749","12","לקו\"ת במדבר טז, ד. ובכ\"מ."],["2750","13","תו\"א יתרו סז, סע\"ב."],["2751","14","פרש\"י עה\"פ (יתרו כ, ב)."],["2752","15","תו\"א שם. לקו\"ת שם."],["2753","16","ויק\"ר פכ\"ח, ג."],["2754","17","אמור כג, טו."],["2755","18","או\"ת להמגיד פ' עקב ד\"ה מפני מה. לקו\"ת שלח מב, ג. ובכ\"מ. וראה גם חדא\"ג מהרש\"א ברכות לה, ב."],["2756","19","פסיקתא דר\"כ פ\"ח. פסיקתא רבתי פי\"ח. קה\"ר פ\"א, ג. יל\"ש אמור שם, י (רמז תרמג). וראה ראב\"ן סי' פ. ראבי\"ה פסחים סתקכ\"ו. רוקח סרצ\"ה (הובא במ\"כ לקה\"ר שם)."],["2757","20","להעיר, שכן הי' בהשנה שבה נאמר המאמר (תשכ\"ה). וכ\"ה בשנה זו (תנש\"א)."],["2758","21","כ\"ה הלשון בלקו\"ת שבהערה 12."],["2759","22","סה\"מ ה'שי\"ת ע' 23. ובכ\"מ."],["2760","23","משלי כז, יט."],["2761","24","ראה ד\"ה לרוקע תקס\"ב (סה\"מ תקס\"ב ח\"א ע' קצד ואילך. ח\"ב ע' תלה ואילך. ועם הגהות וכו' – בסהמ\"צ להצ\"צ קנט, סע\"ב ואילך). ד\"ה כמים הפנים לפנים באוה\"ת בשלח (ע' תעז ואילך). המשך תער\"ב ח\"ב ע' תתקסד ואילך."],["2762","25","וראה לעיל ח\"ב ע' שכה ובהנסמן שם."],["2763","26","ראה אוה\"ת והמשך תער\"ב שם."],["2764","27","אלא שאין זה שינוי (ח\"ו) באדם העליון, כדלקמן הערה 58."],["2765","28","ראה סהמ\"צ להצ\"צ נד, ב."],["2766","29","בכמה ענינים דלקמן – ראה אוה\"ת והמשך תער\"ב שם."],["2767","30","והגם שע\"ס הגנוזות היו לפני ע\"ס הגלויות, הי' זה ע\"י העלאת מ\"ן מיני' ובי' – ראה המשך תער\"ב שם ס\"ע תתקסה ואילך. תתקעב."],["2768","31","ספר אלימה להרמ\"ק – הובא בפלח הרמון על הפרדס ש\"ג פ\"א."],["2769","32","באוה\"ת שם (ריש ע' תפ), שבענין מים הפנים לפנים \"הדבר פשוט יותר\" ש\"אין השינוי בו באמיתית\". אבל לכאורה, עיקר תוכן החידוש דהכתוב הוא שע\"י העלאת מ\"ן דהתחתון <i>נעשה</i> הציור דהתחתון בהעליון (ולא שע\"י הציור אינו משתנה), ומזה מובן, דזה שמשמע מהכתוב שמים הפנים לפנים הוא פשוט יותר הוא גם בנוגע לענין העיקרי שהציור דהתחתון נעשה בהעליון."],["2770","33","כ\"ה הלשון בהמשך תער\"ב שם ע' תתקסד."],["2771","34","להעיר מהמשך תער\"ב ח\"א פקי\"ז (ע' רכז) \"שכל הציורים מציירים על גוון לבן דוקא . . לפי שהוא פשוט מכל הגוונים ע\"כ כל הגוונים והציורים ניכרים עליו דוקא\"."],["2772","35","כהסברא \"כל יצר מחשבות לבו רק רע גו'\" (בראשית ו, ה) שהוא טעם לחוב \"אמחה גו'\" (שם, ז), וסברא זו היא טעם המזכה, כמ\"ש (נח ח, כא) \"כי יצר לב האדם רע מנעוריו ו(לכן) לא אוסיף להכות גו'\". וראה תו\"ח וירא קא, סע\"ב ואילך."],["2773","36","ראה סה\"מ תרפ\"ח ע' קעא. ובכ\"מ."],["2774","37","סהמ\"צ להצ\"צ שם (קס, א). המשך תער\"ב שם ע' תתקעב."],["2775","38","דגם כשהאתערותא דלעילא היא שתהי' ההמשכה <i>למטה</i>, הרי ההתעוררות שתהי' ההמשכה היא <i>למעלה</i> (אתערותא דלעילא), שינוי. ובפרט לפני המבואר לעיל ס\"ד שהאתערותא דלעילא שנתעוררה ע\"י אתערותא דלתתא, היא זה שלמעלה נראית הדמות של האתעדל\"ת."],["2776","39","ראה עד\"ז המשך תער\"ב ח\"ב ריש ע' תתקג."],["2777","40","או\"ת (הוצאת קה\"ת) ב, סע\"ג (בהוצאת קה\"ת תש\"מ ואילך – ס\"ו) – הובא בהמשך הנ\"ל שם ס\"ע תתקב. וראה גם המשך תרס\"ו ע' רלא."],["2778","41","ב\"ר פ\"א, ד."],["2779","42","ב\"ר פ\"ח, ז. רות רבה פ\"ב, ג."],["2780","43","בכ\"מ (המשך תער\"ב ח\"ב ס\"ע תתקעא. המשך ר\"ה תש\"ג פ\"ג ופ\"ו ועוד) דבמי נמלך הו\"ע העלאת מ\"ן מיני' ובי'. היינו, שגם במי נמלך הוא העלאת מ\"ן, אלא שהוא \"מיני' ובי'\". ולפי מ\"ש בפנים, דבמי נמלך הוא במקום שאין צריך להעלאת מ\"ן, ואדרבה, הוא הסיבה לזה שעלה ברצונו שההמשכה תהי' ע\"י העלאת מ\"ן."],["2781","44","כמובן גם מזה שההמלכה דבמי נמלך היא גם על גילויים הכי נעלים (כיון שהם ברצון ולא בהכרח ח\"ו)."],["2782","45","ראה המשך תרס\"ו ע' רלג. והמבואר שם הוא בהמשך להמבואר שם ע' רלא בענין ישראל עלו במחשבה."],["2783","46","וזה (ציור אדם) הוא ענינו, שלכן נקרא בשם <i>אדם</i>. ראה המשך תרס\"ו שם ע' רלב \"שכל הפרצופים יש להם שמות פרטים . . ופרצוף א\"ק אין לו שם פרטי כ\"א נק' בשם אדם\"."],["2784","47","בהבא לקמן, ראה סהמ\"צ להצ\"צ קפב, א ואילך. המשך מים רבים תרל\"ו פס\"ד ואילך. המשך תער\"ב ח\"ב ע' תתקסח."],["2785","48","ראה בארוכה ד\"ה ואברהם זקן תרס\"ו (המשך תרס\"ו ע' פ ואילך). ובכ\"מ."],["2786","49","ומ\"ש בספר יצירה (פ\"א מ\"ז) ע\"ס בלי מה כשלהבת הקשורה בגחלת, דע\"ס הגלויות הם דוגמת שלהבת שעל גבי הגחלת וע\"ס הגנוזות הם דוגמת השלהבת שבגחלת – הוא, כי משל זה בא בעיקר לבאר הקשר דע\"ס הגלויות עם ע\"ס הגנוזות, אבל בנוגע לאופן ההעלם דע\"ס הגנוזות, המשל דאש שבצור החלמיש הוא מכוון יותר, כי ההעלם דע\"ס הגנוזות הוא העלם שאינו במציאות. – כ\"ה בסהמ\"צ ובהמשך מים רבים שם (נעתק בקיצור בסה\"מ תש\"ח ע' 243, בהערה). ולהעיר מסה\"מ תרס\"ח ע' רג, דג' המשלים על ע\"ס הגנוזות – שלהבת הטמונה בגחלת, צור החלמיש, ושמות (ראה לקמן בפנים) – הם ג' מדריגות בע\"ס הגנוזות."],["2787","50","בכ\"מ, דזה שע\"ס הגנוזות הם רק שמות (\"אין מציאות לגנוזות\") הוא לפה\"צ, אבל בהמשך תער\"ב שם ע' תתקסח ואילך <i>מפורש</i> שגם אחה\"צ יש ענין זה. וצ\"ע."],["2788","51","סה\"מ תרנ\"ט ע' קפז. המשך תער\"ב ח\"ב ע' תתקסט. סה\"מ תרס\"ח ע' רב. ועוד."],["2789","52","ראה בארוכה המשך תער\"ב שם ע' תתקסט ואילך. וראה גם תו\"א (הוספות) ויחי קג, ג. אוה\"ת ויחי (השמטות) תכז, ב. ועוד."],["2790","53","ויחי שם."],["2791","54","אוה\"ת ויחי שם. סהמ\"צ להצ\"צ קמט, א ואילך. סה\"מ תרנ\"ט ע' קפו ואילך. המשך תרס\"ו ע' קפד. סה\"מ תרס\"ח ע' רב. המשך תער\"ב שם ע' תתקע."],["2792","55","כ\"ה בסהמ\"צ שם. וראה לקמן ס\"ח."],["2793","56","סה\"מ קונטרסים ח\"א צז, א ואילך. תרפ\"ח ע' ע. ה'תש\"ג ע' 32. ובכ\"מ."],["2794","57","המשך תער\"ב ח\"ב ע' תתקסד ואילך. וראה גם אוה\"ת בשלח ע' תעט ואילך."],["2795","58","והציור דאדם התחתון שבאדם העליון אינו דבר מובדל מאדם העליון אלא הוא אדה\"ע עצמו, ע\"דהפנים הנראים בהמים שהם המים עצמם (כנ\"ל בפנים). ועפ\"ז מובן שאין שינוי (ח\"ו) באדם העליון ע\"י הציור דאדם התחתון שבו – ראה המשך תער\"ב ח\"ב ע' תתקסה. וראה גם אוה\"ת בשלח ע' תפ."],["2796","59","בהבא לקמן, ראה המשך תער\"ב ח\"ב ע' תתקעה-ו."],["2797","60","תנחומא וארא טו. שמו\"ר פי\"ב, ג. ועוד."],["2798","61","אמור כג, יא."]]],[1500380049,"<h3>בס\"ד. יום ב' דחג השבועות ה'תשכ\"ח<sup data-n=\"2799\">*</sup></h3>\n<b>וידבר</b> אלקים את כל הדברים האלה לאמר אנכי גו'<sup data-n=\"2800\">1</sup>, ומדייק אדמו\"ר הזקן<sup data-n=\"2801\">2</sup> מהו אומרו את כל הדברים האלה, דלכאורה הול\"ל וידבר אלקים אנכי גו'. ומבאר, דכל הדברים האלה קאי<sup data-n=\"2802\">3</sup> על כל התורה כולה, כולל כל מה שתלמיד ותיק עתיד לחדש וכו'<sup data-n=\"2803\">4</sup>. וזהו וידבר אלקים את כל הדברים האלה, דבעשרת הדברות (אנכי וגו') נכלל כל התורה כולה (כל הדברים האלה). ויש לקשר זה עם פירוש רש\"י עה\"פ<sup data-n=\"2804\">5</sup>, דמ\"ש את כל הדברים האלה (קודם לאנכי גו') הוא ללמד שכל עשרת הדברות נאמרו (תחילה) בדיבור אחד, ואח\"כ חזר ופירש כל דיבור ודיבור בפ\"ע, דתוכנם של שני הפירושים הוא, שנתינת התורה היתה בדרך כלל ופרט. אלא שלפי פירוש רש\"י מדבר הכתוב בעשרת הדברות עצמם, שמתחילה נאמרו בבחינת כלל (דיבור אחד) ואח\"כ נפרטו כל דיבור ודיבור בפ\"ע, ולפי פירוש אדמו\"ר הזקן מדבר הכתוב בהפרטים דתורה, שגם הם ניתנו תחילה בבחינת כלל, בעשרת הדברות, ואח\"כ נפרטו ונמשכו בגילוי. ויש להוסיף, שגם זה גופא (הפירוט והגילוי דעשרת הדברות) הי' באופן דכלל ופרט. דתחילת ההמשכה והפירוט דעשרת הדברות הוא בתורה שבכתב, ואח\"כ נפרט בפרטיות יותר בתורה שבעל פה, דכל התורה שבעל פה היא פירוש<sup data-n=\"2805\">6</sup> וביאור דתורה שבכתב<sup data-n=\"2806\">7</sup> (מנא הני מילי אמר קרא), והתורה שבעל פה גופא היא ג\"כ באופן דכלל ופרט, משנה ברייתא<sup data-n=\"2807\">8</sup> גמרא וכו' עד כל מה שתלמיד ותיק עתיד לחדש. וצריך להבין<sup data-n=\"2808\">9</sup>, מכיון שכל הפרטים דתורה, עד לכל מה שתלמיד ותיק עתיד לחדש, הכל ניתן למשה בסיני<sup data-n=\"2803\">4</sup>, למה לא ניתנו מלכתחילה באופן גלוי, ומדוע ניתנו תחילה בבחינת כלל.\nב) <b>ויובן</b> זה<sup data-n=\"2809\">10</sup> ממה שמצינו עד\"ז גם בבריאת העולם (אסתכל באורייתא וברא עלמא<sup data-n=\"2810\">11</sup>), שהיתה באופן דכלל ופרט. דאמרו רז\"ל<sup data-n=\"2811\">12</sup> בעשרה מאמרות נבראהעולם כו' במאמר אחד יכול להבראות, וידוע<sup data-n=\"2812\">13</sup> דמאמר אחד הוא המאמר דבראשית (בראשית נמי מאמר הוא<sup data-n=\"2813\">14</sup>), שהוא מאמר כללי שכולל ט' המאמרות שלאחריו. דזהו מ\"ש<sup data-n=\"2814\">15</sup> בראשית ברא אלקים את השמים ואת הארץ וארז\"ל<sup data-n=\"2815\">16</sup> את השמים לרבות צבאיהם ואת הארץ לרבות צבאי', שכל הנבראים נתהוו מהמאמר דבראשית (להיותו מאמר כללי שכולל את כל המאמרות). אלא שהיו בבחינת כלל<sup data-n=\"2816\">17</sup>, ואח\"כ נפרט המאמר דבראשית בהט' מאמרות שלאחריו<sup data-n=\"2817\">18</sup>, ועי\"ז נעשו הנבראים בבחינת התחלקות פרטים.\n<b>והנה</b> כמו שהוא בעשרה מאמרות כפי שנמשכו בפועל ובגילוי (בספירת המלכות<sup data-n=\"2818\">19</sup>), שהמאמר דבראשית הוא מאמר כללי שכולל כל המאמרות, עד\"ז הוא בשרשם, בהעשר ספירות, שהמאמר דבראשית הוא כלל, ויש בזה כמה דרגות<sup data-n=\"2819\">20</sup>. דבתרגום ירושלמי איתא בראשית בחוכמתא<sup data-n=\"2820\">21</sup>, שהחכמה<sup data-n=\"2821\">22</sup> היא כלל שכוללת כל הספירות. ובתרגום אונקלוס איתא בראשית בקדמין, והיינו הרצון דכתר שלמעלה מהחכמה<sup data-n=\"2821\">22</sup>, ועד למחשבה הקדומה דא\"ק שהוא הרצון הכללי על כללות ההשתלשלות, ולמעלה יותר הרצון לברוא עולמות כמו שהוא לפני הצמצום, שהוא בחינת כלל גם לגבי מחשבה הקדומה דא\"ק. ולפני הצמצום גופא יש ג\"כ כלל ופרט, דלאחרי שעלה ברצונו שיער בעצמו בכח כל מה שעתיד להיות בפועל, דהרצון וההשערה הם בחינתכלל ופרט<sup data-n=\"2822\">23</sup>. ונמצא, דכמו שההמשכה דתורה היא בבחינת כלל ופרט בכו\"כ דרגות, כנ\"ל, עד\"ז הוא בההמשכה דעולמות שהיא בבחינת כלל ופרט בכו\"כ דרגות. וגם בזה צריך להבין, הרי הכוונה בבריאת העולמות היא שיהיו נבראים פרטיים בהתחלקות, וכוונה זו היא הסיבה להתעוררות הרצון לפני הצמצום בכדי שימשך ממנו אח\"כ (ע\"י ריבוי השתלשלות) עשרה מאמרות פרטיים שמהם יתהוו נבראים פרטיים, וא\"כ הי' צריך להיות לכאורה התעוררות הרצון מלכתחילה בבחינת פרט באופן שיהי' אפשר להיות ממנו התהוות נבראים פרטיים כפי הכוונה, ולמה הי' התעוררות הרצון בתחילה בבחינת כלל.\nג) <b>ויובן</b> זה ע\"פ משל דהשפעת שכל מרב לתלמיד, דאמרו חז\"ל<sup data-n=\"2823\">24</sup> לעולם ישנה אדם לתלמידו בדרך קצרה, וידוע<sup data-n=\"2824\">25</sup> הדיוק בהלשון דרך קצרה (ולא שכל קצר), שצריך להשפיע להתלמיד כל העומק והפרטים שבהשכל, אלא שכל זה צריך ללמדו בדרך קצרה, בדיבורים קצרים, שמהם יוכל התלמיד להבין כל הפרטים. וכמו המשנה ששנה לנו רבינו הקדוש, שבלשון המשנה ישנם (בהעלם) כל הפרטים, האורך הרוחב והעומק, שנתבאר אח\"כ בגמרא, אלא שבמשנה הם בקיצור נמרץ<sup data-n=\"2825\">26</sup>. והטעם על זה (שההשפעה צריכה להיות בדרך קצרה דוקא) הוא, כי באם ישפיע לו (בתחילה) כל הפרטים בגילוי, יתבלבלו חושי התלמיד, וגם אפשר שמצד ריבוי ההתפשטות ילך בדרך עקלתון, ולכן צריך ללמדו בדרך קצרה דוקא, שעי\"ז בא השכל בציור מוגבל (שהוא יודע את הענין בכללותו), ועי\"ז, הנה גם לאחרי שמעיין בהפרטים, בריבוי סברות, תהי' ההתפשטות לפי אופן הציור של הדיבורים הקצרים ולא ילך בדרך עקלתון. וכמו שהוא בההשפעה להתלמיד בפועל, דתחילת ההשפעה צריכה להיות בדרך קצרה דוקא, עד\"ז הוא גם בהמצאת השכל השייך להתלמיד בהרב עצמו, דתחילת המשכת (והמצאת) השכל היא בבחינת נקודה. דהנה ידוע<sup data-n=\"2826\">27</sup> שבשכל הרב כלול גם חיצוניות השכל ששייך להתלמיד, אלא, שבהיותו כלול בשכל הרב, הנה נוסף לזה שאינו ניכר שם בפ\"ע (להיותו כלול ומעורב עם הפנימיות), הנה גם חיצוניות השכל (השייך להתלמיד) הוא בריבוי אור, ולכן צריך הרב לצמצם את שכלו, היינו להעלים את שכלו העצמי שלא יאיר כלל, שעי\"ז נבדל החיצוניות מהפנימיות וניכר בפ\"ע, וגם החיצוניות שנמצא אצלו אז הוא בבחינת נקודה בלבד, ורק לאחרי זה (לפני שמשפיע בפועל) הוא משער בעצמו את הפרטים שישפיע אל המקבל. והטעם על זה שבתחילה בא השכל בבחינת נקודה הוא, כי באם השכל ששייך להתלמיד הי'נמצא מלכתחילה באופן דהתפשטות בריבוי פרטים, יהיו אז הפרטים באופן כמו שהם נובעים משכל הרב, בריבוי אור, ולא יהיו מכוונים ומתאימים לחושי התלמיד. ולכן, המצאת השכל בתחילה הוא בבחינת נקודה (ענין של התעלמות), שעי\"ז נגבל השכל. דעם היות שבהנקודה כלולים כל הפרטים שישפיע אח\"כ להתלמיד [ויתירה מזו, שיש בהנקודה בהעלם גם מפנימיות השכל<sup data-n=\"2827\">28</sup>], מ\"מ, מכיון שכל זה הוא בהעלם, הנה עי\"ז נעשה הגבלה וציור (כללית) בהשכל שיהי' באופן ששייך להשפיע אותו להתלמיד, ולאחרי שנעשה בו הגבלה זו, הנה גם לאחרי שנמשך ברוחב והתפשטות (כשמפרט את הפרטים), יהי' הרוחב כפי אופן ההגבלה והציור של הנקודה.\nד) <b>והנמשל</b> מזה יובן למעלה, דבכדי שהאור שמהווה את העולמות יהי' לפי ערך הנבראים, באופן שיוכל להאיר בהם בפנימיות, הוצרך להיות תחילה ההמשכה באופן דכלל ופרט. כי מכיון שהעולמות הם באין ערוך לגבי אוא\"ס, לכן, באם ההמשכה מאוא\"ס היתה מלכתחילה בריבוי פרטים, היו אז הפרטים בבלי גבול (כמו שהם מצד אוא\"ס), ולכן הוצרך להיות תחילה ההמשכה באופן דכלל, שעי\"ז נעשה ציור כללי בהאור שיהי' לפי ערך העולמות, ועי\"ז, גם הפרטים שנמשכו אח\"כ הם לפי ציור זה.\n<b>וכמו</b> שבהשפעת השכל מרב לתלמיד, קדימת הכלל להפרטים היא הן בההשפעה בפועל, שההשפעה היא בדרך קצרה, דיבורים קצרים שכוללים כל הפרטים שהתלמיד יבין אח\"כ, והן בהמשכת השכל (השייך להתלמיד) בהרב עצמו, שתחילת המשכתו היא בבחינת נקודה, שכוללת כל הפרטים שנמשכים אח\"כ (אצל הרב, לפני ההשפעה בפועל), עד\"ז הוא גם למעלה, שקדימת הכלל להפרטים היא הן בהמשכת האור שלצורך התהוות העולמות, שבתחילה היתה ההמשכה בבחינת כלל ואח\"כ דוקא נמשכו הפרטים [וענין זה דקדימת הכלל להפרטים הי' בכל דרגא ודרגא, כנ\"ל (סעיף ב) בארוכה], והן בההתהוות בפועל, שבתחילה נברא העולם במאמר אחד, המאמר דבראשית, ורק לאח\"ז היתה ההתהוות בכל מאמרות פרטיים.\nה) <b>אך</b> צריך להבין, דלכאורה, המשל דרב ותלמיד אינו דומה להנמשל. דבהמשל, הרי זה שישנו שכל הרב שלמעלה מגדר השפעה להתלמיד, הוא ענין שמצד הרב עצמו ולא בשביל ההשפעה להתלמיד. משא\"כ בהנמשל, הרי כל הגילויים, גם הגילויים הכי נעלים, כולל גם האור שבבחינת גילוי העצם שלמעלה גם מהכלל הראשון השייך לעולמות (עליית הרצון), הוא בכדי<sup data-n=\"2828\">29</sup> שאח\"כ יומשכו ממנו (ע\"י ריבוי צמצומים) העשרה מאמרות שבהם נברא העולם. ועפ\"ז צריך להבין, מדוע לא נמשכו מלכתחילה עשרה מאמרות. דביאור הנ\"ל על הצורך דקדימת הכלל להפרטים הוא לאחרי שהוקבע שבתחילה יהי' האור שלמעלה משייכות לעולמות וממנו דוקא תהי' המשכת האור שלפי ערך העולמות [דכיון שהאור שלפי ערך העולמות נמשך מהאורשלמעלה משייכות לעולמות, לכן הי' צריך להיות תחילה ההמשכה בבחינת כלל, שעי\"ז נעשה הגבלה בהאור, כנ\"ל], אבל אינו מובן, דכיון שהכוונה בהמצאת האור שלמעלה משייכות לעולמות היא בכדי שאח\"כ יומשך ממנו האור שלפי ערך העולמות עד לעשרה המאמרות שבהם נברא העולם, הרי לכאורה הי' צריך להיות מלכתחילה המשכת (המצאת) העשרה מאמרות<sup data-n=\"2829\">30</sup>.\nו) <b>אך</b> הענין הוא, דבכדי שתושלם כוונת הבריאה, שהנבראים ע\"י עבודתם יהיו בטלים לאלקות, היתה הבריאה<sup data-n=\"2830\">31</sup> באופן כזה שגם קודם העבודה תהי' בהנבראים כעין הכנה והכשרה להביטול שיפעלו ע\"י עבודתם. ולכן היתה הבריאה באופן שבתחילה נמצא האור שלמעלה משייכות לעולמות, וממנו דוקא נמשך האור שלפי ערך העולמות, שעי\"ז נעשה ההכשרה בהעולם להיות דירה לו ית'.\n<b>ויובן</b> זה בהקדים מה שארז\"ל&lt;12&gt; דהטעם על זה שבריאת העולם היתה בעשרה מאמרות (אף שבמאמר אחד יכול להבראות) הוא להפרע מן הרשעים כו' וליתן שכר טוב לצדיקים כו'. וידוע הביאור בזה<sup data-n=\"2831\">32</sup>, דבאם היתה ההתהוות ממאמר אחד, הי' העולם בטל בתכלית [שהרי אפילו עולם הבריאה, שנתהווה מהמאמר דבראשית שבספירת המלכות, אינו יש ממש, ומכ\"ש באם היתה ההתהוות מהמאמר אחד דחכמה או דכתר, ועאכו\"כ מהרצון שלפני הצמצום, שאז היו העולמות בתכלית הביטול], ובמילא לא הי' שייך ענין הבחירה. ולכן היתה הבריאה בעשרה מאמרות פרטיים, שעי\"ז נעשו הנבראים בבחינת יש, ושייך בהם ענין הבחירה (וענין שכר ועונש, להפרע מן הרשעים וליתן שכר טוב לצדיקים). אבל, מכיון שההתהוות שמצד העשרה מאמרות היא בבחינת יש ועד שאפשר לבחור בהיפך, הנה בכדי שתושלם כוונת הבריאה, שיהי' גילוי אלקות בעולם ושהנבראים יהיו בטלים לאלקות, לכן היתה הבריאה באופן שבתחילה נמשך המאמר אחד וממנו נפרטו עשרה מאמרות פרטיים, דעי\"ז יש בהעלם בהעשרה מאמרות הכלל דמאמר אחד, וע\"י עבודת האדם, הוא מגלה את הכלל דמאמר אחד<sup data-n=\"2832\">33</sup> (שבכל הדרגות, עד להרצון שלפני הצמצום) בהעשרה מאמרות ובהעולם<sup data-n=\"2833\">34</sup> שנתהווה מהם, שיהי' גילוי אלקות בהעולם ושיהי' בטל לאלקות<sup data-n=\"2834\">35</sup>.\nז) <b>ועפ\"ז</b> יובן גם זה שבתחילה האיר האור שבבחינת גילוי העצם שלמעלה משייכות לעולמות, וממנו דוקא נמשך האור שלפי ערך העולמות. דהנהידוע<sup data-n=\"2835\">36</sup> שהביטול בעולם שמצד גילוי האור שלפי ערך העולמות, הוא רק ביטול היש, מכיון שלגבי אור זה יש להם ערך, ואמיתית ענין הביטול, ביטול במציאות, הוא דוקא מצד האור שלמעלה משייכות לעולמות. ולהיות שכוונת הבריאה היא שהנבראים יהיו בטלים לאלקות בתכלית הביטול, ביטול במציאות, שעי\"ז דוקא נעשים דירה לו ית', לכן הי' תחילה האור שלמעלה משייכות לעולמות, וממנו דוקא נמשך האור שלפי ערך העולמות, דעי\"ז יש בו בהעלם גם מהאור שלמעלה משייכות לעולמות, וכמו שידוע&lt;28&gt; שבנקודת הרשימה יש בהעלם (לא רק כל הפרטים שיומשכו אח\"כ בהקו, אלא גם) מפנימיות האור שלמעלה משייכות לעולמות, וכבהמשל דרב ותלמיד, שבנקודת השכל של הרב (שנשאר אצלו בעת הצמצום) יש בהעלם כל הפרטים שישפיע אח\"כ להתלמיד (שנמשכים מחיצוניות השכל של הרב), וגם מפנימיות השכל של הרב. ומכיון שהפרטים שנמשכים אח\"כ עד להעשרה מאמרות שמהם נברא העולם בפועל הם (לא ענין בפ\"ע, אלא) הפרטים של הכלל דמאמר אחד (עד לשרשו הראשון) שיש בו בהעלם מהאור שלמעלה משייכות לעולמות, לכן, ע\"י העבודה, מגלים בהעשרה מאמרות (ובהעולם שנברא מהם) לא רק הכלל דמאמר אחד אלא גם האור שלמעלה משייכות לעולמות [ובדוגמת המשל דרב ותלמיד, שע\"י שהתלמיד מעיין בהפרטים, הנה סוף סוף נעשה קאי אדעתי' דרבי'<sup data-n=\"2836\">37</sup>, שמגיע לשכל העצמי דהרב], דע\"י גילוי אור זה, נמשך בעולם שיהי' בטל לאלקות בתכלית הביטול, ביטול במציאות.\nח) <b>ובעומק</b> יותר יש לומר, דע\"י העבודה בהפרטים, מגיעים לבחינת עצם האור, שלמעלה גם מהאור שלמעלה מעולמות שישנו בהעלם בהכלל דעולמות. דמה שיש בהעלם בהכלל דעולמות הוא בחינת התפשטות האור, שבתחילה הי' אוא\"ס ממלא את מקום החלל<sup data-n=\"2837\">38</sup>, שהוא האור שבבחינת התפשטות וגילוי, ואח\"כ (באור זה<sup data-n=\"2838\">39</sup>) עלה ברצונו להאציל ולברוא, הרי שהשייכות דהרצון לעולמות (הכלל דעולמות בשרשו הראשון) לאור הבל\"ג שלמעלה מעולמות, היא רק להאור שבבחינת התפשטות וגילוי, וע\"י העבודה בהפרטים מגיעים לעצם האור.\n<b>והענין</b> הוא, דשרש הפרט הוא למעלה מהכלל<sup data-n=\"2839\">40</sup>. וכמו חכמה ובינה, דהגם שחכמה היא הכלל שממנה נמשכים כל הפרטים דבינה, מ\"מ מצד זה גופא, שרש הבינה הוא למעלה משרש החכמה. שלכן, על ידי העיון בהפרטים דבינה ניתוספים (לפעמים) ענינים חדשים שלא היו בנקודת החכמה. ועד\"ז הוא בדיבור, דכשנמשך השכל בדיבור נעשים בו ריבוי פרטים יותר גם מהפרטים דבינה (אפילו לאחרי שהבינה מתלבשת במחשבה, דמה שחושבים במחשבה אחת הנה בדיבור הוא משך זמן), דשרשהדיבור הוא למעלה יותר גם מהשרש דבינה, שלכן כשלומד את השכל בדיבור, מתחדשים אצלו ענינים שלא היו תחילה במחשבה, גם בההשגה דבינה. ועד\"ז הוא בהשפעת שכל מרב לתלמיד, דעל ידי שהשכל מתפרט לריבוי פרטים [ובפרט על ידי ההשפעה לתלמיד קטן, דכל מה שההשפעה היא לתלמיד קטן יותר, צריך לפרט את השכל בריבוי פרטים יותר<sup data-n=\"2840\">41</sup>], הנה עי\"ז מיתוסף אצל הרב עומק חדש שלא הי' אצלו לפני ההשפעה, כמאמר<sup data-n=\"2841\">42</sup> ומתלמידי יותר מכולן. ובפרט כשהתלמיד מקשה קושיות על השכל, שבכדי לתרץ ולהסיר את הקושיא, מתעורר אצלו עומק חדש.\n<b>והנמשל</b> מזה יובן למעלה בענין העשרה מאמרות, דהגם שהעשרה מאמרות הם הפרטים דהמאמר אחד, מ\"מ, מצד זה גופא, מכיון ששרש הפרט הוא למעלה מהכלל, לכן על ידי העבודה בהעולם שנברא בעשרה מאמרות [ובפרט שמצד זה שהעולם נברא בעשרה מאמרות יש אפשרות לבחור גם בהיפך (כנ\"ל סעיף ו), בדוגמת הקושיות שסותרים את השכל], מגיעים למעלה יותר מבחינת הכלל דעולם דמאמר אחד, ויתירה מזו, שמגיעים גם לעצם האור, שלמעלה גם מהאור (התפשטות האור) שבו הי' העלאת הרצון לעולמות.\nט) <b>והנה</b> עד\"ז הוא גם בההמשכה דתורה, דע\"י שנמשכה תחילה בבחינת כלל ואח\"כ נפרטה לפרטים, הנה גם הפרטים הם (לא ענין בפני עצמו, כי אם) פרטים שנובעים מהכלל, ועי\"ז ישנו הכח שגם בהפרטים דתורה שבעל פה, ועד לכל מה שתלמיד ותיק עתיד לחדש, יהי' בגילוי האור דהכלל דתורה שבכתב, ועד להכלל דעשרת הדברות (שלימוד כל פרט שבתורה יהי' באימה וביראה וברתת ובזיע כמו שהי' בעת אמירת עשרת הדברות<sup data-n=\"2842\">43</sup>), ועד להכלל דדיבור אחד שבו נכללו כל עשרת הדברות.\n<b>ויתירה</b> מזו, דע\"י העיון והיגיעה בהפרטים דתורה שבעל פה, מגיעים למעלה גם מבחינת הכלל. דזהו מה שאמרו כל מה שתלמיד ותיק עתיד לחדש (לחדש<sup data-n=\"2843\">44</sup> דוקא)<sup data-n=\"2844\">45</sup>, כי ע\"י היגיעה בתורה ממשיכים מבחינת התורה כמו שהיא מושרשת בהעלם העצמי דא\"ס, שלמעלה מבחינת התורה כמו שבאה בבחינת המשכה וגילוי<sup data-n=\"2845\">46</sup>. וזהו יגעתי ומצאתי<sup data-n=\"2846\">47</sup>, דענין מציאה (מצאתי) הוא שמוצא דבר חדש שבתחילה לא הי'אפשר לשער, כמו מציאה שבאה<sup data-n=\"2847\">48</sup> בהיסח הדעת. וזהו יגעתי ומצאתי, שע\"י היגיעה בתורה מוצאים ומגלים ענינים חדשים, ועד שע\"י היגיעה בתורה [ובפרט בפנימיות התורה שהיא מעין תורתו של משיח] עכשיו, נזכה לגילוי תורתו של משיח, שבא<sup data-n=\"2847\">48</sup> בהיסח הדעת, מצאתי דוד עבדי<sup data-n=\"2848\">49</sup> (מצאתי דוקא), שאז יהי' גילוי עצמות אוא\"ס בלי לבוש<sup data-n=\"2849\">50</sup> (ועד שגם הגילוי בשעת מ\"ת הי' רק מעין הגילוי דלעתיד<sup data-n=\"2849\">50</sup>), בביאת משיח צדקנו, בקרוב ממש.\n**********",[["2799","*","יצא לאור ב<b>קונטרס חג השבועות – תשמ\"ט</b>, \"לקראת חג השבועות הבעל\"ט . . <i>ימי הגבלה ה'תשמ\"ט</i>\"."],["2800","1","יתרו כ, א ואילך."],["2801","2","בלקו\"ת במדבר ד\"ה זה בתחילתו (טו, ג). רד\"ה זה תקס\"ח (סה\"מ תקס\"ח ח\"א ע' רכד)."],["2802","3","ראה חגיגה ג, ב (וכ\"ה בבמדב\"ר פי\"ד, ד). שמו\"ר רפמ\"ז. ועוד – הובאו בלקו\"ת שם."],["2803","4","ראה מגילה יט, ב. ירושלמי פאה פ\"ב ה\"ד. שמו\"ר שם. ויק\"ר רפכ\"ב. קה\"ר פ\"א, ט (ב). פ\"ה, ח (ב). ועוד."],["2804","5","ממכילתא עה\"פ. ועיין ג\"כ במדב\"ר פי\"א, ז (הובא בלקו\"ת שם)."],["2805","6","ראה רמב\"ם בהקדמתו לספרו."],["2806","7","ראה לקו\"ת ברכה צד, א ואילך. וראה אגה\"ק סכ\"ט (קנ, ב ואילך). ובכ\"מ."],["2807","8","ראה תענית כא, א: מי* איכא מידי בברייתא דלא פשיטנא לי' ממתניתין. וראה לקו\"ת שה\"ש מא, ב."],["2808","9","וכמו שמדייק עד\"ז בד\"ה וידבר גו' ושבתה תרע\"ג (סה\"מ תער\"ב-תרע\"ו ע' רנ ואילך)."],["2809","10","בהבא לקמן (סעיף ב-ד) – ראה (בסגנון אחר קצת) בד\"ה ושבתה תרכ\"ז (סה\"מ תרכ\"ז ע' רנז ואילך); תרע\"ג הנ\"ל שם."],["2810","11","זח\"ב קסא, א-ב."],["2811","12","אבות פ\"ה מ\"א.\n*) <i>כן הובא בלקו\"ת שה\"ש שם</i>. <b>ובכ\"מ</b>."],["2812","13","פרדס שער ב (שער טעם האצילות) פ\"ו. לקו\"ת בהר מא, ד. ד\"ה דבר גו' כי תבואו גו' ושבתה תקס\"ב (סה\"מ תקס\"ב ח\"א ע' קפח. שם ע' תלב. סהמ\"צ להצ\"צ קסז, א). מאמרי אדהאמ\"צ דברים ח\"א ע' רפד-ה. ח\"ב ע' תעז (וש\"נ). אוה\"ת עקב ע' תפ. שם ע' תצג. ובכ\"מ. ובארוכה – סה\"מ תרנ\"ט ע' קמג ואילך. ה'תש\"ד ע' 67 ואילך."],["2813","14","ר\"ה לב, א. מגילה כא, ב."],["2814","15","בראשית א, א."],["2815","16","ראה פרש\"י עה\"פ בראשית שם, יד."],["2816","17","ראה חדא\"ג מהרש\"א לר\"ה שם, שמהמאמר דבראשית נברא \"חומר הראשון אשר ממנו נתהוו כל הצורות\". וראה גם לקו\"ת בהר שם, \"שכמו\"כ בגשמיות בהתהוות עוה\"ז . . נתהווה ע\"י מאמר דבראשית כו' אלא שנפרטו אח\"כ ע\"י ט' מאמרות\", ומציין לרמב\"ן עה\"ת ר\"פ בראשית, דמזה מוכח שכוונתו היא ל\"חומר הראשון\"."],["2817","18","ראה שעהיוה\"א פ\"א, שהחיות הנמשך מהעשרה מאמרות עצמם \"גדול מאד מבחי' הנבראים פרטיים\", והמשכת החיות לפרטי הנבראים מהעשרה מאמרות הוא ע\"י צירופים וחילופים כו' – דעפ\"ז נמצא, שגם העשרה מאמרות (עם היותם בחי' פרט לגבי הכלל דמאמר אחד) הם בחינת כלל שנפרטו אח\"כ ע\"י הצירופים וכו' – בדוגמת מה שגם <i>עשרת</i> הדברות הם בחינת כלל ונפרטו אח\"כ בתושב\"כ ובתושבע\"פ."],["2818","19","היינו, שגם המאמר דבראשית הוא במלכות, כדמוכח ממ\"ש בהערה 17 שמהמאמר דבראשית נתהווה \"חומר הראשון\". וראה סה\"מ עזר\"ת ס\"ע יד, שהוא \"הפנימיות דחיצוניות המל' המקור לבי\"ע\". ומה שמבואר בכ\"מ שהמאמר דבראשית הוא חכמה או כתר (כדלהלן בפנים), הוא – לפי ששם מדובר בענין העשרה מאמרות כמו שהם בשרשם, בהספירות."],["2819","20","ולהעיר שעד\"ז הוא בהכלל דעשרת הדברות – שיש בו כו\"כ דרגות, דב' דברות הראשונות \"הם כללות כל התורה כולה\" (תניא רפ\"כ. וראה תו\"ש יתרו כרך טז מילואים אות א. וש\"נ), למעלה מזה הוא הדיבור \"אנכי\" שכולל גם הדיבור לא יהי' לך (ראה \"הדרן\" על הרמב\"ם (קה\"ת, תשמ\"ה) סעיף ו [תורת מנחם – הדרנים על הרמב\"ם וש\"ס ע' מט]), למעלה מזה – תיבת אנכי, תיבה הראשונה שכוללת כל הפרטים שבדיבור אנכי (ראה פורת יוסף (כג, ד) בשם הבעש\"ט), ובתיבת אנכי גופא – האל\"ף שהוא \"ראש\" התיבה שכולל כל האותיות שבה (ראה פנים יפות (לבעל ההפלאה) עה\"פ יתרו כאן)."],["2820","21","כ\"ה <i>בכ\"מ</i> בדא\"ח. ובתרגום שם: בחוכמא."],["2821","22","ראה גם לקו\"ת במדבר יג, א."],["2822","23","ראה שער היחוד (לאדמו\"ר האמצעי) פ\"י וי\"א. ד\"ה צאינה וראינה תרנ\"ד (סה\"מ תרנ\"ד ע' שב ואילך)."],["2823","24","פסחים ג, ב."],["2824","25","ראה לקו\"ת בשלח א, א. ביאוה\"ז לאדהאמ\"צ פ' אחרי (עו, ד) ולהצ\"צ שם (ח\"א ע' שסג-ד). ד\"ה וידעת תרנ\"ז (סה\"מ תרנ\"ז ע' מט). וראה גם לקו\"ת שבהערה 8."],["2825","26","ראה הקדמת הרמב\"ם לפירוש המשניות ד\"ה אחר כן ראה, שלשון המשנה הוא \"דבר קצר וכולל ענינים רבים\"."],["2826","27","ראה המשך תרס\"ו ע' סה. סה\"מ תרס\"ח ע' קסד. תרפ\"ד ע' שז-ח. תרפ\"ז ע' מב. ה'תש\"ט ע' 4-133. ועוד."],["2827","28","ראה ד\"ה פנים בפנים תרנ\"ט (סה\"מ תרנ\"ט ס\"ע קצא ואילך)."],["2828","29","דמכיון שלמעלה הגילוי אינו בדרך הכרח ח\"ו – הרי מובן, שגם גילוי האור שבבחינת גילוי העצם הוא בשביל הכוונה דדירה בתחתונים (סה\"מ עטר\"ת ע' לא. תרצ\"ט ע' 48. ובכ\"מ)."],["2829","30","ראה עד\"ז סה\"מ תרע\"ח ע' רפג וסה\"מ תרפ\"א ע' חצר שמדייק שם \"למה הי' הגילוי תחילה בבחי' א\"ס שיהי' הצמצום ואח\"כ המשכת הקו, הרי בכח הא\"ס הי' יכול להיות בתחילה המשכת הקו בבחי' מדה וגבול\" (ולהעיר מהמשך תרס\"ו ע' תסה. ובכ\"מ)."],["2830","31","כי הכוונה ב\"דירה בתחתונים\" היא שהתחתונים יהיו דירה לו ית' <i>מצד ענינם הם</i> (לקו\"ש חי\"ב ע' 73. ובכ\"מ). ולכן היתה <i>הבריאה</i> באופן כזה, בכדי שהביטול בעולם (שיהי' אח\"כ ע\"י עבודה) יהי' (גם) מצד ענין וגדר העולם."],["2831","32","ד\"ה ושבתה תרכ\"ז שבהערה 10. סה\"מ תרנ\"ב ע' נא. תרנ\"ט ע' קמד. ה'תש\"ד ע' 70."],["2832","33","להעיר גם מלקו\"ת נשא כו, ב (בענין ויקרא האדם שמות), ד\"ע\"י האדם באים למאמר הכולל\"."],["2833","34","ועפ\"ז יומתק זה שבריאת העולם (בתחילה) היתה במאמר אחד, בכדי שהשייכות דעולם להמאמר אחד תהי' (לא רק ע\"י העשרה מאמרות שהם הפרטים דהמאמר אחד, אלא) גם מצד העולם."],["2834","35","ראה גם סה\"מ תרנ\"ב ע' נב, \"שיומשך בחי' מאמר אחד בעש\"מ ועי\"ז נעשה בחי' ביטול היש לאין\"."],["2835","36","ראה קונטרס עה\"ח פ\"ו. המשך תרס\"ו ע' תלו. ובכ\"מ."],["2836","37","ראה ע\"ז ה, ב."],["2837","38","עץ חיים שער א (דרוש עגולים ויושר) ענף ב."],["2838","39","המשך תרס\"ו ריש ע' קפה. ובכ\"מ."],["2839","40","ראה בארוכה המשך מצה זו תר\"מ פרק יז ואילך ובסה\"מ תרנ\"ט ע' ג' ואילך (בענין בינה יתירה ניתנה באשה יותר מבאיש). וראה שם הדוגמאות דלקמן. וראה גם ד\"ה ושבתה שבהערה 9 (ע' רנד ואילך)."],["2840","41","ראה גם סהמ\"צ להצ\"צ נט, ריש ע\"ב."],["2841","42","תענית ז, א."],["2842","43","ברכות כב, א. וראה תו\"א יתרו סז, ב."],["2843","44","ראה לקו\"ש חי\"ט ע' 252 הערה 21."],["2844","45","ראה המשך תרס\"ו (ע' שפג. שם ע' שצג. ועוד), ש\"הגם דלכאורה כל הענינים דתושבע\"פ (שחידשו חז\"ל) הכל מתושב\"כ\", הנה באמת \"כל עניני תושבע\"פ הן בבחי' חידוש בכח עצמם ויגיעתם דוקא\", וע\"י היגיעה שלהם המשיכו \"לא מבחי' תוה\"ק לבד כ\"א מבחי' העלם העצמי דא\"ס\"."],["2845","46","ומה שאמרו דכל מה שתלמיד ותיק עתיד לחדש הכל ניתן למשה בסיני – הוא, לפי שבמ\"ת \"ניתנה\" התורה כמו שהיא מושרשת ב\"העלם העצמי דא\"ס\" (שלמעלה מבחינת התורה כמו שבאה בבחינת המשכה וגילוי)."],["2846","47","מגילה ו, ב."],["2847","48","סנהדרין צז, א."],["2848","49","תהלים פט, כא. וראה לקו\"ש ח\"ד ע' 1165."],["2849","50","תניא פל\"ו (מו, א)."]]],[1500380050,"<h3>בס\"ד. יום ב' דחג השבועות ה'תשכ\"ט<sup data-n=\"2850\">*</sup></h3>\n<b>וידבר</b> אלקים את כל הדברים האלה לאמר<sup data-n=\"2851\">1</sup>, וידוע הדיוק<sup data-n=\"2852\">2</sup> במ\"ש לאמר, דמאחר שכל ישראל (הנשמות שבכל הדורות<sup data-n=\"2853\">3</sup>) היו במעמד הר סיני ושמעו את הדברות מהקב\"ה בעצמו, מהו פירוש לאמר, לאמר לאחרים<sup data-n=\"2854\">4</sup>. ונקודת הביאור בזה, שבזה מבאר הכתוב את החידוש דמתן תורה. דלכאורה הרי גם קודם מתן תורה למדו כל התורה [כמובן גם מזה שקיים אברהם אבינו את כל התורה כולה עד שלא ניתנה<sup data-n=\"2855\">5</sup>, שבכדי לקיים את התורה צריך ללמוד אותה, ובודאי<sup data-n=\"2856\">6</sup> שאברהם לימד את כל התורה כולה ליצחק בנו ויצחק לימדה ליעקב ובניו<sup data-n=\"2857\">7</sup>], ומהו החידוש דמתן תורה<sup data-n=\"2858\">8</sup>. ומבאר הכתוב, שהחידוש דוידבר אלקים את כל הדברים האלה במתן תורה הוא, שעי\"ז ניתן הכח לכאו\"א מישראל שבכל הדורות, שלימוד התורה שלו יהי' באופן דלאמר. ושני פירושים בזה. שע\"י לימוד התורה שלו הוא גורם שהקב\"ה יאמר דיבורים אלה<sup data-n=\"2859\">9</sup>, דכל הקורא ושונה הקב\"ה קורא ושונה כנגדו<sup data-n=\"2860\">10</sup>, דעפ\"ז פירוש לאמר (לאמר לאחרים) הוא, שהאדם הלומד תורה אומר להקב\"ה<sup data-n=\"2861\">11</sup> כביכול שיחזור על הדיבורים שלו. ועוד, שלימוד התורה של האדם יהי' באופן דלאמר, לחזור הדברים שהקב\"ה אומר, כמ\"ש<sup data-n=\"2862\">12</sup> תען לשוני אמרתך, שהדיבורים דתורה שהאדם אומר הם אמרתך ולשוני תען כעונה אחר הקורא<sup data-n=\"2863\">13</sup>. ועוד פירוש בוידבר גו' לאמר, שוידבר אלקים את כל הדבריםהאלה, עשרת הדברות שהם כללות כל התורה<sup data-n=\"2864\">14</sup>, הוא לאמר, שעשרת הדברות (תורה שלמעלה מעולם) יומשכו בהעשרה מאמרות שבהם נברא<sup data-n=\"2865\">15</sup> העולם<sup data-n=\"2866\">16</sup>. ועד\"ז הוא בלימוד התורה דהאדם, שהוא באופן דוידבר גו' לאמר, שמדיבור התורה שלו נעשה אמירה, המשכת ההשפעה למטה<sup data-n=\"2867\">17</sup>. וצריך להבין הקשר והשייכות דכל ענינים הנ\"ל בלאמר.\nב) <b>והנה</b> בהמאמר של אדמו\"ר מהר\"ש ד\"ה זה שנאמר לפני מאה שנה<sup data-n=\"2868\">18</sup> (לאחרי הדיוק שלכאורה תיבת לאמר הוא מיותר), מביא מ\"ש בילקוט<sup data-n=\"2869\">19</sup>, כשהי' הקב\"ה מדבר הי' כל אחד מישראל אומר עמי הדיבור מדבר שנאמר<sup data-n=\"2870\">20</sup> אנכי הוי' אלקיך לשון יחיד. ומבאר, דזהו מה דאיתא במדרש<sup data-n=\"2871\">21</sup> עה\"פ אנכי הוי' אלקיך, שהקול ששמעו בעשרת הדברות <i>הי'</i> לפי כחו של כל אחד, הבחורים לפי כחן והזקנים לפי כחן והקטנים לפי כחן. ויש לומר, דמהטעמים על זה שמביא גם מאמר המדרש, הוא, לפי שעי\"ז מובן שהענין דעמי הדיבור מדבר (לכאו\"א בפ\"ע) הוא לא רק בנוגע להנשמה אלא גם בנוגע להגוף, שהרי החילוק דבחורים זקנים וקטנים הוא מצד הגוף.\n<b>ומבאר</b> בהמאמר הטעם על זה שהדיבור דעשרת הדברות הי' באופן דעמי הדיבור מדבר, בלשון יחיד לכאו\"א בפ\"ע [הגם שכל ציוויי התורה הם לכאו\"א מישראל ובכל התורה נאמר אני ה' אלקיכם], ע\"פ מה דאיתא בילקוט שם, דבשעת מ\"ת שיתף הקב\"ה את שמו בכאו\"א מישראל. דזהו מ\"ש<sup data-n=\"2872\">22</sup> רכב אלקים רבותיים גו' אד' בם סיני בקודש, דכמו שאד' בם (בהמלאכים), שבשמו של כל מלאך משותף (בסופו) שמו של הקב\"ה, א-ל (מיכאל גבריאל רפאל), כן במתן תורה, סיני בקודש, שיתף הקב\"ה את שמו בכאו\"א מישראל, אנכי הוי' אלקיך. וממשיך בהמאמר, דע\"י ששמו של הקב\"ה משותף במלאכים, הם בטלים לגבי שמו ית' שמשותף בהם. וכמו\"כ הוא בישראל, דע\"י ששיתף הקב\"ה את שמו בישראל, הם בביטול, כמבואר בארוכה בהמאמר.\nג) <b>והנה</b><sup data-n=\"2873\">23</sup> שמו של הקב\"ה ששיתף בישראל הוא למעלה יותר משמו שמשותף במלאכים. דבמלאכים כתיב אד' בם, וכמבואר בתניא<sup data-n=\"2874\">24</sup> שהמלאכים נק' בשם אלקים, דאלקים ואד' הם (בכללות) ענין אחד<sup data-n=\"2875\">25</sup>, אבל בישראל כתיב<sup data-n=\"2876\">26</sup> כי חלקהוי' עמו, חלק משם הוי'<sup data-n=\"2877\">27</sup>. והגם שהענין דחלק הוי' עמו הי' גם קודם מ\"ת, לא האיר זה בגילוי (כ\"כ), כי הענין דחלק הוי' עמו הוא מצד הנשמה, ובירידת הנשמה למטה, הגוף מעלים ומסתיר על הנשמה ועל שם הוי' שבה, ובמתן תורה, ע\"י הדיבור אנכי הוי' אלקיך, נמשך זה בגילוי. וכמבואר בלקו\"ת<sup data-n=\"2878\">28</sup>, דפירוש (אנכי) הוי' אלקיך הוא, שהוי' יהי' מאיר ומתגלה בך כל כך עד שיהי' נקרא על שמך, אלקי<i>ך</i>. והכח על הוי' אלקיך [שגם לאחרי שהנשמה מתלבשת בגוף יהי' הוי' בו בגילוי ועד שיהי' נקרא על שמו] הוא מעצמות אוא\"ס שלמעלה גם מהוי'. דשם הוי' (מצד עצמו), הגילוי שלו הוא למעלה דוקא, ובכדי שיהי' בגילוי למטה בגוף גשמי הוא ע\"י המשכת עצמות אוא\"ס שלמעלה מהוי', דכל הגבוה יותר יורד ומתגלה למטה יותר<sup data-n=\"2879\">29</sup>. וזהו אנכי הוי' אלקיך, שהכח על זה שהוי' יהי' אלקיך, הוא מבחינת אנכי שלמעלה גם מהוי'.\n<b>ויש</b> לומר, דכיון ששמו של הקב\"ה ששיתף בישראל הוא שם הוי' שלמעלה משם אד' שמשותף במלאכים [ובפרט שהשורש דשיתוף שמו בישראל הוא מבחינת אנכי שלמעלה גם מהוי'], לכן, גם הביטול דישראל שנעשה ע\"י שמו ית' המשותף בהם הוא ביטול גדול יותר מביטול המלאכים.\nד) <b>וענין</b> שם הוי' שבכל אחד מישראל, מבאר בהמאמר<sup data-n=\"2880\">30</sup>, שהיו\"ד דשם הוי' שבישראל היא החכמה שבנפש, והה' דשם הוי' הוא הבינה שבנפש, להבין דבר מתוך דבר<sup data-n=\"2881\">31</sup>. ותוך דבר הוא הדבר הוי' שמתלבש בתוך הנבראים, כפירוש הבעש\"ט<sup data-n=\"2882\">32</sup> עה\"פ<sup data-n=\"2883\">33</sup> לעולם הוי' דברך נצב בשמים, ודבר הוא הדיבור עצמו שלמעלה מהתלבשות בנבראים, דבכללות הוא אור הסובב, וזהו להבין דבר מתוך דבר<sup data-n=\"2884\">34</sup>, שע\"י ההתבוננות בהדבר ה' המלובש בתוך הנבראים (תוך דבר) שהוא הארה בלבד (כדמוכח מזה גופא שהוא מלובש בתוך הנבראים) באים לידיעה שישנו \"דבר\" שלמעלה מהתלבשות בעולם, שהוא המקור שממנו נמשך ההארה שבהתלבשות. והו' דשם הוי' הם המדות שבנפש, וה' אחרונה דשם הוי' היא היראה תתאה (קבלת עול) שבנפש. וממשיך בהמאמר, שד' האותיות דשם הוי' שבכל אחד מישראל הם גם בהגוף שבו. שהראש הוא כציור תמונת היו\"ד והגוף כציור תמונת הוא\"ו וה' אצבעות שביד וה' אצבעות שברגל הן ב' ההי\"ן. ומוסיף בהמאמר, דיש לומר, דהטעם שישנם עשר אצבעות בידים ועשר אצבעות ברגלים הוא, כי בשם הוי' במילוי ההי\"ן, בכל ה\"ה ישנם שני ההי\"ן. ויש לומר דע\"י ההוספה שהמספר עשר אצבעות הוא כנגד ה\"הבמילואו מיתוסף ביאור בכללות הענין דציור שם הוי' שבגוף. דהנה ידוע בענין המילויים<sup data-n=\"2885\">35</sup>, שהטעם על זה שהמילוי של האות הוא בהעלם [וכמו באות אל\"ף, שהא' עצמו הוא בגילוי, והל' והפ' (שהם המילוי שלו) כלולים בו בהעלם], הוא, לפי שהמילוי הוא הפנימיות והעצמיות שלו שלמעלה מגילוי. ובדוגמת אדם שמדבר איזה ענין ויש לו בזה כוונה, שהכוונה היא בהעלם. ומזה מובן, דזה שבהציור דשם הוי' שבהגוף (דוקא) יש גם מילוי הההי\"ן דשם הוי', הוא, לפי שבהגוף דוקא מתגלה (גם) הפנימיות והעצמיות דשם הוי'. כי בכדי להיות המשכת שם הוי' בגוף הגשמי, הוא דוקא ע\"י הפנימיות והעצמיות דשם הוי'. וע\"ד המבואר לעיל (סעיף ג), שבכדי ששם הוי' שבהנשמה יהי' בגילוי גם בהתלבשותה בגוף הוא ע\"י ההמשכה דאנכי שלמעלה מהוי'. והחילוק שבין שני הענינים הוא, שהחידוש בהגילוי דשם הוי' שבהנשמה גם בהתלבשותה בגוף הוא רק בנוגע להמקום (גוף גשמי) ששם נמשך הגילוי, וע\"י שנמשך בהוי' מבחינת אנכי שלמעלה מהוי' נמשך הגילוי שלו למטה. והחידוש בהציור דשם הוי' בהגוף הוא בשם הוי' עצמו, כי שם הוי' (שלמעלה מעולם) וגוף (גשמי) הם שני הפכים. ולכן, בכדי ששם הוי' יצטייר כביכול בציור דגוף גשמי, אין זה ע\"י המשכת ענין שלמעלה ממנו, כי הפעולה שנעשית באיזה דבר ע\"י כח עליון היא רק שיומשך למטה יותר וכיו\"ב, אבל לא שינוי בהדבר עצמו. ובכדי ששם הוי' יצטייר כביכול בציור דגוף גשמי הוא ע\"י המשכת וגילוי הפנימיות והעצמיות דשם הוי' עצמו (המילוי דהוי'), ש(גם) הוי' עצמו בפנימיותו, אינו מוגדר בגדר הרוחני וביכלתו להיות גם בציור דגוף גשמי.\nה) <b>וממשיך</b> בהמאמר<sup data-n=\"2886\">36</sup>, דפירוש וידבר גו' לאמר הוא, שבמ\"ת ניתן הכח לכאו\"א מישראל שכשיקרא בתורה יהי' הקב\"ה קורא ושונה כנגדו. ועד\"ז הוא במצוות, דע\"י שאיש ישראל עושה מצוה הוא גורם וממשיך שהקב\"ה יעשה אותה<sup data-n=\"2887\">37</sup>. והכח שיש בכל אחד מישראל שע\"י לימוד התורה שלו יהי' הקב\"ה קורא ושונה כנגדו ושע\"י קיום המצוות שלו יהי' הקב\"ה מקיים את המצוות, הוא ע\"י הדיבור אנכי הוי' אלקיך לשון יחיד, כמבואר בהמאמר.\n<b>ויש</b> לומר, דהענינים המבוארים בהמאמר בתור הקדמה להפירוש דלאמר שלימוד התורה דהאדם גורם שיהי' הקב\"ה קורא ושונה כנגדו – הביטול דישראל ע\"י שהקב\"ה שיתף בהם את שמו, ושהכח שהוי' יהי' אלקיך הוא מאנכי שלמעלה מהוי' כי כל שההמשכה היא למטה יותר הוא לפי ששורש ההמשכה היא ממקור נעלה יותר – הם דוגמת שאר הפירושים בלאמר. דהפירוש בלאמר, שלימוד התורה הוא באופן דתען לשוני אמרתך כעונה אחר הקורא – הוא הדגשת ענין הביטול, והפירוש שוידבר גו' לאמר הוא ההמשכה דעשרת הדברות בעשרה מאמרות מדגיש המעלה דהמשכה למטה. וזה ששני ענינים אלה באים בהמאמר כהקדמה להפירוששלאמר הוא שע\"י לימוד התורה דהאדם גורם להיות הקב\"ה קורא ושונה כנגדו, הוא, כי כל הפירושים (הענינים) בלאמר שייכים זה לזה<sup data-n=\"2888\">38</sup>.\nו) <b>ויש</b> לומר הביאור בזה, דבמתן תורה ג' ענינים, הקב\"ה נותן התורה, וישראל מקבלי התורה, והתורה עצמה<sup data-n=\"2889\">39</sup>. והחידוש בהתורה שניתנה במתן תורה לגבי התורה שלמדו האבות לפני מתן תורה הוא הן בנוגע לנותן התורה, והן בנוגע למקבלי התורה והן בנוגע להתורה עצמה. שהחידוש בנוגע לנותן התורה הוא כדאיתא בגמרא<sup data-n=\"2890\">40</sup> שאנכי (הפתיחה דמתן תורה) הוא ר\"ת <i>א</i>נא <i>נ</i>פשי <i>כ</i>תבית <i>י</i>הבית, דאנא (נפשי) הוא עצמותו ית', ופירוש אנא נפשי כתבית יהבית הוא<sup data-n=\"2891\">41</sup> אַז ער האָט אַריינגעשריבן און אַריינגעגעבן זיך אַליין, אנא נפשי. ובלשון המדרש<sup data-n=\"2892\">42</sup> מכרתי לכם תורתי כביכול נמכרתי עמה. והחידוש בנוגע לישראל מקבלי התורה הוא, שבמ\"ת ניתנה התורה לבעלות כביכול של ישראל, שהכח לפסוק הלכות ניתן דוקא לישראל. דאין משגיחין בבת קול ויתירה מזו נצחוני בני נצחוני<sup data-n=\"2893\">43</sup>. והחידוש בנוגע לתורה עצמה הוא שהתורה שניתנה במתן תורה היא באופן של ציווי וגזירה שפועל על האדם והעולם להיות כהוראת התורה. וכמבואר בלקו\"ת<sup data-n=\"2894\">44</sup> בנוגע לעשרת הדברות שנאמרו במ\"ת (ומתוכן הענין שם מובן שעד\"ז הוא בנוגע לכל הציוויים דתורה) שנאמרו בלשון ציווי וגם בלשון עתיד, וכמו לא תרצח שהוא ציווי וגם הבטחה, כי הדיבור עצמו גוזר על האדם והעולם<sup data-n=\"2895\">45</sup> ופועל עליהם להיות כן. [והגם שחידוש זה הוא לכאורה רק בפעולת התורה על האדם והעולם ולא בהתורה עצמה, מ\"מ, כיון ששם תורה [דשמו של כל דבר מורה על תוכנו<sup data-n=\"2896\">46</sup>] הוא מלשון הוראה<sup data-n=\"2897\">47</sup>, הרי החידוש בהאופן דהוראת התורה [שהוראת התורה איך שהאדם והעולם צריכים להיות היא באופן שפועלת עליהם] נוגע להתורה עצמה<sup data-n=\"2898\">48</sup>].<b>ועד\"ז</b> הוא בלימוד התורה דישראל, כמבואר בלקו\"ת שם, דע\"י שישראל לומדים אלו טריפות בבהמה כו' ואלו כשרות כו'<sup data-n=\"2899\">49</sup>, נעשה בירור והבדלה בין טמא לטהור ויתפרדו כל פועלי און<sup data-n=\"2900\">50</sup> בדוגמת הפעולה בעולם שנעשית ע\"י הדברות שדיבר הקב\"ה במתן תורה.\n<b>ולהוסיף</b><b>,</b> שהחידוש שנעשה בהתורה שעל ידה נעשה שינוי בהעולם, מודגש עוד יותר במצוות התורה. שע\"י קיום מצוות התורה שלאחרי מתן תורה, נעשה בירור וזיכוך בדבר הגשמי שבו נעשית המצוה, ועד שבכמה ענינים נעשה הגשמי חפצא של מצוה, ועד אפילו חפצא של קדושה<sup data-n=\"2901\">51</sup>.\nז) <b>וזהו</b> שאמרו רז\"ל<sup data-n=\"2902\">52</sup> עה\"פ<sup data-n=\"2903\">53</sup> לריח שמניך טובים שמן תורק שמך, כל השירים<sup data-n=\"2904\">54</sup> שאמרו לפניך האבות ריחות היו אבל אנו שמן תורק שמך כאדם שמוריק מכלי לכלי, כל המצוות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך, דיש לומר, שבמרז\"ל זה מבוארים כל ג' הענינים שנתחדשו במתן תורה. דהחילוק שבין ריח לשמן בהם עצמם, שהריח הוא רק התפשטות (הארת) השמן, מורה על החידוש בתורה ובמצוות (שניתנו במ\"ת) בנוגע לנותן התורה ומצַוה המצוות. דהתורה כמו שהיא מצד עצמה (חכמתו של הקב\"ה) היא הארה בלבד (ריח), ואמיתית הענין דאורייתא וקוב\"ה כולא חד<sup data-n=\"2905\">55</sup> נעשה במתן תורה, שאז נמשך בה העצמות (שמן). ועד\"ז הוא בנוגע למצוות, שבמתן תורה נמשך בהם העצמות.\n<b>ועוד</b> חילוק בין ריח השמן להשמן עצמו, שע\"י שמריחים את ריח השמן לא נחסר מאומה מהשמן, משא\"כ כשלוקחים את השמן עצמו הוא נחסר בהמקום שהי' בו תחלה (שמן <i>תורק</i> שמך, כאדם <i>שמוריק</i> מכלי לכלי). ובהנמשל הוא, שע\"י נתינת התורה למטה, <i>ניטל</i><sup data-n=\"2906\">56</sup> מהעליונים הכח לפסוק דין, דתורה <i>לא</i> בשמים היא<sup data-n=\"2907\">57</sup>. ועוד חילוק בין ריח לשמן, דהריח הוא הולך וכלה ועד שלא נשאר ממנו מאומה, וגם ההנאה שהאדם נהנה מהריח, לאחרי שנפסק הריח עוברת הנאתו<sup data-n=\"2908\">58</sup>, משא\"כ המאכל (שמן<sup data-n=\"2909\">59</sup>), גם לאחרי שנתעכל המזון במעיו, נשאר במציאות, אלא שנהפך לדם ובשר,ועי\"ז הוא פועל בהאדם שהתכונות שלו יהיו כפי תכונות המאכל<sup data-n=\"2910\">60</sup>. ובהנמשל הוא, שההמשכה ע\"י קיום המצוות ומכש\"כ ע\"י לימוד התורה דהאבות לא <i>נקבעה</i> בהעולם <i>בפנימיותו</i><sup data-n=\"2911\">61</sup>. וע\"י לימוד התורה שלאחרי מ\"ת ומכש\"כ ע\"י קיום המצוות נעשה שינוי העולם <i>בפנימיות ובקביעות</i>.\nח) <b>ויש</b> לומר, דבג' ענינים הנ\"ל שנתחדשו במתן תורה, החידוש העיקרי הוא שבמ\"ת נעשה המשכת העצמות בתורה, ועי\"ז נעשה החידוש גם בהתורה ובמקבלי התורה. דהתורה מצד עצמה, כיון שהיא באין ערוך לגמרי להעולם, אין שינוי בהדברים שבעולם ע\"י דיני התורה, ועד\"ז הוא בנוגע למצוות. והכח שבהתורה והמצוות שניתנו במ\"ת לפעול שינוי בהעולם הוא כי במתן תורה נמשך העצמות בהתורה ומצוותי', ועי\"ז יש בהם הכח לפעול גם בהדברים שבעולם שאינם בערך להתומ\"צ כי העצמות הוא בכל מקום. ועד\"ז הוא בנוגע להכח שניתן לישראל לפסוק הלכות ועד לאופן דקוב\"ה חייך ואמר נצחוני בני נצחוני, דכח זה שבישראל הוא לפי ששורש הנשמות הוא בעצמותו ית' (למעלה מכמו שצמצם את עצמו בתואר קוב\"ה)<sup data-n=\"2912\">62</sup>. והגילוי דשורש הנשמה (כמו שמושרשת בהעצמות) בהנשמה כמו שבאה בהמשכה ועאכו\"כ בהנשמה המלובשת בגוף, הוא ע\"י התורה. דע\"י שהפתיחה דמתן תורה היתה באנכי ר\"ת אנא נפשי כתבית יהבית, שהכניס כביכול את עצמותו בתורה, עי\"ז נעשה אנכי (הוי') אלקיך (לשון יחיד) דכאו\"א מישראל, וע\"י עסק התורה שלו כדבעי, נמשך זה בגילוי.\n[<b>ויש</b> לומר, שהענין דאנכי אלקיך דישראל הוא למעלה מבחינת אנכי שבתורה. וכידוע<sup data-n=\"2913\">63</sup> שגם בהשורש דתורה וישראל כמו שהם בהעצמות, השורש דישראל הוא למעלה משורש התורה. דהתורה (גם כמו שהיא לאחרי מתן תורה, הענין דאנא נפשי כתבית יהבית) היא בשביל ישראל<sup data-n=\"2914\">64</sup>. אלא שהגילוי דאנכי אלקיך (דישראל) – נמשך ע\"י אנכי שבתורה].\n<b>וזהו</b> גם הטעם שגם ע\"י לימוד התורה דישראל נעשה שינוי בהדברים שבעולם, בדוגמת השינוי שנעשה בהעולם ע\"י עשרת הדברות של הקב\"ה (כנ\"ל סעיף ו מלקו\"ת), כי ע\"י שישראל עוסק בתורה נמשך הגילוי דאנכי (אנכי שבתורה, וגם אנכי אלקיך דישראל, שלמעלה מאנכי שבתורה), והדיבור (כביכול) דהעצמות פועל שינוי בהעולם, כנ\"ל.ט) <b>ויש</b> להוסיף ביאור בהשייכות דהשינוי בעולם שנעשה ע\"י לימוד התורה וקיום המצוות דהאדם להמשכת העצמות בהתומ\"צ, כי בכדי שבלימוד (דיבור) התורה דהאדם תהי' המשכת הדיבור דאנכי, הוא ע\"י שהלימוד שלו הוא בתכלית הביטול. ועד\"ז הוא בנוגע לקיום המצוות. ואמיתית הביטול שבלימוד התורה וקיום המצוות בא מזה שבהתורה והמצוות שניתנו במתן תורה ישנה המשכת העצמות. דלימוד התורה וקיום המצוות של האבות קודם מתן תורה, כיון שעבודת האבות הגיעה רק עד שורש הנבראים<sup data-n=\"2915\">65</sup>, דלגבי שורש הנבראים יש תפיסת מקום להנבראים, לכן, הביטול שלהם לא הי' ביטול בתכלית. וזהו מ\"ש באברהם<sup data-n=\"2916\">66</sup> ואנכי עפר ואפר, שגם אפר הוא מציאות<sup data-n=\"2917\">67</sup>. והביטול שע\"י לימוד התורה וקיום המצוות שלאחרי מתן תורה הוא ביטול בתכלית, בדוגמת הביטול דמשה (מקבל התורה) דכתיב בי'<sup data-n=\"2918\">68</sup> ונחנו מה. [ויש לומר, דזה שכאו\"א מישראל יכול להגיע ע\"י תומ\"צ להביטול דמ\"ה הוא לפי שבמ\"ת נעשה הוי' אלקיך (כנ\"ל סעיף ג' וד') והוי' במילוי אלפי\"ן בגימטריא מ\"ה, והביטול שנעשה ע\"י המשכת העצמות (אנכי שלמעלה מהוי') בתורה ומצוותי' הוא למעלה גם מהביטול דמ\"ה].\nיו\"ד) <b>ועפ\"ז</b> יש לומר שג' הענינים (פירושים) דלאמר הם בהתאם לג' הענינים שנתחדשו במתן תורה. דהפירוש בלאמר שבמ\"ת נתחדש שלימוד התורה של האדם יהי' בתכלית הביטול, באופן דתען לשוני אמרתך כעונה אחר הקורא, הוא מצד החידוש שנעשה במ\"ת בנוגע לנותן התורה. וכנ\"ל (סעיף ט) שאמיתית הביטול שבלימוד התורה בא מזה שבהתורה שניתנה במתן תורה ישנה המשכת העצמות. והפירוש דלאמר שהאדם הלומד תורה אומר להקב\"ה שיחזור כביכול על הדיבור שלו, הוא מצד החידוש שנעשה במ\"ת בנוגע לישראל מקבלי התורה, שניתן להם הכח לפעול כביכול בהקב\"ה, נצחוני בני נצחוני. והפירוש בלאמר שעשרת הדברות נמשכים ופועלים בהעשרה מאמרות הוא מצד החידוש שנעשה במ\"ת בהתורה שהיא מושלת ושולטת על העולם.\n<b>ויש</b> לקשר זה עם מה שאמרו רז\"ל<sup data-n=\"2919\">69</sup> אין לך בן חורין אלא מי שעוסק בתלמוד תורה, דכיון שהתורה מושלת ושולטת על העולם, הרי כשעוסק בתורה אין שייך שיהי' מי שהוא שולט עליו<sup data-n=\"2920\">70</sup>, דאדרבה, הוא מושל ושולט על כל העולם. ומגאולה הפרטית (שע\"י עסק התורה נעשה בן חורין) באים לגאולה הכללית, שאז יהי' אמיתית החירות, בגאולה האמיתית והשלימה ע\"י משיח צדקנו בקרוב ממש.\n**********",[["2850","*","יצא לאור ב<b>קונטרס חג השבועות – תש\"נ</b>, \"לקראת חג השבועות . . <i>יום ג' פ' נשא</i>,<i> ערב חה\"ש</i>,<i> שנת ה'תש\"נ</i>\"."],["2851","1","יתרו כ, א."],["2852","2","תו\"א יתרו סז, ב (ועם הגהות – באוה\"ת יתרו ע' תשפג ואילך). סה\"מ תקס\"ז ע' קמט. לקו\"ת שה\"ש מ, ב. שם מב, סע\"א ואילך. תו\"ח יתרו שע, סע\"א [בהוצאה החדשה – ח\"ב רנג, ב]. רד\"ה וידבר גו' אנכי תרכ\"ט (דלקמן בפנים). <i>ובכ\"מ</i>."],["2853","3","פדר\"א פמ\"א. שמו\"ר פכ\"ח, ו. תנחומא יתרו יא. זח\"א צא, א. ובכ\"מ."],["2854","4","ראה לקו\"ש ח\"ו ע' 119, ובהנסמן שם הערה *&lt;1&gt;."],["2855","5","יומא כח, ב. קידושין פב, א (במשנה)."],["2856","6","כ\"ה הלשון בתו\"א שם סז, ד."],["2857","7","ו\"מימיהן של אבותינו לא פרשה ישיבה מהם . . אברהם אבינו זקן ויושב בישיבה הי' . . יצחק אבינו זקן ויושב בישיבה הי' . . יעקב אבינו זקן ויושב בישיבה הי'\" (יומא שם)."],["2858","8","כהדיוק בתו\"א שם. לקו\"ת במדבר יג, ד. <i>ובכ\"מ</i>."],["2859","9","ד\"ה וידבר גו' אנכי תרכ\"ט (דלקמן בפנים) – סה\"מ תרכ\"ט ע' רג (הובא לקמן סעיף ה)."],["2860","10","ראה תדא\"ר פי\"ח. יל\"ש איכה רמז תתרלד."],["2861","11","להעיר מחדא\"ג מהרש\"א שבת (פט, א), דפירוש הכתוב (שלח יד, יז) \"כאשר דברת לאמר\" הוא \"כאשר דברת לי לאמר שאומר אני\", היינו שמשה יאמר <i>להקב\"ה</i> (יגדל נא כח אד'). וע\"פ המבואר בכ\"מ (ראה סד\"ה ועתה יגדל נא גו' ה'תשי\"ט (לקמן ס\"ע שעח), ובהנסמן שם הערה 47) ד\"כאשר דברת לאמר\" הוא ע\"ד \"וידבר גו' לאמר\" – מסתבר, שכ\"ה גם הפירוש ד\"לאמר\"."],["2862","12","תהלים קיט, קעב."],["2863","13","תו\"א שם סז, ב. תו\"ח שם שע, ב [שם רנג, ב] ואילך (וראה שם שעג, ב [שם רנה, ב]). ובכ\"מ. ולהעיר, שגם לפירוש זה שהאדם חוזר הדברים שהקב\"ה אומר – מובן, דזה שהקב\"ה אומר הדברים עכשיו נעשה זה ע\"י לימוד האדם. אבל <i>הפירוש</i> ד\"לאמר\" הוא (לא שהאדם פועל למעלה, אלא אדרבה) שדיבור האדם הוא כעונה אחר הקורא."],["2864","14","ראה ד\"ה וידבר גו' אנכי ה'תשכ\"ח ס\"א (לעיל ע' שכו). <i>וש\"נ</i>."],["2865","15","אבות פ\"ה מ\"א."],["2866","16","ראה לקו\"ת חוקת נז, סע\"ג ואילך. וראה גם לקו\"ת שה\"ש כה, ג. ובכ\"מ."],["2867","17","לקו\"ת שלח לט, סע\"ב ואילך."],["2868","18","משנת אמירת מאמר זה (תשכ\"ט) – נדפס בסה\"מ תרכ\"ט ע' קצג ואילך."],["2869","19","שמעוני עה\"פ יתרו כ, ב."],["2870","20","יתרו שם."],["2871","21","שמו\"ר רפכ\"ט. יל\"ש שם."],["2872","22","תהלים סח, יח."],["2873","23","בהבא לקמן, ראה אוה\"ת (יהל אור) לתהלים שם ע' רמ. ד\"ה הנ\"ל תרכ\"ט (סה\"מ שם ע' קצד ואילך)."],["2874","24","אגה\"ת פ\"ד (צד, א)."],["2875","25","לקו\"ת דרושים לשבת שובה סה, ד. סהמ\"צ להצ\"צ ס, א. ובכ\"מ."],["2876","26","האזינו לב, ט."],["2877","27","אגה\"ת שם."],["2878","28","ר\"פ ראה."],["2879","29","ראה בארוכה שערי אורה שער הפורים ד\"ה יביאו לבוש מלכות פי\"ב (נח, א-ב). שם פל\"ב ואילך (סה, א ואילך). וראה בהנסמן לעיל ח\"ב ס\"ע כד ואילך."],["2880","30","ס\"ע קצו ואילך. וראה אגה\"ת שם (צד, ב ואילך). לקו\"ת שם. ובכ\"מ."],["2881","31","לשון חז\"ל – חגיגה יד, א. סנהדרין צג, ב."],["2882","32","שעהיוה\"א בתחלתו."],["2883","33","תהלים קיט, פט."],["2884","34","ראה גם תו\"א בראשית א, א. הוספות לפ' ויקהל קיג, ג. לקו\"ת ואתחנן ו, סע\"ג. ראה כה, סע\"ב. שבת שובה סז, ד. ובכ\"מ."],["2885","35","ספהמ\"צ להצ\"צ קט, ב. אוה\"ת שלח ס\"ע תקב ואילך. וראה בארוכה ספר הערכים-חב\"ד מערכת אותיות בה\"מבוא\" ע' יב ואילך. <i>וש\"נ</i>."],["2886","36","ע' רג."],["2887","37","ראה לעיל ח\"ב ע' קמה. <i>וש\"נ</i>."],["2888","38","ובמכש\"כ מזה שכל הפירושים שבפסוק אחד שייכים זה לזה, כידוע הראי' לזה מ\"שעטנז\" (נדה סא, ב) – ראה לקו\"ש ח\"ג ע' 782. ובכ\"מ."],["2889","39","ולהעיר שבהדרושים שבלקו\"ת פרשת במדבר (יב, ג ואילך) המדברים בענין מתן תורה – דרוש הראשון הוא בשעה שהקדימו <i>ישראל</i> נעשה לנשמע [וגם בדרוש \"ענין שניתנה התורה על הר סיני\" (טו, סע\"ב ואילך) מדובר בענין הביטול וכו' <i>דהאדם</i>]; לאח\"ז בא הדרוש \"וידבר <i>אלקים</i> גו'\", ולאח\"ז הדרוש ואהי' אצלו אמון גו' שקאי על <i>תורה</i>."],["2890","40","שבת קה, א (כגירסת הע\"י). יל\"ש שם."],["2891","41","לקו\"ת שלח מח, סע\"ד ואילך. ובכ\"מ."],["2892","42","שמו\"ר רפל\"ג."],["2893","43","ב\"מ נט, ב."],["2894","44","במדבר יג, ג."],["2895","45","ויש לומר, שמצד <i>גדר הבריאה</i>, מכיון שהדיבור דתורה <i>גוזר</i> על האדם והעולם, מוכרחים הם להיות כהוראת וגזירת התורה. וזה שיש לאדם בחירה חפשית הוא שביכלתו לבחור להיות היפך טבע הבריאה."],["2896","46","שעהיוה\"א בתחלתו."],["2897","47","ראה רד\"ק לתהלים יט, ח. ספר השרשים שלו ערך ירה. גו\"א ר\"פ בראשית בשם הרד\"ק. וראה זח\"ג נג, ב."],["2898","48","ויש לומר, דזה שהתורה דוקא נקראת בשם תורה מלשון הוראה – אף שבכמה חכמות ישנם לכאורה (גם) הוראות [ולהעיר ממארז\"ל (איכ\"ר פ\"ב, יג) \"יש חכמה בגוים תאמין . . יש תורה בגוים אל תאמין\"] – הוא, כי ההוראות שבכל החכמות הם <i>חלק מהחכמה</i> (שע\"פ <i>כללי החכמה</i> צריך האדם להתנהג כך וכך) אבל אינם הוראות <i>להאדם</i> כיון שאין להם פעולה עליו; ודוקא תורה שפועל על האדם (שביכלתו לבחור היפך הטבע) היא הוראה להאדם."],["2899","49","משנה דחולין רפ\"ג (מב, א. נד, א)."],["2900","50","לשון הכתוב – תהלים צב, י."],["2901","51","ראה בארוכה לקו\"ש חט\"ז ע' 212 ואילך. \"הדרן\" על הש\"ס (תשמ\"ט) ס\"ה ואילך (תורת מנחם – הדרנים על הרמב\"ם וש\"ס ע' קסג ואילך)."],["2902","52","שהש\"ר פ\"א, ג (א)."],["2903","53","שה\"ש א, ג."],["2904","54","\"שירים\" הוא תורה, כמרז\"ל (חגיגה יב, ב) \"כל העוסק <i>בתורה</i> בלילה כו' שנאמר כו' ובלילה <i>שירה</i> עמי\" (סה\"מ ה'תש\"ו ע' 102)."],["2905","55","ראה זח\"ג עג, א."],["2906","56","ראה ד\"ה אנכי הוי' אלקיך ה'תשמ\"ט הערה 53 (לעיל ע' שיג)."],["2907","57","וע\"פ מ\"ש בפנים יומתק שענין \"כאדם <i>שמריק</i> כו'\" נאמר במדרש גבי שירים (תורה) דוקא."],["2908","58","שלכן אין מברכין על הריח ברכה אחרונה (מג\"א או\"ח ר\"ס רטז)."],["2909","59","שאפשר לאכלו עם פת או לשתותו ע\"י שמערבין אותו בשאר משקין (סדר ברכת הנהנין לאדה\"ז פ\"ג ה\"א). ולהעיר, שגם כששותין אותו כשהוא בפני עצמו, שאז הוא מזיק להאדם (סדר ברה\"נ שם) – ה\"ז גופא שמזיק מורה על זה דהמאכל נכנס בפנימיות."],["2910","60","כידוע בטעם איסור אכילת בע\"ח הדורסים וטורפים (רמב\"ן עה\"פ שמיני יא, יא. ועוד). וראה גם ברכות מד, ב."],["2911","61","ראה לקו\"ש ח\"ה ע' 395 ואילך שגם המצוות דהאבות פעלו <i>במקצת</i> בדברים הגשמיים שבהם נעשו המצוות (גם <i>לאחרי</i> קיום המצוה), דכיון שמעשה אבות סימן ונתינת כח לבנים בהכרח שיהי' בהם איזו דוגמא עכ\"פ להמצוות שלאחרי מ\"ת. אלא שהפעולה לא <i>נקבעה</i> בהדברים בהם נעשו המצוה <i>בפנימיותם</i>."],["2912","62","ראה בארוכה לעיל ח\"א ע' לב."],["2913","63","ראה לעיל ע' רפח ואילך. וש\"נ."],["2914","64","להעיר ממרז\"ל (הובא לעיל סעיף ו) \"מכרתי את תורתי כביכול נמכרתי עמה\", דיש לומר הפירוש בזה שגם נותן התורה נמכר כביכול לישראל מקבלי התורה – שגם הענין ד\"אנא נפשי\" שבתורה אינו העצמות ממש, והוא טפל כביכול לישראל ששרשם בהעצמות ממש."],["2915","65","סה\"מ תש\"ג ע' 23. ובכ\"מ."],["2916","66","וירא יח, כז."],["2917","67","באגה\"ק סט\"ו \"שהאפר אין לו דמיון וערך אל מהות העץ כו'\", אבל אעפ\"כ הוא מציאות."],["2918","68","בשלח טז, ז."],["2919","69","אבות פ\"ו מ\"ב."],["2920","70","ראה עירובין נד, א: אלמלי לא נשתברו לוחות הראשונות . . אין כל אומה ולשון שולטת בהן, שנאמר חרות, א\"ת חרות אלא חירות. וראה שמו\"ר פמ\"א, ז (בתחלתו)."]]],[1500380051,"<h3>בס\"ד. יום ב' דחג השבועות, ה'תשמ\"ו<sup data-n=\"2921\">*</sup></h3>\n<b>אתה</b><sup data-n=\"2922\">1</sup> הראת לדעת כי ה' הוא האלקים אין עוד מלבדו, כתוב במשנה תורה (שמשה מפי עצמו אמרה<sup data-n=\"2923\">2</sup>), ומבאר רבינו הזקן בספר התניא<sup data-n=\"2924\">3</sup> דענין זה הי' בשעת מתן תורה, דאז הי' הגילוי דאתה הראת לדעת גו', כתורת אדמו\"ר הזקן<sup data-n=\"2925\">4</sup> אתה דו עצמות א\"ס ב\"ה הראת דו האָסט זיך באַוויזן לדעת אַז מען זאָל דיך וויסן, כי הוי' הוא האלקים אין עוד מלבדו, שהם<sup data-n=\"2926\">5</sup> ב' אופני ועניני השגה בהשגות אלקות, הא' הוא ההשגה דהוי' ואלקים כולא חד והב' הוא ההשגה דאין עוד מלבדו. ובזה מבאר בתניא שם, שבשעת מ\"ת הי' גילוי זה (דעצומ\"ה וכו') באופן דהראת (ומוסיף) ממש בראי' חושיית. וממשיך בתניא שם, דלכן היו (ישראל) בטלים במציאות ממש כמארז\"ל (בגמרא<sup data-n=\"2927\">6</sup>) שעל כל דיבור ודיבור פרחה נשמתן כו' והחזירה הקב\"ה להן בטל שעתיד להחיות בו את המתים, וכדאיתא בגמרא שם שזהו מה שאמר דוד המלך<sup data-n=\"2928\">7</sup> (בעל ההילולא דחג השבועות<sup data-n=\"2929\">8</sup>) גשם נדבות תניף אלקים נחלתך ונלאה אתה כוננתה, דקאי על טל תחי' שהחי' בו את ישראל, ומבאר בתניא שם, דטל זה הוא טל תורה כו' כמארז\"ל<sup data-n=\"2930\">9</sup> כל העוסק בתורה טל תורה מחייהו כו'.\nב) <b>והנה</b> ידוע ביאור מורנו הבעל שם טוב<sup data-n=\"2931\">10</sup> (בעל ההילולא דחג השבועות<sup data-n=\"2932\">11</sup>), דכל ענין שבעולם הוא הוראה בעבודת האדם לקונו. וכ\"ש וק\"ו כל ענין שבתורה, כמ\"ש<sup data-n=\"2933\">12</sup> ויצוונו ה' לעשות את כל החוקים האלה ליראה את ה' אלקינו גו', דמפסוק זה מוכח, שכל התורה כולה (כל החוקים האלה) ענינה הוא הוראה בעבודת ה', ליראה את ה\"א גו', עד לקיום המצוות בפשטות. ומזה מובן, דגם ענין זה שבתורה, זה שעל כל דיבור ודיבור פרחה נשמתן והחזירה להן בטל כו', הוא הוראה בעבודת האדם לקונו. ועוד זאת, דהנה מבאר מורנו הבעש\"ט בכתר שם טוב<sup data-n=\"2934\">13</sup> במאמררז\"ל<sup data-n=\"2935\">14</sup> דע מה למעלה ממך, ר\"ל ממך תדע, איזה מדה שנתעורר בך כך הוא למעלה [ובמ\"א<sup data-n=\"2936\">15</sup> הובא ע\"ד זה בשם הרב המגיד, ובמקום שלישי<sup data-n=\"2937\">16</sup> הובא בשם רבינו הזקן, ויש שינויי לשונות ביניהם, ואכ\"מ]. ומזה מובן, דכשהאדם רואה ויודע בעצמו (ממך) שאצלו הוא זמן מתן תורתנו (מכיון שכך מפורש בתורת אמת ותורת חיים), הרי מובן מזה, שכן הוא גם למעלה, שלמעלה הוא זמן מתן תורתנו. והיינו, שבזמן מתן תורתנו נעשה אתה הראת לדעת כי ה' הוא האלקים אין עוד מלבדו, דו עצמות א\"ס ב\"ה האָסט זיך באַוויזן כו', הראת ממש בראי' חושיית, ויחד עם זה נמשך בישראל גם הטל שעתיד להחיות בו את המתים והוא טל תורה. וענין זה נמשך בכל עניני האדם, (ע\"ד מ\"ש<sup data-n=\"2938\">17</sup> זאת התורה אדם), שהתורה (גם בחי' טל תורה) חודרת במציאותו של אדם עד שנעשית מציאותו האמיתית של כאו\"א מישראל, כולל בכל דרכיך ובכל מעשיך<sup data-n=\"2939\">18</sup> (כמבואר במ\"א<sup data-n=\"2940\">19</sup> הענין בזה). ומזה מובן עוד יותר, שענין זה (טל תורה) נוגע בעבודת האדם בזמן הזה.\nג) <b>והנה</b> הובא לעיל, שבגמרא הובא ע\"ז הכתוב (שאמר דוד) גשם נדבות תניף אלקים גו', ולכאורה צריך להבין, הרי בפסוק כתיב גשם נדבות, גשם דייקא, וא\"כ מהו שמסיים שהחזירה להם בטל תחי', טל דייקא. ומבואר במ\"א<sup data-n=\"2941\">20</sup>, שבחי' גשם נדבות (לא גשם סתם) הוא ע\"ד ענין הטל. אך עדיין צריך להבין למה נק' בשם גשם דוקא. וביאור הענין יובן ע\"פ מה שמבאר כ\"ק אדמו\"ר האמצעי במאמרו ד\"ה ענין טל תורה<sup data-n=\"2942\">21</sup> (והוא המשך לד\"ה להבין ענין עומר שעורים ושתי הלחם שנת\"ל בד\"ה זה דערחה\"ש), דהנה כתיב<sup data-n=\"2943\">22</sup> יערוף כמטר לקחי תיזל כטל אמרתי (דכתוב זה קאי על התורה, שהרי אמרו משה רבינו, אשר משה קיבל תורה מסיני ומסרה כו'<sup data-n=\"2944\">23</sup>, ועד שהתורה נקראת על שמו<sup data-n=\"2945\">24</sup>), הרי יש בתורה ב' מדרגות בחי' טל ובחי' מטר. ומבאר בזה<sup data-n=\"2946\">25</sup>, דהנה ידוע שהמטר בא מסיבת האדים שעולים מן הארץ כו' [וכמ\"ש<sup data-n=\"2947\">26</sup> ואד יעלה מן הארץ והשקה את כל פני האדמה, שזהו הגשם המשקה את פני האדמה, וכמ\"ש<sup data-n=\"2948\">27</sup> כי כאשר ירד הגשם גו' הרוה את הארץ והולידה והצמיחה גו'], אבל הטל הוא היורד מלמעלה מעצמו כמאמר<sup data-n=\"2949\">28</sup> טל לא מיעצר. ועד\"זיש ב' מיני המשכות והשפעות מלמעלה<sup data-n=\"2950\">29</sup>, הא' הנמשך מלמעלה למטה ע\"י אתעדל\"ת, שזהו בחי' מטר, כמו המטר הנמשך ע\"י האד העולה מן הארץ, והיינו ע\"י יגיעה ועבודה מלמטה. וכמארז\"ל<sup data-n=\"2951\">30</sup> על הפסוק יערוף כמטר לקחי, שברו הבריות את ערפן מיד מטר יורד. ובעבודת האדם הנה בחי' עורף הוא בחי' אחוריים (היפך בחי' פנים)<sup data-n=\"2952\">31</sup>, אחרי ה\"א תלכו<sup data-n=\"2953\">32</sup>, ושברו הבריות ערפן הוא ביטול ענין זה (דהעלם והסתר) הבא ע\"י עבודה ויגיעה. ואין הכוונה בזה שבירת הגוף בפשטות ח\"ו, אלא שהנשמה בגוף, גוף בריא בכל רמ\"ח אברים ושס\"ה גידים, והשבירה אינה אלא שבירת הלב בלבד (ושבירת העורף, ומה לי קטלא כולא מה לי קטלא פלגא<sup data-n=\"2954\">33</sup>). ואדרבה, ע\"י שבירת הלב בא הגוף לשלימות יותר, כפתגם הידוע שאין לך דבר שלם כלב נשבר<sup data-n=\"2955\">34</sup>. ועי\"ז המטר יורד מלמעלה, והמטר משקה את הארץ והולידה והצמיחה וכו'. וההמשכה הב' מלמעלה היא בחי' טל שנמשך מעצמו בלי אתעדל\"ת כלל וכמו הטל שיורד מעצמו, כמאמר טל לא מיעצר (כנ\"ל).\nד) <b>וזהו</b> יערוף כמטר לקחי תיזל כטל אמרתי, דכשם שיש ב' בחי' אלו (אתעדל\"ע הנמשכת ע\"י אתעדל\"ת ואתעדל\"ע שלמעלה מאתעדל\"ת) בהשפעות אלקות בכלל, כך ישנם ב' ענינים אלו בתורה (לקחי ואמרתי). דענין שפע האור דתורה הנק' מטר הוא בחי' חיצוניות שבתורה (נגלה דתורה) הנמשך ע\"י עבודת האדם ויגיעת האדם. וכמאמר<sup data-n=\"2956\">35</sup> יגעתי ומצאתי תאמן, דמזה מובן, שהמציאה נמדדת לפי ערך היגיעה. והגם שמבואר במ\"א<sup data-n=\"2957\">36</sup>, שענין מציאה אינו בערך להיגיעה (כמו מציאה כפשוטה שהמוצא אותה אינו יודע ממי בא לו המציאה<sup data-n=\"2958\">37</sup>, ומוצא אותה בדרך ממילא<sup data-n=\"2959\">38</sup>), מ\"מ יש לזה איזה ערך ושייכות להיגיעה, ואם מתייגע במקום שהמציאה אינה שם לא ימצא אותה, וכמ\"ש<sup data-n=\"2960\">39</sup> ובקשתם משם גו', ומבואר בלקו\"ת<sup data-n=\"2961\">40</sup> דמ\"ש משם דייקא הוא משום שאי אפשר למצוא אבידה כ\"א במקום שנאבדה. משא\"כ טל שבתורה הוא בחי' השפעה שנמשך מעצמו, והוא בחי' טלא דבדולחא, טלא דנטיף מעתיקא קדישא<sup data-n=\"2962\">41</sup>, שעתיד להחיות בו את המתים, בחי' פנימיות התורה. ולכן נאמר בו תיזל כטל, דענין תיזל הוא מלשון נוזל, היינו שנמשך ויורד למטה מטה כמו שהוא במקורו ושרשו בבחי' המזל. וגילוי בחי' טל תורה יהי' לע\"ל, כמבואר בהמשך הדרוש שם שזהומשארז\"ל כל העוסק בתורה טל תורה מחייהו, שע\"י העסק בתורה בנגלה בזמן הזה יומשך לע\"ל בחי' טל תורה<sup data-n=\"2963\">42</sup>, פנימיות התורה. [וכמבואר גם במ\"א<sup data-n=\"2964\">43</sup> במשארז\"ל<sup data-n=\"2965\">44</sup> אשרי מי שבא לכאן ותלמודו בידו, שע\"י לימוד נגלה דתורה (תלמודו) בזמן הזה זוכים לגילוי סודות התורה דלע\"ל]. וזה גם מ\"ש<sup data-n=\"2966\">45</sup> תורה חדשה מאתי תצא. שגילוי בחי' תורה חדשה (טל שבתורה) יהי' לע\"ל דוקא.\nה) <b>ובזה</b> יובן גם זה שבחי' טל זה הוא טל שעתיד להחיות בו את המתים, כי החידוש דתחיית המתים הוא שנמשך מבחינת אתעדל\"ע שלמעלה מאתעדל\"ת. וכמבואר בכמה דרושים<sup data-n=\"2967\">46</sup> החידוש והשינוי דתחיית המתים לגבי גן עדן. דהנה תחיית המתים היא למעלה מג\"ע, כדמוכח מנוסח ברכת יוצר (דשבת) אין ערוך כו' ואין זולתך מלכנו לחיי העולם הבא (ג\"ע) כו' (ואח\"כ) ואין דומה לך מושיענו לתחיית המתים, ואעפ\"כ הנה בנוגע לג\"ע צ\"ל עבודת האדם, הן העבודה לפני זה (בתור הכנה לג\"ע) והן העבודה בג\"ע עצמו, שזהו ענין העליות שבג\"ע מדרגא לדרגא ע\"י העמוד שבין ג\"ע לג\"ע וכו'<sup data-n=\"2968\">47</sup>, ולא זו בלבד, אלא שלא כל אדם זוכה לג\"ע (כמובא הלשון בכ\"מ<sup data-n=\"2968\">47</sup>) (העליון) משום שהוא תלוי בעבודה, משא\"כ בנוגע לתחיית המתים תנן<sup data-n=\"2969\">48</sup> כל ישראל יש להם חלק לעוה\"ב, ואף שאיתא בהמשך המשנה חוץ כו', מ\"מ מבואר בירושלמי<sup data-n=\"2970\">49</sup>, שע\"י הבירור והזיכוך שלאח\"ז גם הם ישובו לתחי'. ומבואר הטעם בזה<sup data-n=\"2967\">46</sup>, משום שגילוי האלקות שבג\"ע שרשו הוא מבחי' אתעדל\"ע שנמשכת ע\"י אתעדל\"ת, ממכ\"ע, ולכן ה\"ה תלוי בעבודת האדם, משא\"כ הגילוי דתחה\"מ הוא סוכ\"ע, אתעדל\"ע שלמעלה מאתעדל\"ת, ולכן אינו תלוי בעבודת האדם אלא כל ישראל יש להם חלק לעוה\"ב. וזהו ענין טל תחי', כמשנת\"ל, שבחי' טל הוא בחי' שנמשך מעצמו בלי שום אתעדל\"ת.\nו) <b>אמנם</b> אעפ\"כ, בהכרח לומר ומובן ופשוט מעצמו (און ס'איז געשמאַק צו זאָגן), שענין זה ישנו כבר עכשיו, וכנודע שהכל ניתן במתן תורה. והענין הוא, דהנה בתניא (שם) מבאר רבינו הזקן (בענין גילוי האלקות שיהי' לע\"ל ובפרט בתחיית המתים) שכבר הי' לעולמים מעין זה בשעת מתן תורה כדכתיב אתה הראת לדעת כו'. והיינו, שענין זה (הגילוי דתחיית המתים) כבר נמשך במ\"ת, ולא עוד אלאשמדייק בלשונו כבר הי' לעולמים דייקא. די\"ל הכוונה בזה, שנמשך בגדרי העולם, שזה כולל גדרי הזמן וגדרי המקום<sup data-n=\"2971\">50</sup>, כב' הפירושים בתיבת עולם<sup data-n=\"2972\">51</sup> (עולמים), שזהו שמו אשר יקראו לו בלשון הקודש, המהווה ומחי' ומקיים אותו<sup data-n=\"2973\">52</sup>. וי\"ל שזהו הביאור בפתגם היודע שמ\"ת לא יהי' עוד הפעם<sup data-n=\"2974\">53</sup>, כי מכיון שהכל כבר ניתן בשעת מ\"ת, וא\"כ אין צורך (מ'דאַרף ניט) שיומשך עוד הפעם, וכיון שאין צורך בדבר ממילא מובן שלא יהי' מ\"ת עוה\"פ. וע\"ד המבואר בכ\"מ<sup data-n=\"2975\">54</sup>, שכל התורה כולה כלולה בעשה\"ד שניתנו במ\"ת, עד\"ז הוא בעניננו, שכל הדרגות שבתורה, כולל בחי' טל תורה דלעתיד, הכל ניתן במתן תורה. וענין זה ניתן לכל ישראל, כדאיתא במדרש<sup data-n=\"2976\">55</sup> שהתורה ניתנה לכאו\"א לפי כחו, כולל גם יונקים ונשים מעוברות וכו' (היינו שאפילו עוברין שבמעי אמן היו (וקבלו) בקבלת התורה), ולא זו בלבד אלא<sup data-n=\"2977\">56</sup> גם כל הנשמות שלא ירדו אז לעולם עדיין, או הנשמות שכבר ירדו ועלו לפנ\"ז<sup data-n=\"2978\">57</sup>, כולם היו בשעת מ\"ת.\nז) <b>והנה</b> בזה גופא (מה שבחי' טל תורה כבר ניתן במתן תורה) יש ב' אופנים. דאפשר שענין זה יהי' טמון ונעלם כמו אוצר דהון יקר הכמוס וחתום מעין כל רואה<sup data-n=\"2979\">58</sup>, וכמו שהתורה בכלל היתה חמדה גנוזה<sup data-n=\"2980\">59</sup> לפני מתן תורה. דגם ענין זה פועל עילוי בישראל, כמו בפשטות, שמי שיש בבעלותו אוצר גדול, הרי אף שאינו משתמש בו מאיזו סיבה שתהי', מ\"מ יש לו ערך גדול יותר, שנחשב לעשיר גדול. וכ\"ה להלכה בהלכות ערכין דכתיב<sup data-n=\"2981\">60</sup> על פי אשר תשיג ידו יעריכנו הכהן, שתלוי בהישג ידו, ואם יש לו אוצר גדול (אף שלא השתמש בו) נערך עשיר, ועד שזה מובן בפשטות גם אצל תגרי לוד, ובמנהג דרך ארץ, וגם בחו\"ל וגם בשבעים אומות העולם. ועד\"ז יובן בנמשל, כשבחי' טל שבתורה היא באופן דאוצר נעלם בידי ישראל (מזמן מ\"ת), פועל שיהיו נערכים באופן נעלה ביותר ע\"י הכהן, אלקיכם כהן הוא<sup data-n=\"2982\">61</sup>, ועד שענין זה פועל גם בע' האומות. אבל מ\"מ אין זה החידוש האמיתי דמתן תורה, וגם לפני מתן תורה היתה התורה בבחי' חמדה גנוזה, והחידוש דמ\"ת הוא שהתורה תומשך בישראל בפנימיות ובגלוי ובפשטות. ועד\"ז הוא בבחי' טל שבתורה, שאינו מספיק זה שענין זה כבר ניתן (בהעלם) בשעת מ\"ת, אלא צריך שיפעול גם בפנימיות, וכמ\"ש<sup data-n=\"2983\">62</sup> כי היא חכמתכם ובינתכם גו', דעיקר ענין התורה הוא שהיא בבחי' חכמה ובינה, בחי' לימוד בהבנה והשגה.ח) <b>והענין</b> הוא, דהנה איתא במשנה<sup data-n=\"2984\">63</sup> אין דורשין במעשה מרכבה ביחיד אא\"כ הי' חכם ומבין מדעתו, די\"ל, דע\"י הלימוד דיחיד זה במעשה מרכבה (דהיינו פנימיות התורה), ה\"ה מוציא עי\"ז<sup data-n=\"2985\">64</sup> את כל תלמידיו וכל כלל ישראל בהבנה והשגה בפנימיות התורה. אך ע\"פ משנ\"ת שהגילוי דמ\"ת הי' לכל ישראל, צריך לומר, שגם ענין זה (ההבנה והשגה בבחי' טל תורה) צ\"ל בכל ישראל. ויש לומר<sup data-n=\"2986\">65</sup>, דזהו החידוש דתורת החסידות, שיהי' לימוד פנימיות התורה (בחי' טלא דבדולחא, טלא דנטיף מע\"ק) באופן דהבנה והשגה, ובאופן דיתפרנסון מיני'<sup data-n=\"2987\">66</sup>. כי הגם שבדורות הקודמים היתה הגבלה דאין דורשין במעשה מרכבה ביחיד כו', הנה בזמן הזה, בערב שבת<sup data-n=\"2988\">67</sup>, הרי הפס\"ד בשו\"ע<sup data-n=\"2989\">68</sup> שבע\"ש צ\"ל הטעימה<sup data-n=\"2990\">69</sup> מכל תבשיל ותבשיל דשבת, טועמי' חיים זכו<sup data-n=\"2991\">70</sup>, וא\"כ צ\"ל עתה הטעימה מהגילוי דבחי' טל תורה שיתגלה לע\"ל, היינו ההבנה וההשגה בפנימיות התורה. ובזה יובן מ\"ש גשם נדבות תניף אלקים גו', שהטל תורה דמ\"ת נק' בשם גשם (נדבות) דוקא, כי התכלית דבחי' טל זה הוא שתהי' בו גם המעלה דגשם, ועד שיומשך בהבנה והשגה כמו בחי' גשם, נגלה דתורה.\nט) <b>וזהו</b> אתה הראת לדעת כי ה' הוא האלקים אין עוד מלבדו, שענין זה ניתן בשעת מ\"ת, ועד\"ז נמשך בכל שנה ושנה בזמן מתן תורתנו, כי בשעת מ\"ת הי' גילוי בחי' טל תורה, בחי' טלא דבדולחא דנטיף מע\"ק, שהוא חד עם עצמות א\"ס ב\"ה, אתה דו עצמות א\"ס ב\"ה. ויש לומר דזהו גם מה שידוע<sup data-n=\"2992\">71</sup> שחג השבועות קשור עם משה רבינו, שקיבל אז התורה מסיני, ודוד המלך והבעש\"ט, דבעצרת הוא יום ההילולא דדוד המלך [וענין זה הוא בהדגשה יתירה בשנה זו, שהרי דוד מת בשבת<sup data-n=\"2993\">72</sup>, ובשנה זו חל יו\"ט שני של עצרת בשבת] וגם יום ההילולא דהבעש\"ט (כנ\"ל). [ויש לומר עוד, דחג השבועות הוא גם יום ההילולא<sup data-n=\"2994\">73</sup> דמשה רבינו. שהרי בשעת מ\"ת פרחה נשמתן של כל ישראל והחזירה בטל כו', ובהכרח לומר שענין זה הי' בכל ישראל, למקטנם ועד גדולם<sup data-n=\"2995\">74</sup>, שהרי בטח נמשך ענין טל תחי' (טל תורה) לכאו\"א מישראל, כולל משה רבינו<sup data-n=\"2996\">75</sup>. ונמצא שביום זה הי' גם עניןיציאת הנשמה (פרחה נשמתן) במשה רבינו, ענין הילולא]. ושלשה אלה (משה רבינו דוד המלך והבעש\"ט) קשורים עם ענין המשכת בחי' טל תורה (פנימיות התורה) בישראל באופן דהבנה והשגה. דבמשה כתיב תורה צוה לנו משה מורשה קהלת יעקב<sup data-n=\"2997\">76</sup>, שנתן ומסר את כל התורה כולה (כולל בחי' טל תורה) לכל ישראל באופן דירושה, דאמיתית ענין הירושה היא כשנמצאת בבעלותו של היורש לגמרי, והיינו שיש בזה הבנה והשגה וכו'. ועד\"ז הי' זה ענינו של דוד, דוד מלכא משיחא, שענינו של משיח הוא גילוי פנימיות התורה דלעתיד. [וענין זה הוא בהדגשה בזמן זה, סמוך למוצאי שבת, זמן סעודתא דדוד מלכא משיחא<sup data-n=\"2998\">77</sup>]. ועד\"ז הוא גם ענינו של הבעש\"ט, שגילה פנימיות התורה באופן דהפצת המעיינות חוצה. דבזמן מתן תורה הי' ענין זה (בחי' טל תורה) בהעלם (לפי ערך), ואח\"כ נתגלה יותר ע\"י דוד, ואח\"כ נתגלה ביותר ע\"י הבעש\"ט ותלמידיו ותלמידי תלמידיו, עד לכ\"ק מו\"ח אדמו\"ר נשיא דורנו, שחידושם הי' הפצת המעיינות דפנימיות התורה (טל תורה) חוצה.\nי) <b>והנה</b> התורה היא נצחית<sup data-n=\"2999\">78</sup>, והיינו שהיא הוראה נצחית לכל ישראל, ואינו מבקש אלא לפי כוחן<sup data-n=\"3000\">79</sup>, שלכל אחד ואחת [שהרי גם לנשים היתה נתינת התורה וקבלת התורה, ואדרבה, כתיב בתחלה<sup data-n=\"3001\">80</sup> כה תאמר לבית יעקב אלו הנשים, ובאופן דאמירה רכה] ניתן הכח שיהי' לימוד בחי' טל שבתורה, ובאופן דהבנה והשגה. וכמו שבכל הלכה שבתורה העיקר הוא המעשה בפשטות, עד\"ז הוא גם בענין זה דגילוי בחי' טל תורה דלע\"ל, שהעיקר הוא שיהי' בפשטות, שמדבר הוי' זו הלכה נבוא לדבר הוי' זה הקץ<sup data-n=\"3002\">81</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו, בעגלא דידן ממש.\n**********",[["2921","*","יצא לאור בשעתו, \"<i>תשלומין דחה\"ש</i>,<i> ה'תשמ\"ו</i>\"."],["2922","1","ואתחנן ד, לה. וראה גם מאמר דחגה\"ש תש\"ד – סה\"מ תש\"ד ע' 220."],["2923","2","מגילה לא, ב ובפרש\"י. זח\"ג רסא, א. ועוד. ובתוד\"ה משה מעצמו אמרם (מגילה שם): וברוח הקודש. וראה לקו\"ש חי\"ט ע' 9. וש\"נ."],["2924","3","פל\"ו. וכפרש\"י עה\"פ. ודלא כדעת המפרשים דקאי על הנפלאות שביצי\"מ – ראה לקו\"ש חכ\"ד ע' 37. וש\"נ."],["2925","4","סה\"מ תש\"ד שם. שם ע' 54. וראה רד\"ה אתה הראת תרפ\"ט. סה\"מ הש\"ת ס\"ע 146."],["2926","5","תש\"ד שם ע' 54."],["2927","6","שבת פח, ב. וראה שמו\"ר פכ\"ט, ד."],["2928","7","תהלים סח, י."],["2929","8","ראה ירושלמי חגיגה פ\"ב ה\"ג – הובא בתוס' חגיגה יז, א. ועוד."],["2930","9","ראה יל\"ש ישעי' עה\"פ כו, יט. וראה כתובות קיא, ב."],["2931","10","כתר שם טוב (הוצאת קה\"ת תשנ\"ט) בהוספות סרכ\"ג ואילך. וש\"נ."],["2932","11","לקו\"ד ח\"א לב, א. ובכ\"מ."],["2933","12","ואתחנן ו, כד."],["2934","13","סקמ\"ה. וראה גם צוואת הריב\"ש סקמ\"ב."],["2935","14","אבות פ\"ב מ\"א."],["2936","15","לקו\"א סקצ\"ח. או\"ת קיב, ב."],["2937","16","ס' השיחות תש\"ד ע' 23. \"היום יום\" יג אייר. ועוד."],["2938","17","חוקת יט, יד. וראה זח\"ב קיז, ריש ע\"ב. ח\"ג כט, ב. ועוד."],["2939","18","ראה משלי ג, ו. אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג."],["2940","19","ראה לקו\"ש ח\"ג ע' 907. 932. ח\"י ע' 104. ח\"כ ע' 331 ואילך. ועוד."],["2941","20","ביאוה\"ז להצ\"צ ח\"ב ע' תרנד ואילך. ועוד."],["2942","21","בס' מאמרי אדמו\"ר האמצעי-במדבר ח\"ב ע' שנב ואילך."],["2943","22","האזינו לב, ב."],["2944","23","אבות רפ\"א."],["2945","24","שמו\"ר פ\"ל, ד. וש\"נ."],["2946","25","וראה בכ\"ז גם לקו\"ת האזינו עג, א ואילך. <i>ובכ\"מ</i>."],["2947","26","בראשית ד, ו."],["2948","27","ישעי' נה, יו\"ד."],["2949","28","תענית ג, א."],["2950","29","ראה בכ\"ז גם לקו\"ת שה\"ש כב, ב ואילך. ובכ\"מ."],["2951","30","ב\"ר פי\"ג, יד. וראה גם המשך תער\"ב ח\"ב ע' א'ע."],["2952","31","ראה לקו\"ת ש\"ש סו, ד. ועוד."],["2953","32","ראה יג, ה. וראה לקו\"ת ראה יט, ד. <i>ובכ\"מ</i>."],["2954","33","ב\"ק סה, א. וש\"נ."],["2955","34","ראה גם ס' השיחות תש\"ב ע' 109."],["2956","35","מגילה ו, ב."],["2957","36","ראה לקו\"ש ח\"ד ע' 1165. חי\"ג ע' 117."],["2958","37","ראה לקו\"ת שה\"ש מא, ד. ובכ\"מ."],["2959","38","ראה סנהדרין צז, סע\"א."],["2960","39","ואתחנן ד, כט."],["2961","40","ראה לב, סע\"א."],["2962","41","זח\"ג קכח, ב. ובכ\"מ."],["2963","42","כי גם בחי' האתעדל\"ע שלמעלה מאתעדל\"ת – \"אינה שורה ומתגלה אלא כשיש שלימות במעשה התחתונים כו'\" (לשון הלקו\"ת שה\"ש שבהערה 29). ובלשון הזהר (ח\"ג צ, ב) \"לא שריא אלא באתר שלים\". ועצ\"ע דהא טל לא מיעצר <i>בימי אלי'</i>."],["2964","43","ראה לקו\"ש ח\"ט ע' 385. ובכ\"מ."],["2965","44","פסחים נ, א. וש\"נ."],["2966","45","ויק\"ר פי\"ג, ג."],["2967","46","ראה בכ\"ז: אגה\"ק סי\"ז. תו\"א יתרו עג, ב. לקו\"ת שלח מו, ד. דרמ\"צ יד, ב ואילך. אוה\"ת סידור ס\"ע שנ ואילך. המשך תער\"ב ח\"ב ע' תשעט ואילך. סה\"מ קונטרסים ח\"ב ע' תיא ואילך. סה\"מ ה'ש\"ת ע' 44 ואילך. לקו\"ש חי\"ז ע' 344 ואילך. ד\"ה להבין ענין תחיית המתים דש\"פ אחרי שנה זו (לעיל ח\"ג ע' רכא ואילך)"],["2968","47","ראה המשך תער\"ב שם. ועוד."],["2969","48","סנהדרין ר\"פ חלק."],["2970","49","כלאים פ\"ט ה\"ג. וראה תשובות וביאורים (קה\"ת, תשל\"ד) סימן ח (אגרות-קודש ח\"א ע' קמב ואילך)."],["2971","50","שער היחוד והאמונה פ\"ז (פב, רע\"א)."],["2972","51","ראה סה\"מ תש\"ח ע' 160. ובכ\"מ."],["2973","52","ראה שער היחוד והאמונה בתחלתו."],["2974","53","המשך תרס\"ו ע' כג. ובכ\"מ."],["2975","54","ראה פרש\"י משפטים כד, יב. ובכ\"מ."],["2976","55","שמו\"ר פ\"ה, ט."],["2977","56","פדר\"א פמ\"א."],["2978","57","תנחומא פקודי ג."],["2979","58","לשון מאמר ד\"ה באתי לגני תש\"י פי\"א. ובכ\"מ."],["2980","59","שבת פח, ב (לפי גירסת הר\"נ גאון)."],["2981","60","בחוקותי כז, ח."],["2982","61","סנהדרין לט, א."],["2983","62","ואתחנן ד, ו."],["2984","63","חגיגה רפ\"ב."],["2985","64","להעיר ממצות המלך (אגה\"ק ר\"ס כט)."],["2986","65","ראה בכ\"ז לקו\"ש חט\"ו ע' 282 ואילך. וש\"נ."],["2987","66","לשון התקו\"ז ת\"ו בסופו."],["2988","67","ראה סה\"מ תש\"י ע' 245. לקו\"ש שם. וש\"נ."],["2989","68","שו\"ע אדה\"ז סר\"נ ס\"ח."],["2990","69","ראה לקו\"ש שם."],["2991","70","נוסח מוסף דשבת."],["2992","71","ראה לקו\"ש ח\"ח ע' 21 ואילך. שם ע' 249 ואילך. ועוד."],["2993","72","שבת ל, א."],["2994","73","שלימותו, ועוד, יום חתונתו זה מ\"ת."],["2995","74","ומש\"כ בחדא\"ג (שבת שבהערה 6) לפענ\"ד צע\"ג."],["2996","75","בתניא רפל\"ד מבואר ד\"מדרגת משה רבינו ע\"ה היא העולה על כולנה שאמרו עליו שכינה מדברת מתוך גרונו של משה, ומעין זה זכו ישראל במעמד הר סיני רק שלא יכלו לסבול, כמאמר רז\"ל שעל כל דבור פרחה נשמתן כו'\", דמזה משמע לכאורה, שאצל משה לא הוצרך להיות \"פרחה נשמתו\" (כמו שלא פרחה נשמתו כששכינה מדברת מתוך גרונו).אבל עכצ\"ל דהגילוי דמ\"ת, \"<i>פנים בפנים</i>\", הוא למעלה מהגילוי ד\"<i>שכינה</i> מדברת כו'\", ובשביל גילוי זה י\"ל (ע\"פ המבואר בפנים, דאאפ\"ל שאצל משה רבינו הי' חסר העילוי דטל תחי') שגם אצל משה פרחה נשמתו. ועצ\"ע. ואכ\"מ*."],["2997","76","ברכה לג, ד."],["2998","77","ראה סידור האריז\"ל סדר מוצאי שבת."],["2999","78","תניא רפי\"ז."],["3000","79","במדב\"ר פי\"ב, ג."],["3001","80","יתרו יט, ג ובפרש\"י."],["3002","81","ראה שבת קלח, ב.\n*) <i>וראה לקו\"ש חכ\"ח ע' 13 הערה 56 ובשוה\"ג</i>. <b>המו\"ל</b>."]]],[1500380052,"<h3>בס\"ד. ש\"פ נשא, י\"ד סיון ה'תשל\"ב<sup data-n=\"3003\">*</sup></h3>\n<b>ביום</b> השני הקריב נתנאל בן צוער נשיא יששכר הקריב את קרבנו גו'<sup data-n=\"3004\">1</sup>, ופרש\"י מהו הקריב הקריב ב' פעמים שבשביל שני דברים זכה להקריב שני לשבטים, אחת שהיו יודעים בתורה שנאמר<sup data-n=\"3005\">2</sup> ומבני יששכר יודעי בינה לעתים ואחת שהם נתנו עצה לנשיאים להתנדב קרבנות הללו, וצריך להבין, דמצד שני טעמים אלו הי' ראוי לכאורה שיקריב ראשון לשבטים. וביותר אינו מובן, דאיתא במדרש<sup data-n=\"3006\">3</sup>, למה נאמר בו הקריב כו' לפי שזכה בעצת נשיאים העלה עליו הכתוב כאילו הוא הקריב תחלה. ועפ\"ז צריך להבין עוד יותר הטעם על זה שבפועל הקריב יהודה תחלה ויששכר הקריב ביום השני. גם צריך להבין מ\"ש נתנאל בן צוער נשיא יששכר, שמקדים את שמו (נתנאל בן צוער) לפני שאומר שהי' נשיא יששכר, דלכאורה, מכיון דזה שהקריב את קרבנו הוא לפי שהי' נשיא יששכר, הי' צריך לומר נשיא יששכר (ואח\"כ) נתנאל בן צוער, וכמ\"ש גבי שאר הנשיאים שהקריבו לאחרי יום השני שבתחלה נאמר נשיא לבני גו' ואח\"כ נאמר שמו של הנשיא<sup data-n=\"3007\">4</sup>. וכן בהנשיא שהקריב ביום הראשון נאמר<sup data-n=\"3008\">5</sup> נחשון בן עמינדב למטה יהודה, בתחלה נחשון בן עמינדב ואח\"כ למטה יהודה<sup data-n=\"3009\">6</sup>.\nב) <b>ויש</b> לבאר ע\"פ מה שאיתא במדרש<sup data-n=\"3010\">7</sup> עה\"פ נחשון בן עמינדב למטה יהודה, למה נקרא שמו נחשון על שם שירד תחלה לנחשול שבים כו' מי שקידש את שמי בים הוא יקריב תחלה. ויש לומר, דזה שמדייק במדרש למה נקרא שמו נחשון (שאינו מדייק כן בשאר הנשיאים), הוא, כי מלשון הכתוב נחשון בן עמינדב למטה יהודה (ולא נשיא יהודה) משמע דזה שהוא הי' המקריב ביום הראשון הוא (לא רק מפני המעלה דשבט יהודה, אלא גם) מצד מעלת עצמו<sup data-n=\"3011\">8</sup>, וכיון ששמו של אדם רומז על ענינו<sup data-n=\"3012\">9</sup> (ומעלתו), לכן מדייק למה נקרא שמו נחשון. ומבאר דמעלתו של נחשון (המרומזת בשמו) היא שקידש את שמי (של הקב\"ה) ולכן הקריב תחלה. ויש לומר עד\"ז בנוגע נתנאל בן צוער נשיא יששכר, שהכתוב מקדים נתנאל בן צוער לפני נשיא יששכר, הוא, לרמז, דזה שהקריב ביום השני (מיד לאחרי יהודה), ויתירהמזה שהעלה עליו הכתוב כאילו הוא הקריב תחלה (לפני יהודה), הוא מפני המעלה שבו המרומזת בשמו. והגם שנאמר בו נשיא יששכר [דלא כנחשון שנאמר בו למטה יהודה] שמזה מוכח דזה שהקריב ביום השני [וגם זה שהעלה עליו הכתוב כאילו הוא הקריב תחלה] הוא מצד המעלה דשבט יששכר, מ\"מ נאמר נתנאל בן צוער לפני נשיא יששכר, כי מעלה זו דשבט יששכר [שבשבילה הקריב ביום השני וכאילו הוא הקריב תחלה] מרומזת בהשם נתנאל בן צוער.\n<b>ומבואר</b> בהדרושים<sup data-n=\"3013\">10</sup>, דהשייכות של נחשון ונתנאל ליהודה ויששכר הוא, כי יהודה הו\"ע הביטול [שלכן נקרא בשם יהודה על שם הפעם <i>אודה</i> את ה'<sup data-n=\"3014\">11</sup>], ולכן הנשיא דשבט יהודה הי' נחשון שירד תחלה לנחשול שבים, ענין המס\"נ ביטול. ויששכר הו\"ע התורה (כנ\"ל). ולכן הנשיא דיששכר הי' נתנאל<sup data-n=\"3015\">12</sup>, אותיות נתן א-ל, כי התורה היא מתנה. וענין בן צוער, צוער מלשון מצער, הוא, כי הכלי לתורה הוא ביטול. וזהו שיהודה הקריב לפני יששכר, כי ענין הביטול<sup data-n=\"3016\">13</sup> הוא לפני (ולמעלה מ)עסק התורה. דשורש התורה הוא בחכמה, דאורייתא מחכמה נפקת<sup data-n=\"3017\">14</sup>, וע\"י הביטול הוא המשכת הכתר שלמעלה מחכמה. וצריך להבין, דע\"פ המבואר בהדרושים שיהודה הוא בכתר ויששכר בחכמה, למה העלה הכתוב על יששכר כאילו הוא הקריב תחלה (תחלה גם ליהודה).\nג) <b>והנה</b> ידוע דיהודה הו\"ע המעשה (כמ\"ש בהדרושים המבארים ענין הגשת יהודה ויוסף<sup data-n=\"3018\">15</sup>), ועפ\"ז, יששכר ויהודה הו\"ע תלמוד ומעשה. ומבואר במק\"א<sup data-n=\"3019\">16</sup> דהגם שנמנו וגמרו שתלמוד גדול<sup data-n=\"3020\">17</sup>, מ\"מ, מכיון שהטעם על זה שתלמוד גדול הוא לפי שתלמוד מביא לידי מעשה<sup data-n=\"3020\">17</sup>, הרי מזה עצמו מוכח שהמעשה הוא העיקר [כי שורש המעשה הוא למעלה משורש התלמוד ולכן לע\"ל יהי' מעשה גדול<sup data-n=\"3021\">18</sup>]. ועפ\"ז יש לומר, דזה שנשיא יששכר העלה עליו הכתוב כאילו הוא הקריב תחלה (תחלה גם ליהודה) הוא ע\"ד תלמוד גדול, וזה שבפועל הקריב יהודה תחלה הוא לפי שהמעשה הוא העיקר. ולהוסיף, דהקמת המשכן ומתן תורה שייכים זל\"ז. וכמובן ממדרשי חז\"ל<sup data-n=\"3022\">19</sup> עה\"פ<sup data-n=\"3023\">20</sup> באתי לגני, שהמשכת וירידת עיקר שכינה למטה בארץהותחלה בשעת מתן תורה, ועיקר ההמשכה הי' כשהוקם המשכן. ועפ\"ז יש לומר, דכמו שמתן תורה הי' ע\"י שהקדימו נעשה לנשמע, הדגשת מעלת המעשה על הלימוד וההבנה<sup data-n=\"3024\">21</sup> (נשמע מלשון הבנה<sup data-n=\"3025\">22</sup>) ובאופן <i>שהקדימו</i> נעשה לנשמע [דלאחרי מתן תורה, הגם שהמעשה הוא העיקר<sup data-n=\"3026\">23</sup> והטעם שתלמוד גדול הוא מפני שמביא לידי מעשה מ\"מ תלמוד גדול, ולימוד קודם למעשה. אבל בכדי שתהי' ההמשכה דמתן תורה הי' צריך להיות ההכנה דהקדמת נעשה לנשמע], עד\"ז הוא בנוגע לההמשכה שהיתה בהקמת המשכן. ולכן, בחנוכת המשכן הקריב יהודה (מעשה) לפני יששכר (תלמוד).\nד) <b>וצריך</b> להבין, דכיון שגם זה שתלמוד גדול הוא מפני שמביא למעשה והמעשה הוא העיקר, מהו החילוק בין שני הענינים, שבדרך כלל התלמוד הוא קודם למעשה [קודם בזמן, וגם קודם במעלה, תלמוד גדול], ובמתן תורה וכן בחנוכת המשכן הי' מעשה קודם. ונקודת הביאור בזה, דזה שהמעשה הוא העיקר [אף שמעשה הוא כח היותר אחרון, ועד\"ז למעלה המעשה הוא סוף ההשתלשלות], הוא כי נעוץ תחלתן בסופן וסופן בתחלתן<sup data-n=\"3027\">24</sup>, וגם כי סוף<sup data-n=\"3028\">25</sup> מעשה במחשבה תחלה<sup data-n=\"3029\">26</sup>. ומבאר אדמו\"ר (מהורש\"ב) נ\"ע בהמשך תער\"ב<sup data-n=\"3030\">27</sup>, החילוק דשני הענינים, דסופן הוא גמר סיום ההמשכה. ובחינה זו נעוצה בתחלתן תחלת וראשית ההמשכה. וכמובא שם משל לזה מהשפעת צדקה לעני, שהתחילה (של ההשפעה) הוא שמתעורר ברחמים על העני, ומזה נעשה אצלו אח\"כ רצון להטיב להעני [דהרחמים הם הטעם דהרצון<sup data-n=\"3031\">28</sup>], ואח\"כ נמשך הרצון בשכל ובמדות וכו' עד שבא במעשה בפועל, שנותן צדקה להעני. וענין נעוץ סופן בתחלתן הוא, שעיקר המכוון בהתעוררות הרחמים (תחלתן) הוא שתהי' ההשפעה בפועל (סופן). ובאם לא תהי' ההשפעה בפועל [הגם שע\"י הרחמים נעשה ההתעוררות דכל כחות הנעלים שבו, רצון שכל ומדות, ואפילו כשהרצון שלו להטיב להעני מתגלה בדיבור (שמדבר דברי פיוס להעני<sup data-n=\"3032\">29</sup>) אבל לא בא במעשה בפועל], חסר העיקר. ולפי שנעוץ סופן בתחלתן, שהכוונה (הנעוצה) בהתעוררות הרחמים (תחלתן) הוא שיהי' המעשה בפועל (סופן), לכן נעוץ תחלתן בסופן, שגילוי הכח דבחינת תחלה הוא<sup data-n=\"3033\">30</sup> דוקא בסוף ההשפעה, בהמעשה בפועל. וענין סוף מעשה במחשבה תחלה הוא למעלה מענין נעוץ תחלתן בסופן וסופןבתחלתן. דפירוש סוף מעשה הוא (לא סוף העשי' עצמה, עשיית האדם, אלא) המעשה הבאה ע\"י עשיית ופעולת האדם. דבהשפעת החסד, ענין סוף מעשה הוא <i>קבלת</i> ההשפעה, שהעני מקבל את ההשפעה בטוב ונהנה מזה. דענין זה (באיזה אופן מקבל העני את ההשפעה) אינו תלוי בהנותן אלא בהמקבל. וזה מגיע במחשבה תחלה, היינו בהתחילה שלפני תחלת המחשבה, למעלה משורש ההשפעה. דשורש ההשפעה (ההתעוררות להטיב) הוא תחלת המחשבה, וגילוי ענין זה הוא בסוף <i>ההשפעה</i> – נעוץ תחלתן בסופן, והמעלה דסוף מעשה (<i>קבלת</i> ההשפעה) היא שסוף מעשה מגיע בהתחילה שלפני תחלת המחשבה, למעלה משורש ההשפעה. ולכן התענוג שיש להמשפיע מקבלת ההשפעה (מזה שהעני קיבל ההשפעה בטוב) הוא תענוג גדול יותר מהתענוג שבההשפעה עצמה.\n<b>וכמו</b><sup data-n=\"3034\">31</sup> שהוא בענין ההשפעה עד\"ז הוא בכל עשי', דסופן הוא העשי' עצמה, עשיית ופעולת האדם, ונקראת בשם סופן, כי כח המעשה הוא כח היותר אחרון, וגם פעולת המעשה באה בסוף. דבתחילה הוא התענוג, ומזה נמשכים הרצון והשכל והמדות, והמדות מתלבשים במחשבה ודיבור, ולאח\"ז באה המעשה<sup data-n=\"3035\">32</sup>. ונעוץ סופן בתחלתן ותחלתן בסופן, דשורש המעשה הוא בהתענוג, שהוא ה\"תחילה\", סיבת הרצון ושאר הכחות. וכן נעוץ תחלתן בסופן, שגילוי התענוג הוא בהמעשה דוקא. וסוף מעשה הוא (לא העשי' עצמה, אלא) המעשה שנעשתה ע\"י עשיית ופעולת האדם. ועיקר ענין סוף מעשה הוא בהמעשה הבאה ע\"י עשייתו שאינה תלוי' ברצון האדם. וכמו אומן העושה מלאכה, דזה שהאומן אינו יכול לקבל על עצמו שהמלאכה תהי' בהצלחה [דענין זה אינו תלוי בהאומן. וע\"ד המבואר לעיל בענין קבלת ההשפעה, שזה תלוי בהמקבל ולא בהנותן]. וסוף מעשה במחשבה תחלה, שהתענוג של האומן מזה שהמלאכה נעשתה בתכלית ההידור והיופי (באופן דהצלחה) הוא תענוג נעלה יותר מהתענוג שבעשיית המלאכה. דהתענוג שנעשית המלאכה הוא תענוג המורכב (תענוג מעשיית המלאכה), וע\"י שרואה שהמלאכה נעשתה בהידור וביופי, מתגלה תענוג הפשוט (כמבואר בהמשך הנ\"ל).\nה) <b>והנה</b> ידוע<sup data-n=\"3036\">33</sup> שמעלת האדם מתחילה מכח הדיבור שבו<sup data-n=\"3037\">34</sup> (משא\"כ מעשה ישנו גם בבע\"ח). ועפ\"ז יש לומר, דשני הענינים שבמעשה – עשיית ופעולת האדם (סופן), והמעשה הבאה ע\"י העשי' שלו (סוף מעשה) – יש (דוגמתם) גם בהעשי' דהאדם. דזה שהכחות דהאדם (שכל ומדות מחשבה ודיבור) נמשכים ומתלבשים בהמעשה, הוא ע\"ד עשיית ופעולת <i>האדם</i>, והמעשה עצמה (כמו שהיא נבדלת מהכחות שלמעלה ממנה, שהם עיקר האדם) הוא <i>ע\"ד</i> המעשה (שמחוץ להאדם) שנעשה ע\"י עשיית ופעולת האדם. והחילוק דשני הענינים בשרשם בנפש הוא, דשורש המעשה ששייך להכחות שלמעלה ממנו (היינו ההתלבשות דהכחות בהמעשה)הוא בבחינת הגילוי דהנפש. והיינו<sup data-n=\"3038\">35</sup>, שגם השורש דענין זה שבמעשה הוא בהנפש שלמעלה מהכחות. כי הכחות מצד עצמם הם מובדלים ואין ביכלתם לירד למטה כ\"כ ולהתלבש במעשה, וזה שאפשר להם לירד ולהתלבש במעשה הוא ע\"י שנמשך בהם מהנפש (שלמעלה מהכחות), שהיא נמצאת בכל הכחות והאיברים בשוה. אבל ענין זה שבנפש (שביכלתה לירד למטה מטה) הוא בחינת הגילוי שלה – ע\"ד נעוץ סופן בתחלתן, שהשורש דסופן (עשיית <i>האדם</i>) הוא בה\"תחילה\", שורש ההשפעה. והשורש דהמעשה עצמו (כמו שהוא נבדל מהכחות שלמעלה ממנו) הוא בעצם הנפש<sup data-n=\"3038\">35</sup> – ע\"ד סוף מעשה במחשבה תחלה, שהשורש דסוף מעשה (שמחוץ להאדם) הוא בהתחילה שלפני תחלת המחשבה, למעלה משורש ההשפעה.\n<b>ויש</b> לומר, דבמעלת המעשה בזה שעל ידה מתגלה הבל\"ג דהנפש שלמעלה מהכחות – השכל והמדות וכו' הם לפני [ולמעלה מ]המעשה. דכיון שגילוי הבל\"ג דהנפש הוא <i>שהשכל והמדות</i> נמשכים ומתלבשים בהמעשה, הרי השכל והמדות קודמים להמעשה. וגם <i>למעלה</i> מהמעשה. שהרי המעלה דמעשה (בבחינה זו) היא לא בהמעשה עצמו אלא בזה <i>שהשכל והמדות</i> מתלבשים בהמעשה [ועפ\"ז יש לבאר מה שאמרו תלמוד גדול שמביא לידי מעשה (דלכאורה, מזה עצמו שהגדלות דתלמוד הוא שמביא למעשה מוכח שהמעשה הוא העיקר, ואעפ\"כ תלמוד גדול ממעשה), כי היתרון דמעשה לגבי תלמוד בדרגא זו היא <i>שהתלמוד</i> מביא למעשה (דזה שהתלמוד מביא לידי מעשה הוא ע\"י שנמשך בו ענין הבל\"ג שלמעלה מהתלמוד עצמו), ולכן תלמוד גדול]. ובמעלת המעשה מצד זה ששורש המעשה עצמו הוא בעצם הנפש – המעשה הוא (לפני ולמעלה מ)כל הכחות, וזהו שלפני מתן תורה הקדימו נעשה לנשמע, ועד\"ז בחנוכת המשכן הקריב יהודה (מעשה) לפני יששכר (תלמוד), כי במתן תורה ובהקמת המשכן היתה המשכת העצמות, ושם – המעשה קודם לתלמוד.\nו) <b>ויש</b> לקשר ביאור זה [דזה שיהודה הקריב הראשון הוא מצד מעלת המעשה] עם הביאור (הובא לעיל סעיף ב) דזה שיהודה הקריב ראשון הוא כי יהודה הוא בחינת ביטול, כי ענין הביטול הוא במעשה. דהכחות שלמעלה ממעשה, כיון שענינם הוא מעלה ושלימות, וכנ\"ל (סעיף ה) שהתחלת מעלת האדם הוא כח הדיבור שבו, הביטול שלהם להנפש אינו ביטול בתכלית, ודוקא כח המעשה שאינו ממעלת האדם, הביטול שלו להנפש הוא ביטול בתכלית<sup data-n=\"3039\">36</sup> [ובמעשה עצמו, עיקר הביטול הוא בהדרגא דמעשה כמו שהוא מובדל מהכחות שלמעלה ממנו. דבדרגת המעשה שבו מתלבשים הכחות שלמעלה ממנו, יש בו העילוי שעל ידו נתגלה הבל\"ג דהנפש, ולכן הוא \"מציאות\". ועיקר הביטול הוא בהמעשה עצמו (שנבדל מהכחות שלמעלה ממנו), דכיון שאין בו עילוי, לכן נרגש בו שכל מציאותו הוא רק מצד הנפש].\n<b>ויש</b> לקשר זה עם זה ששורש המעשה הוא בעצם הנפש, דבעצם הנפש אין נתינת מקום למציאות שמחוץ להנפש. ומזה מובן, דזה ששורש המעשה הוא בעצםהנפש הוא לפי שכל מציאותו היא רק מצד עצם הנפש<sup data-n=\"3040\">37</sup>. ועד\"ז הוא למעלה (בהחילוק בין תורה ומצוות), דזה שהרצון דמצוות הוא במעשה המצוות (ובדברים גשמיים), אף שהמעשה אין לו ערך, הוא לפי ששורש המצוות הוא בהעצמות<sup data-n=\"3041\">38</sup>, ולכן, עיקר הביטול הוא במעשה המצוות. ויש לומר, שגם הרצון בכוונת המצוות, הוא לא מצד המעלה שבכוונת המצוות אלא מפני שכן עלה ברצונו ית'. אלא שגילוי ענין זה הוא במעשה המצוות, ועי\"ז מתגלה שכן הוא גם בכוונת המצוות. ועד\"ז הוא בתורה, דהגם שהתורה היא חכמה [וגם למעלה, התורה היא חכמתו של הקב\"ה], זה שאורייתא וקוב\"ה כולא חד הוא לא מצד <i>מעלת</i> התורה אלא לפי שכן עלה ברצונו ית'. אלא שגילוי ענין זה הוא במצוות וע\"י המצוות מתגלה שכן הוא גם בתורה.\nז) <b>וזהו</b> ביום השני הקריב נתנאל בן צוער לשון מצער, דלאחרי הביטול דיהודה בענין המצוות המשיך נתנאל בן צוער ביטול זה גם בעסק התורה. ולכן העלה עליו הכתוב כאילו הוא הקריב תחלה [אף שיהודה הוא למעלה מיששכר, וכנ\"ל (סעיף ב) שיהודה הוא בכתר ויששכר הוא בחכמה], דענין הקריב תחלה הוא שהמשיך הביטול דכתר (בחינת תחלה) בחכמה. ויש לומר דבהלשון כאילו הקריב תחלה (ולא כאילו הקריב ביום הראשון) מרומז גם הביטול שמצד בחינת תחלה – תחלה שלפני תחלת המחשבה, שבו עלה סוף מעשה (מעשה המצוות) ונתנאל המשיך ביטול זה גם בתורה [גם יש לומר דפירוש כאילו הקריב תחלה הוא תחלה לפני יהודה. כי המשכת הביטול בתורה הוא חידוש גדול יותר ובמילא נעלה יותר מהביטול שבמעשה המצוות]. וע\"י הביטול דצוער שהי' בו נעשה נתנאל<sup data-n=\"3042\">39</sup>, אותיות נתן א-ל, שניתנה לו התורה במתנה.\n**********",[["3003","*","יצא לאור ב<b>קונטרס ב' ניסן – תנש\"א</b>, \"לקראת ב' ניסן, יום הסתלקות הילולא של כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע . . <i>ער\"ח ניסן</i>,<i> שנת ה'תנש\"א</i>\"."],["3004","1","נשא ז, יח-יט."],["3005","2","דברי הימים-א יב, לג."],["3006","3","במדב\"ר פי\"ג, טו-טז."],["3007","4","וכמו שמדייק באוה\"ח כאן."],["3008","5","נשא ז, יב."],["3009","6","ראה במדב\"ר פי\"ג, יז \"למה בכל הנשיאים מזכיר שבטם ואח\"כ מזכיר שמותם וביהודה ויששכר מזכיר שם נשיאיהם תחלה ואח\"כ מזכיר שמותן\"."],["3010","7","במדב\"ר פי\"ג, ז."],["3011","8","אוה\"ח עה\"פ ז, יב."],["3012","9","ראה יומא פג, ב. ר' מאיר הוה דייק בשמא. וראה בארוכה תשובות וביאורים (קה\"ת תשל\"ד) סימן א (נדפס באגרות-קודש ח\"א ס\"ע רפח ואילך)."],["3013","10","אוה\"ת נשא ע' רפ וע' רפב. שם ח\"ה ע' א'תקפ."],["3014","11","ויצא כט, לה."],["3015","12","ראה גם סה\"מ תרכ\"ט ע' ריג. עטר\"ת ע' תעב. תרפ\"ה ע' רכא. ה'ש\"ת ע' 111."],["3016","13","ואף שגם נתנאל בן צוער הוא מלשון מצער – יש לומר, שהביטול דמצער אינו כהביטול דמס\"נ. וראה לקמן סעיף ז."],["3017","14","זהר ח\"ב סב, א. פה, א. ח\"ג קפב, א."],["3018","15","ראה אוה\"ת ר\"פ ויגש. ד\"ה ויגש תרע\"ח. ובכ\"מ."],["3019","16","ראה לעיל ח\"ב ע' קצה. ע' ריז. <i>וש\"נ</i>."],["3020","17","קידושין מ, ב."],["3021","18","נסמן לעיל ח\"ב ע' קצה הערה 23."],["3022","19","ראה תנחומא נשא טז \"עמד משה והורידה לארץ שנאמר וירד ה' על הר סיני\". וכ\"ה במתנות כהונה לב\"ר פי\"ט, ז. ובשהש\"ר עה\"פ באתי לגני \"ואימת שרתה שכינה עלי' (בארץ) ביום שהוקם המשכן\". וראה לעיל ח\"ב ע' תלג."],["3023","20","שה\"ש ה, א."],["3024","21","ראה אוה\"ת ראה ע' תרסח. מגלת אסתר ע' קס."],["3025","22","ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרעז. אוה\"ת עקב ע' תעט. ובכ\"מ."],["3026","23","אבות פ\"א מי\"ז. תקו\"ז תנ\"ב (פז, סע\"א). ת\"ס (צג, ב). ת\"ע (קלג, ב. קלד, א)."],["3027","24","ספר יצירה פ\"א מ\"ז."],["3028","25","פיוט \"לכה דודי\"."],["3029","26","ראה תו\"א מקץ לב, סע\"ד שמבאר שם מעלת המצוות \"שנשתלשלו למטה בעשי' גשמית\", ומביא שם ב' הלשונות \"סוף מעשה במחשבה תחלה\" ו\"נעוץ תחלתן בסופן\"."],["3030","27","ח\"ב ע' א'קיז ואילך. וראה גם תו\"ח ויגש פט, סע\"א ואילך. ד\"ה השם נפשינו בחיים תשכ\"ד."],["3031","28","כ\"ה בהמשך תער\"ב שם ע' א'קיח."],["3032","29","דמה שארז\"ל (ב\"ב ט, ב) הנותן פרוטה לעני מתברך בשש ברכות והמפייסו בדברים מתברך בי\"א ברכות \"הוא דוקא כאשר יש המעשה בפועל ממש . . אז יש יתרון בהפיוס\" (המשך תער\"ב שם)."],["3033","30","כ\"ה בהמשך תרס\"ו ע' שמג. וראה גם המשך תער\"ב שם (ע' א'קיט) דזהו הטעם על זה שבמלכות דוקא יש כח הא\"ס להוות מאין ליש."],["3034","31","בהבא לקמן – ראה המשך תער\"ב שם א'קכ. א'קכג-ד."],["3035","32","ראה שעהיוה\"א פרק ח (פה, ב). ובכ\"מ."],["3036","33","סה\"מ ה'תש\"ב ס\"ע 102 ואילך."],["3037","34","ובסה\"מ ה'תש\"ב שם, שלכן נקרא האדם בשם \"מדבר\"."],["3038","35","ראה גם לעיל ח\"ב ע' קצה."],["3039","36","וע\"ד הידוע שביטול היש הוא ביטול גדול יותר מביטול האור (סה\"מ תרפ\"א ע' קכא. ובכ\"מ)."],["3040","37","להעיר מתו\"א ויגש מא, סע\"ד, דהביטול שיש דוקא בארץ [שהיא מדרס תחת כפות רגלי הכל] הוא מפני שבשרשה במחשבה ארץ קדמה לשמים."],["3041","38","ראה המשך תרס\"ו ס\"ע נה."],["3042","39","וזהו \"נתנאל <i>בן</i> צוער\", ד\"נתנאל\" נולד (ונמשך) מ\"צוער\"."]]],[1500380053,"<h3>בס\"ד. ש\"פ בהעלותך, ט' סיון ה'תשכ\"ז<sup data-n=\"3043\">*</sup></h3>\n<b>רני</b> ושמחי בת ציון גו'<sup data-n=\"3044\">1</sup>, ומדייק אדמו\"ר הזקן בתו\"א (דרושי חנוכה) ד\"ה זה<sup data-n=\"3045\">2</sup>, דלכאורה הי' צריך להתחיל ההפטורה דשבת חנוכה בפסוק<sup data-n=\"3046\">3</sup> ויאמר אלי גו' ראיתי והנה מנורת זהב גו', ולמה מתחילין ברני ושמחי בת ציון. ומבאר שם<sup data-n=\"3047\">4</sup>, שהשייכות דרני ושמחי בת ציון לחנוכה היא, כי בת ציון קאי על כנסת ישראל בזמן הגלות, דבזמן הבית נקראת כנסת ישראל בשם ציון ובזמן הגלות נקראת בת ציון, כמבואר שם בארוכה.\n<b>וצריך</b> להבין, דדיוק הנ\"ל [שהתחלת ההפטורה היא רני ושמחי בת ציון ולא ראיתי והנה מנורת זהב] הוא גם בההפטורה דשבת פרשת בהעלותך, שבסמיכות לזמן מתן תורתינו, דמתן תורה הו\"ע חירות<sup data-n=\"3048\">5</sup>, ואעפ\"כ גם התחלת ההפטורה דש\"פ בהעלותך היא רני ושמחי <i>בת</i> ציון.\nב) <b>והנה</b> בתו\"א שם בד\"ה רני ושמחי הראשון<sup data-n=\"3049\">6</sup> מקשר הפסוק רני ושמחי בת ציון עם מאמר המדרש<sup data-n=\"3050\">7</sup> (עה\"פ<sup data-n=\"3051\">8</sup> צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו), משל למלך כו' לא זז מחבבה<sup data-n=\"3052\">9</sup> עד שקראה בתי כו' לא זז מחבבה עד שקראה אחותי כו' לא זז מחבבה עד שקראה אמי. ומבאר שם<sup data-n=\"3053\">10</sup>, דג' ענינים אלה (בתי אחותי אמי) בעבודת האדם הם קיום המצוות<sup data-n=\"3054\">11</sup> עסק התורה והעבודה דמסירת נפש. דבקיום המצוות האדם המקיים את המצוה הוא בחי' מקבל (בת), שהוא מקבלאת ההמשכה שנמשכת ע\"י קיום המצוה. וע\"י עסק התורה נעשים ישראל אחים ורעים להקב\"ה (אחותי). וע\"י העבודה דמס\"נ נק' בשם אמי, שהם משפיעים כביכול בהקב\"ה. ויש לקשר זה עם המבואר בכ\"מ<sup data-n=\"3055\">12</sup> עה\"פ בעטרה שעטרה לו אמו, דהעטרה שעטרה כנס\"י (אמו) להקב\"ה הוא ע\"י שהקדימו נעשה לנשמע, כי הביטול דהקדמת נעשה לנשמע הוא כהביטול דמס\"נ<sup data-n=\"3056\">13</sup>.\n<b>ויש</b> לומר, דמהטעמים שקוראין פרשת בהעלותך את הנרות לאחרי חג השבועות<sup data-n=\"3057\">14</sup> הוא, כי נרות קאי על נשמות ישראל כמ\"ש<sup data-n=\"3058\">15</sup> נר הוי' נשמת אדם<sup data-n=\"3059\">16</sup>, דפירוש נר הוי' הוא שהנשמה מאירה (משפעת) כביכול להוי'<sup data-n=\"3060\">17</sup>, וכדאיתא במדרש<sup data-n=\"3061\">18</sup> עה\"פ בהעלותך את הנרות שישראל מאירין למי שמאיר לכל העולם, וענין זה שייך לחג השבועות, עטרה שעטרה לו אמו. ועפ\"ז צריך להבין עוד יותר מה שההפטורה דש\"פ בהעלותך את הנרות (ענין אמי) הוא רני ושמחי <i>בת</i> ציון.\nג) <b>והענין</b> הוא, שההמשכה שע\"י קיום המצוות, בתי, היא המשכה נעלית יותר מההמשכה שע\"י העבודה דאחותי ואמי. כי העבודה דמסירת נפש (אמי), ועד\"ז עסק התורה (אחותי), מכיון שהיא עבודה רוחנית, יש לה שייכות לההמשכה שנמשכת על ידה, וכיון שההמשכה שע\"י העבודה דאחותי ואמי היא כמו אתערותא דלעילא שמתעוררת ונמשכת על ידי אתערותא דלתתא, ההמשכה היא רק ממקום שאתעדל\"ת מגעת לשם. וההמשכה שע\"י מעשה המצוות, שעשיית המצוה היא עשי' גשמית שאינה בערך כלל<sup data-n=\"3062\">19</sup>, היא כמו אתעדל\"ע שמצד עצמה, ולכן ההמשכה היא מעצמות אוא\"ס<sup data-n=\"3063\">20</sup>. וזהו רני ושמחי בת ציון כי הנני בא ושכנתי בתוכך, שהנני בא כולל שני ענינים. הנני מוכן מעצמי שלא ע\"י אתעדל\"ת<sup data-n=\"3064\">21</sup>, בא, אני בעצמי כביכול אוא\"ס ב\"ה ממש<sup data-n=\"3065\">22</sup>.<b>ויש</b> להוסיף, שהמעלה דהעבודה דבתי על העבודה דאחותי ואמי היא גם בנוגע להאדם העובד. שבהעבודה דאחותי ואמי נרגש בדקות מציאותו של האדם העובד, גודל העילוי דהעבודה <i>שלו</i> [העילוי דהעבודה עצמה (העבודה דעסק התורה, ומכש\"כ העבודה דמס\"נ), והעילוי שנעשה ע\"י עבודתו, שנעשה אח להקב\"ה ויתירה מזו שמשפיע כביכול בהקב\"ה], ובהעבודה דבתי (קיום המצוות) נרגש הביטול שלו<sup data-n=\"3066\">23</sup>, הן בנוגע להעבודה עצמה, שכל עבודתו היא רק לקיים ציווי הקב\"ה, והן בנוגע לההמשכה שע\"י עבודתו, דזה שע\"י קיום המצוות נמשך עצמות אוא\"ס הוא לא מצד ענינו של האדם המקיים את המצוות אלא מפני שהמצוות הם רצון וציווי העצמות. ויש לומר, דע\"י הביטול הוא נעשה כלי להאור שנמשך ע\"י המצוות. וזהו כי הנני בא ושכנתי בתוכך, שההמשכה דהנני בא, אני בעצמי כביכול, היא <i>בתוכך</i>, בפנימיות.\nד) <b>וצריך</b> להבין, דכיון שאמי היא העבודה דמס\"נ, דמס\"נ הו\"ע הביטול, ובפרט לפי המובא לעיל (סעיף ב) דהעטרה שעטרה כנס\"י (אמו) להקב\"ה הוא ע\"י שהקדימו נעשה לנשמע, שהביטול דהקדמת נעשה לנשמע הוא הביטול לבעל הרצון<sup data-n=\"3067\">24</sup>, מהי המעלה בהביטול דבתי על הביטול דאמי. ויש לומר בזה, שהביטול דהקדמת נעשה לנשמע, הוא <i>שישראל</i> קיבלו עליהם עול מלכות שמים. ולכן, אף שהביטול דקבלת עול מלכות שמים הוא (לא רק בנוגע לכח המעשה שלו, שיעשה כל מה שיצטווה, אלא גם) בעצם מציאותו<sup data-n=\"3068\">25</sup>, שכל מציאותו הוא זה שהוא עבדו של המלך, מלך מלכי המלכים הקב\"ה, מ\"מ, כיון שהקבלת עול מלכות שמים באה מצד האדם, <i>שהוא</i> קיבל עליו להיות עבדו של המלך, הרי בביטול זה מעורבת גם מציאותו של האדם [ועד\"ז הוא בנוגע להמס\"נ דבחי' אמי, שהמס\"נ היא מצד טבע הנשמה<sup data-n=\"3069\">26</sup>]. ואמיתית הביטול הוא כשהביטול הוא מצד האדון.\n<b>ויש</b> לומר, דזהו מ\"ש<sup data-n=\"3070\">27</sup> כי לי בני ישראל עבדים עבדי הם אשר הוצאתי אותם מארץ מצרים, דזה שישראל הם עבדים של הקב\"ה הוא (לא רק מפני <i>שהם</i> קיבלו עול מלכותו ית', אלא גם) מפני <i>שהקב\"ה</i> הוציא אותם מארץ מצרים, שעי\"ז הם <i>מוכרחים</i> להיות עבדים<sup data-n=\"3071\">28</sup>. וענין זה נמשך בעיקר בשעת מתן תורה<sup data-n=\"3072\">29</sup>.ה) <b>ועפ\"ז</b> יש לבאר מעלת הביטול דבתי על הביטול דאמי [אף שהביטול דבתי (עול מצוות) הוא בנוגע לכח המעשה, לעשות מה שנצטווה, והביטול דאמי (הקדמת נעשה לנשמע, עול מלכות שמים) הוא בעצם מציאותו (כנ\"ל סעיף ד)], כי העול דישראל לקיים את המצוות שניתנו במתן תורה הוא מפני שבמתן תורה עשה <i>הקב\"ה</i> אותם לעבדים, אמיתית הביטול. ויש לומר, דזה שמבואר בכ\"מ<sup data-n=\"3073\">30</sup> דבת הוא בחינת מקבל, דלית לי' מגרמי' כלום והוא רק מקבל מה שנותנים לו מלמעלה, הכוונה בזה היא, שגם הביטול דקבלת עול הוא לא משל עצמו אלא שבמתן תורה בחר הקב\"ה בישראל להיות לו עבדים.\n[<b>ויש</b> לקשר זה עם המובא לעיל (בתחלת המאמר) מתו\"א דבת ציון קאי על כנס\"י בזמן הגלות, כי הביטול דבת מתגלה בעיקר בהעבודה שבזמן הגלות. וכמבואר במק\"א<sup data-n=\"3074\">31</sup>, דבזמן הגלות, ובפרט בדרא דעקבתא דמשיחא, ההעלמות וההסתרים הם גדולים במאד, וישנם העלמות והסתרים שהאדם מצד עצמו (גם ע\"י הקבלת עול שלו שמקבל ברצונו), כיון שהוא מוגבל, אין ביכלתו להתגבר עליהם, וזה שישראל מתגברים גם על העלמות והסתרים אלה הוא לפי שהביטול דקבלת עול שלהם הוא (לא מצד המציאות שלהם אלא) מצד האלקות, מפני שהקב\"ה בחר בהם להיות לו לעבדים, ולגבי האלקות אין הגבלות<sup data-n=\"3075\">32</sup>].\n<b>וזהו</b> שההפטורה דש\"פ בהעלותך שלאחרי זמן מתן תורתינו היא רני ושמחי <i>בת</i> ציון, אף שהענין והמעלה דיום חתונתו&lt;8&gt; זה מתן תורה<sup data-n=\"3076\">33</sup> הוא (עטרה שעטרה לו) אמו, כי תכלית הכוונה בהביטול דאמי שבחג השבועות הוא שעי\"ז יגיעו אח\"כ לביטול נעלה יותר, ביטול דבתי, בת ציון.\nו) <b>ומדייק</b> הכתוב רני ושמחי בת ציון, שקיום התומ\"צ (ציון<sup data-n=\"3077\">34</sup>) צ\"ל לא רק בביטול, בת, אלא גם בשמחה, רני ושמחי. וצריך להבין, דכאשר האדם הוא במצב שאין לו תענוג וחיות בתומ\"צ, וקיום התומ\"צ שלו הוא רק בדרך קבלת עול [ויתירה מזו, שגם הקב\"ע שלו היא לא באופן שרוצה לקבל עליועומ\"ש ורק שאינו יכול לפרוק ממנו עול מלכות שמים מפני שבחירת הקב\"ה בישראל להיות לו לעבדים <i>מכריחה</i> אותו], איך יכול לפעול בעצמו שקיום התומ\"צ שלו יהי' בשמחה. והענין הוא, דיש עוד פירוש בבת ציון, דציון הם הצדיקים, ובת ציון הוא התקשרות עם הצדיקים<sup data-n=\"3078\">35</sup>. וע\"י ההתקשרות להצדיקים, ובפרט לנשיאי ישראל שענינם הוא להמשיך גילוי אלקות לכל ישראל ובפרט להמקושרים ושייכים אליהם, עי\"ז נמשך לו נתינת כח שקיום התומ\"צ שלו יהי' בשמחה, רני ושמחי. ובכלל זה הוא גם שלא יהיו לו בלבולים מענינים גשמיים<sup data-n=\"3079\">36</sup>, רני ושמחי גם בנוגע לבני חיי ומזוני רויחי.\n<b>וע\"י</b> ההתקשרות להצדיקים ולהנשיאים שבכל דור, ומה שנוגע לנו במיוחד הוא ההתקשרות לכ\"ק מו\"ח אדמו\"ר נשיא דורנו, יבטלו כל ההעלמות וההסתרים, כולל גם ביטול (ההעלם ד)הגלות<sup data-n=\"3080\">37</sup>, וכ\"ק מו\"ח אדמו\"ר יוליכנו קוממיות לארצנו, בגאולה האמיתית והשלימה, בקרוב ממש.\n**********",[["3043","*","יצא לאור ב<b>קונטרס ט\"ו סיון – תש\"נ</b>, \"לקראת ט\"ו סיון, יום התחלת מאסרו של כ\"ק אדמו\"ר מהוריי\"צ נ\"ע בשנת תרפ\"ז* . . <i>ג' בהעלותך</i>,<i> יב סיון</i>,<i> שנת ה'תש\"נ</i>\"."],["3044","1","זכרי' ב, יד. – התחלת וראש ההפטורה דש\"פ בהעלותך."],["3045","2","השני – לו, סע\"ד ואילך."],["3046","3","זכרי' ד, ב."],["3047","4","לז, סע\"ב ואילך."],["3048","5","כמארז\"ל (עירובין נד, א. שמו\"ר פמ\"א, ז (בתחלתו). ויק\"ר פי\"ח, ג (בסופו). ועוד) עה\"פ (תשא לב, טז) \"חרות על הלוחות\" – א\"ת חרות אלא חירות, חירות מן גליות (שמו\"ר שם), חירות מן המלכיות (ויק\"ר שם. וראה גם זח\"ב קיג, סע\"ב), אין כל אומה ולשון שולטת בהן (עירובין שם. וראה גם שמו\"ר שם)."],["3049","6","לו, א ואילך. וכ\"ה ברד\"ה זה דפ' בהעלותך תרכ\"ז** (סה\"מ תרכ\"ז ע' רצז)."],["3050","7","שמו\"ר ס\"פ פקודי. שהש\"ר ספ\"ג."],["3051","8","שה\"ש ג, יא."],["3052","9","כ\"ה הלשון בתו\"א וברד\"ה תרכ\"ז הנ\"ל שם. <i>ובכ\"מ</i>."],["3053","10","וראה גם ד\"ה הנ\"ל תרכ\"ז ס\"ה ואילך (סה\"מ תרכ\"ז ע' שב ואילך)."],["3054","11","כ\"ה להדיא בתו\"א שם (לו, סע\"ד).\n*) <i>וראה לקמן ס\"ע שעא ובהערה 40</i>,<i> שלאחרי הגאולה די\"ב תמוז נתגלה שהמאסר הי' זריעה</i>,<i> בכדי שעי\"ז תהי' צמיחה בריבוי והוספה בהפצת המעיינות</i>.\n**) <i>כמובן מזה שנרשם בין המאמר דפ' נשא להמאמר דפ' שלח</i>.\n<i>בכת\"י א' (הובא ברשימת מאמרי דא\"ח דאדמו\"ר מהר\"ש ע' 3 בשוה\"ג) רשום על ד\"ה זה \"שבת חנוכה תרכ\"ז\"</i>.<i> ולכאורה הכוונה </i><b>שנאמר</b><i> בשבת חנוכה</i>,<i> שהרי נסדר בפ' בהעלותך</i>."],["3055","12","סד\"ה צאינה וראינה עזר\"ת (סה\"מ עזר\"ת ע' רכה)."],["3056","13","ראה גם סה\"מ תרכ\"ט ע' קפד ואילך, שהביטול דנעשה הו\"ע למסור נפשו באחד. ולהעיר גם מלקו\"ת אמור לה, סע\"א ואילך, דשתי העטרות שנתן בראשן של ישראל הוא ע\"י המצוות והתורה (בתי ואחותי), והעטרה שנטל לעצמו, היא העטרה שעטרה <i>לו אמו</i>, ע\"י מס\"נ באחד."],["3057","14","אלא שבכמה שנים קוראין גם פ' נשא לאחרי חג השבועות. וע\"ד שפרשת במדבר קוראין לעולם בהשבת שלפני חג השבועות ולפעמים גם פ' נשא."],["3058","15","משלי כ, כז."],["3059","16","לקו\"ת פרשתנו (בהעלותך) רד\"ה בהעלותך את הנרות (כט, ג). רד\"ה ראיתי והנה מנורת זהב גו' (לג, ב). רד\"ה זה תרכ\"ז (סה\"מ תרכ\"ז ע' רצז). ובכ\"מ."],["3060","17","סה\"מ תרכ\"ז שם. וראה עד\"ז תו\"א שם (לו, א)."],["3061","18","במדב\"ר פרשתנו פט\"ו, ה. תנחומא פרשתנו ד. וכ\"ה גם בשמו\"ר פל\"ו, ב. – הובא בסה\"מ תרכ\"ז שם*."],["3062","19","ראה המשך תרס\"ו ע' נה."],["3063","20","ראה תו\"א שם (לז, ג) בענין המעלה ד<i>בת</i> ציון \"יש אתערותא דלעילא שהיא לעילא לעילא מקום שאין אתערותא דלתתא מגעת שם כלל\"."],["3064","21","שערי אורה שער החנוכה ד\"ה רני ושמחי פכ\"א (לג, ב)."],["3065","22","לשון התו\"א שם.\n*) <i>בסה\"מ שם</i>:<i> וכמו </i><b>שפרש\"י</b><i> ע\"פ בהעלותך</i>.<i> וכפה\"נ הוא ט\"ס וצ\"ל</i>:<i> וכמו </i><b>במד\"ר</b><i> ע\"פ בהעלותך</i>."],["3066","23","ראה גם ד\"ה החודש ה'תשל\"ה ס\"ד (לעיל ס\"ע צח ואילך) ובהנסמן שם, שהמעלה דבתי היא בענין הביטול."],["3067","24","בכ\"מ (ד\"ה בחודש השלישי ה'תשכ\"ט ס\"ז (לעיל ע' שב ואילך). וראה לקו\"ת במדבר יד, א. ועוד) שנשמע הוא ביטול להרצון ונעשה הוא ביטול לבעל הרצון. ובד\"ה בששה\"ק ה'תש\"ט ס\"ב (סה\"מ ה'תש\"ט ע' 148), שגם הקב\"ע דנעשה הוא בכלל ביטול להרצון, והביטול לבעל הרצון הוא <i>בהקדמת</i> נעשה לנשמע."],["3068","25","ראה בארוכה ד\"ה בחודש השלישי הנ\"ל ס\"ח (לעיל ע' שג ואילך)."],["3069","26","ראה בארוכה לקמן ח\"ד ע' קצב, דהמס\"נ שמצד הנשמה, כיון שהיא מצד טבעה, היא בחינת מציאות."],["3070","27","בהר כה, נה. וע\"פ מ\"ש בפנים, אולי יש לבאר (וראה <i>עד\"ז</i> אוה\"ח עה\"פ) כפל הלשון \"עבדים עבדי הם\": דע\"י שקבלו עליהם עומ\"ש נעשים \"עבדים\" (עבדים סתם), וע\"י שהוצאתי אותם מארץ מצרים – \"עבדי הם\", <i>שהקב\"ה</i> עשה אותם לעבדים."],["3071","28","להעיר שהשעבוד דעבד שמכרוהו ב\"ד הוא שעבוד גדול יותר מהמוכר עצמו – דמכרוהו ב\"ד רבו מוסר לו שפחה כנענית משא\"כ המוכר עצמו. ועוד כמה חילוקים (קידושין יד, ב) – דיש לומר הטעם על זה, כי המוכר עצמו הוא ברצונו, וכשמכרו אותו ב\"ד הוא על כרחו."],["3072","29","להעיר ממרז\"ל (קידושין כב, ב. הובא בפרש\"י עה\"פ משפטים כא, ו. ירושלמי קידושין פ\"א סוףה\"ב) אוזן ששמעה <i>על הר סיני</i> כי לי בני ישראל עבדים עבדי הם. ולהעיר שהדיבור הראשון דמ\"ת הוא \"אנכי ה' אלקיך אשר הוצאתיך מארץ מצרים\", ובפרש\"י שם \"כדאי היא ההוצאה שתהיו <i>משועבדים</i> לי\"."],["3073","30","ראה בארוכה ד\"ה החודש דלעיל הערה 23. <i>וש\"נ</i>."],["3074","31","ראה ד\"ה הנ\"ל ס\"ה."],["3075","32","להעיר מתורת הבעש\"ט (כתר שם טוב – הוצאת קה\"ת – סימן מ\"ז (ז, ד)), דהטעם שכפה הקב\"ה עליהם את ההר כגיגית (שבת פח, א), אף שאמרו מעצמם נעשה ונשמע (כקושיית התוספות ד\"ה כפה שם), הוא \"ללמד שגם כשאינו חושק בתורה ועבודת ה', מ\"מ אינו בן חורין ליבטל, רק יעשה על כרחו וידמה כמו שכופין אותו לעשות בע\"כ\" – דלכאורה, אמירתם נעשה ונשמע היא התחייבות על כל הזמנים, ומהי הקס\"ד דע\"י שאח\"כ (לאחרי ההתחייבות) \"אינו חושק\" יהי' בן חורין ליבטל?\nוי\"ל הביאור בזה, דההתחייבות דנעשה ונשמע, כיון שהיא מצד האדם שהוא מוגבל, אפשר שלפעמים לא יוכל להתגבר על זה ש\"אינו חושק בתורה\", ובמילא הוא \"בן חורין ליבטל\" דאונס רחמנא פטרי' (ב\"ק כח, ב); וע\"י <i>שהקב\"ה</i> כפה עליהם הר כגיגית – ניתן הכח לכ\"א מישראל לעשות בעל כרחו, גם כשאינו חושק."],["3076","33","תענית כו, ב (במשנה)."],["3077","34","ראה תו\"א שם (לז, סע\"ב ואילך). שערי אורה שם פי\"ח (לב, א)."],["3078","35","אוה\"ת חנוכה ד\"ה רני ושמחי שיב, סע\"א."],["3079","36","ראה רמב\"ם הל' תשובה פ\"ט ה\"א."],["3080","37","שאינו מניח לעסוק בתורה ובמצוות כהוגן (רמב\"ם שם ה\"ב)."]]],[1500380054,"<h3>בס\"ד. ש\"פ בהעלותך, כ\"א סיון ה'תשכ\"ט<sup data-n=\"3081\">*</sup></h3>\n<b>בהעלותך</b> את הנרות<sup data-n=\"3082\">1</sup>, ואיתא בלקו\"ת<sup data-n=\"3083\">2</sup> דנרות הם הנשמות כמ\"ש<sup data-n=\"3084\">3</sup> נר הוי' נשמת אדם [וז' הנרות דהמנורה הם ז' סוגי בני ישראל בעבודת ה', יש עובד מאהבה משוך כמים (חסד) ויש מאהבה כרשפי אש (גבורה) וכו']. ומבאר אדמו\"ר מהר\"ש במאמרו ד\"ה וידבר גו' בהעלותך את הנרות שנאמר לפני מאה שנה<sup data-n=\"3085\">4</sup>, דזה שהנשמות נקראים נרות הוא כמאמר רז\"ל<sup data-n=\"3086\">5</sup> אמר הקב\"ה לאדם נרי בידך ונרך בידי, נרי בידך זו התורה דכתיב<sup data-n=\"3087\">6</sup> כי נר מצוה ותורה אור ונרך בידי זו הנפש דכתיב<sup data-n=\"3084\">3</sup> נר הוי' נשמת אדם, אם שמרת את נרי אני משמר את נרך ואם כבית את נרי אני מכבה את נרך. וצריך להבין, הרי זה שהנשמות נק' נרות הוא מפורש בקרא (נר הוי' נשמת אדם), ולמה מביא בהמאמר את דברי המדרש נרי בידך ונרך בידי. גם צריך להבין, דבפסוק נאמר נר <i>הוי'</i> נשמת אדם, שהנשמה היא נר הוי', ובמדרש הנ\"ל אומר שהנשמה היא נר<i>ך</i> (דהאדם) והתורה היא נר<i>י</i> (דהקב\"ה).\nב) <b>ויש</b> לבאר זה בהקדים המבואר בכ\"מ<sup data-n=\"3088\">7</sup> דענין בהעלותך את הנרות הוא שאהרן מעורר את הנשמות שיהי' בהם הרצון לעלות למעלה, ועד ליכלל בעצמות אוא\"ס. והגם דרצון זה הוא טבע דהנשמה, וכמבואר בתניא<sup data-n=\"3089\">8</sup>, דהטעם שהנשמות נקראים בשם נרות, הוא, כי כמו שהנר טבעו לעלות למעלה ולידבק בשרשו (ביסוד האש הכללי שתחת<sup data-n=\"3090\">9</sup> גלגל הירח) כן הנשמה היא בטבע הרצוא לעלות למעלה להכלל במקור חוצבה, מ\"מ צריך שאהרן יעלה את הנרות (הנשמות), כי ע\"י ירידת הנשמה למטה והתלבשותה בגוף מתעלם טבע הרצוא שבה. וכמבואר בארוכה בהדרושים<sup data-n=\"3088\">7</sup>, דמהטעמים על זה שהנשמות דאצילות נקראים זרע אדם והנשמות דבי\"ע נקראים זרעבהמה<sup data-n=\"3091\">10</sup>, הוא, כי הנשמות דאצילות, גם בירידתם למטה, טבע הרצוא והעלי' שבהם הוא בגילוי, ולכן נקראים בשם אדם על שם רוח האדם העולה היא למעלה<sup data-n=\"3092\">11</sup>, והנשמות דבי\"ע (שהם רוב הנשמות<sup data-n=\"3093\">12</sup>), כשהן יורדות למטה ומתלבשות בגוף, הן נמשכות אחר הגוף ועניני עוה\"ז הגשמי, ולכן נקראים בשם בהמה על שם רוח הבהמה היורדת היא למטה<sup data-n=\"3092\">11</sup>. ועבודתו של אהרן היא לעורר ולגלות את טבע הרצוא והעלי' שישנו גם בנשמות דבי\"ע, בהעלותך את הנרות, שטבע העלי' שבהם יהי' בגילוי.\n<b>ומבואר</b> בהדרושים<sup data-n=\"3094\">13</sup>, דהטעם שהעלאת הנרות [גילוי טבע הרצוא והעלי' דהנשמות] הוא ע\"י אהרן דוקא, כי באהרן כתיב<sup data-n=\"3095\">14</sup> כשמן הטוב על הראש יורד על הזקן זקן אהרן שיורד על פי מדותיו, וענין זקן אהרן הוא הלכות התורה<sup data-n=\"3096\">15</sup>, וע\"י התורה, תורה אור&lt;6&gt;, מתגלה ומאיר טבע העלי' דהנשמה (שישנו גם בירידתה למטה והתלבשותה בגוף), בהעלותך את הנרות. ועפ\"ז יש לבאר השייכות דמארז\"ל (המובא בהמאמר) אם שמרת את נרי אני משמר את נרך לבהעלותך את הנרות, כי ענין אני משמר את נרך (שמירת הנר שלא תיכבה) הוא שהנר דהנשמה (טבע הרצוא והעלי' שלה) יהי' בגילוי, וזה ששמירת הנר דהנשמה הוא ע\"י שמירת הנר דתורה הוא ע\"ד הענין דבהעלותך את הנרות שע\"י אהרן, תורה.\nג) <b>וממשיך</b> בהמאמר, דצריך להבין באם שמרת את נרי אני משמר את נרך, מהי שייכותם זה לזה ועוד ועד שהם תלויים זה בזה. ומבאר זה ע\"פ מה דאיתא במדרש<sup data-n=\"3097\">16</sup> בזכות מי נבראו אלה תולדות השמים והארץ<sup data-n=\"3098\">17</sup> ובזכות מי הם עומדים, בזכות אלה שמות בני ישראל<sup data-n=\"3099\">18</sup>, ואלה בזכות מי עומדים, בזכות אלה העדות והחוקים והמשפטים<sup data-n=\"3100\">19</sup>. שהכוונה דבריאת העולם היא בשביל ישראל, והשלימות דישראל היא ע\"י התורה. דע\"י שישראל מקיימים התרי\"ג מצוות הם מתעלים למדריגה נעלית יותר מכמו שהם מצד עצמם. וזהו מה שהנשמה יורדת למטה ומתלבשת בגוף גשמי בכדי לקיים תומ\"צ, כי ע\"י קיום התומ\"צ מתעלית הנשמה למעלה יותר מכמו שהיתה קודם ירידתה. וזהו אם שמרת את נרי אני משמר את נרך, ששמירת הנר דהנשמה היא ע\"י שמירת הנר דתורה.\n<b>וע\"פ</b> מש\"כ בהמאמר דענין אם שמרת את נרי אני משמר את נרך הוא שע\"י קיום התומ\"צ מתעלית הנשמה למעלה יותר מכמו שהיתה קודם ירידתה, ישלומר, דזה שמקשר ענין זה עם בהעלותך את הנרות, הוא, כי גם ענין בהעלותך את הנרות הוא<sup data-n=\"3101\">20</sup> העלי' שנעשה בהנשמות למעלה יותר גם מכמו שהיו קודם ירידתם למטה.\nד) <b>וביאור</b> הענין בפרטיות יותר, יש להקדים דהדיוק בהמאמר מפני מה הם [שמירת הנר דהנשמה ושמירת הנר דתורה] תלויים זה בזה הוא, כי שמרת את נרי הוא לא רק זה שהאדם אינו עובר ח\"ו על ציווי התורה אלא שהוא <i>מקיים</i> את מצוות התורה<sup data-n=\"3102\">21</sup>, ולכן מדייק מפני מה הם תלויים זה בזה. דזה ששמירת הנר דהנשמה תלוי' בזה שאינו עובר ח\"ו על ציווי התורה, הוא, כי כשעובר ח\"ו על ציווי התורה נעשה פגם בהנשמה. והדיוק בהמאמר הוא מה ששמירת הנר דהנשמה תלוי' <i>בקיום</i> התורה<sup data-n=\"3103\">22</sup>. ויש להוסיף, שהדיוק בהמאמר הוא בעיקר בנוגע נשמות דאצילות. דבנוגע נשמות דבי\"ע (שהם רוב הנשמות) יש לומר דזה ששמירת הנר דהנשמה תלוי' בהנר דתורה הוא דכיון שאצלם הגוף ונפש הבהמית מעלים ומסתיר על הנשמה, לכן שמירת הנר דנשמתם הוא ע\"י קיום התומ\"צ (כנ\"ל סעיף ב), והדיוק והשאלה בהמאמר הוא בעיקר בנשמות דאצילות, דכיון שאצלם הנשמה היא בגילוי, למה צריכים הם להנר דתורה.\n<b>ועפ\"ז</b> צריך להבין מ\"ש בהמאמר דזה ששמירת הנר דהנשמה היא ע\"י שמירת הנר דתורה הוא כי אלה שמות בני ישראל עומדים בזכות אלה העדות והחוקים והמשפטים, דלכאורה, זה שישראל עומדים בזכות התורה והמצוות הוא שע\"י קיום התומ\"צ הם מתעלים למדריגה נעלית יותר<sup data-n=\"3104\">23</sup> (אבל הדרגא דנש\"י שמצד עצמם אינה תלוי' לכאורה בהתורה), ופירוש אם שמרת את נרי אני משמר את נרך הוא ששמירת הנר דהנשמה (היינו דרגת הנר דהנשמה מצד עצמה<sup data-n=\"3105\">24</sup>) הוא ע\"י שמירת הנר דתורה. ויש לבאר זה ע\"פ מאמר הזהר<sup data-n=\"3106\">25</sup> המובא בתניא<sup data-n=\"3107\">26</sup>, דכמו שאור הנר אינו מאיר ונאחז בפתילה בלי שמן כן אין השכינה שורה על גוף האדם שנמשל לפתילה אלא ע\"י מעשים טובים שנמשלו לשמן. ומבאר בתניא<sup data-n=\"3108\">27</sup>, דהטעם על זה ש(השראת השכינה על גוף האדם היא דוקא ע\"י קיום המצוות (מעשים טובים), ו)לא די לובנשמתו שהיא חלק אלוקה ממעל להיות היא כשמן לפתילה, כי נשמת האדם, אפילו כשהוא צדיק גמור עובד ה' ביראה ואהבה בתענוגים, אינה בטילה במציאות לגמרי, רק הוא דבר בפני עצמו ירא ה' ואוהבו. והמצוות שהן פנימיות רצונו ית', אין החיות שבהם דבר נפרד בפ\"ע כלל אלא הוא מיוחד ונכלל ברצונו ית'. ולכן השראת השכינה על גוף האדם היא ע\"י קיום המצוות דוקא, כי ענין השראת השכינה באיזה דבר הוא שאותו הדבר נכלל באור ה' ובטל לו במציאות לגמרי, שאז דוקא שורה ומתגלה ומאיר בו ה' אחד. ועפ\"ז יש לבאר זה ששמירת הנר דהנשמה היא ע\"י שמירת הנר דתורה, כי ענין הנר דהנשמה הוא הביטול שלה<sup data-n=\"3109\">28</sup>, ושלימות הביטול דהנשמה (ביטול במציאות לגמרי) הוא ע\"י קיום המצוות. וזהו שהנר דהנשמה נק' נר<i>ך</i> (דהאדם) והנר דתומ\"צ נק' נר<i>י</i> (דהקב\"ה), כי הביטול דהנשמה (שמצד עצמה) אינו ביטול בתכלית – נרך דהאדם, והנר דמצוות שהוא פנימיות רצונו ית' הוא נרי דהקב\"ה. וע\"י שהאדם מקיים את המצוות, נמשך ביטול זה גם בהנשמה, אני משמר את נרך<sup data-n=\"3110\">29</sup>.\nה) <b>ולהעיר</b><b>,</b> דמאמר הנ\"ל שייך לחג השבועות. דנוסף לזה שפרשת בהעלותך את הנרות (התחלת המאמר) קורין לאחרי חג השבועות<sup data-n=\"3111\">30</sup>, נרשם בהתחלת המאמר שהוא שייך לד\"ה וידבר אנכי<sup data-n=\"3112\">31</sup>. ועפ\"ז יש לומר, דזה שמבואר בהמאמר שע\"י קיום התומ\"צ נעשה עלי' בהנשמה, הוא ע\"ד העילוי דישראל שנתחדש במתן תורה. והענין הוא, דהאהבה הטבעית שבכל אחד מישראל להיות דבוק בה' ולא ליפרד ממנו ית' בשום אופן אפילו במסירת נפש ממש היתה גם קודם מתן תורה, שהרי אהבה זו היא ירושה לנו מאבותינו. וע\"פ מ\"ש בתניא<sup data-n=\"3113\">32</sup> דזה שהאבות הורישו לכל אחד מישראל אהבה זו שייך לזה שהאבות הן הן המרכבה<sup data-n=\"3114\">33</sup>, דענין המרכבה היא שהיא <i>בטילה</i> להרוכב [דזה שהליכת המרכבה (הסוסים) היא כפי רצון הרוכב הוא לא מפני שרוצים שתהי' <i>להם</i> שייכות להרוכב (ע\"ד אהבה הטבעית הנ\"ל שהיא הרצון שהוא יהי' דבוק בה') אלא מפני ביטולם להרוכב], יש לומר, שבהאהבה הטבעית הבאה בירושה מהאבות הן הן המרכבה כלולה (בהעלם) גם האהבה שבבחינת ביטול<sup data-n=\"3115\">34</sup>, שאינו רוצה לעצמו כלל וכל רצונו הוא שיהי' גילוי אלקות בעולם<sup data-n=\"3116\">35</sup> ושתושלם הכוונה דדירה<sup data-n=\"3117\">36</sup> לו ית' בתחתונים.<b>והנה</b> ידוע<sup data-n=\"3118\">37</sup> דאהבה היא האהבה והרצון דהאדם (האוהב), ולכן, גם כשהאהבה והרצון שלו הוא שיושלם רצון העליון, מ\"מ, עצם ענין האהבה והרצון הוא מציאות. ואמיתית ענין הביטול הוא בהעבודה דקבלת עול, שהוא כמו עבד שאין לו שום רצונות, וכל מה שעושה הוא מצד עול האדון שמוטל עליו, שמצד זה הוא <i>מוכרח</i> לקיים רצון האדון. ויש לומר, דכיון שביטול המרכבה להרוכב הוא לא מצד הרצון דהמרכבה (שרוצה להיות בטילה להרוכב ומרכבה אליו) אלא מצד הרוכב, לכן בהירושה מהאבות הן הן המרכבה כלול בהעלם גם הביטול דקבלת עול. [ולהעיר ממאמר רז\"ל<sup data-n=\"3119\">38</sup> בשעה שהקדימו ישראל נעשה לנשמע כו' מי גילה לבני רז זה ומבואר בחסידות<sup data-n=\"3120\">39</sup> דזה שהקדימו נעשה לנשמע [שבהביטול דקבלת עול עצמו הוא ביטול נעלה ביותר, ביטול לבעל הרצון] הוא ע\"י גילוי אהבה המסותרת, רז. ויש לומר, שהשייכות <i>דאהבה</i> מסותרת (מציאות) להקדמת נעשה לנשמע (<i>ביטול</i> דקבלת עול), הוא, כי אהבה המסותרת היא בירושה מהאבות הן הן <i>המרכבה</i>]. ומזה מובן, דהביטול שנמשך לישראל במתן תורה (<i>לאחרי</i> שהקדימו נעשה לנשמע) הוא ביטול נעלה יותר גם מהביטול דמרכבה.\nו) <b>והענין</b> הוא, דאיתא בגמרא<sup data-n=\"3121\">40</sup> אמרו עליו על ריב\"ז שלא הניח דבר גדול ודבר קטן, דבר גדול מעשה מרכבה דבר קטן הוויות דאביי ורבא. ומבואר בהמאמר<sup data-n=\"3122\">41</sup>, דהטעם שמעשה מרכבה נק' דבר גדול הוא, כי ע\"י המרכבה<sup data-n=\"3123\">42</sup> מגיע האדם הרוכב על המרכבה למקום שאינו יכול להגיע לשם מצד עצמו, וכמו\"כ הוא במרכבה העליונה, שהחיות נושאות את הכסא<sup data-n=\"3124\">43</sup> ואת האדם שעל הכסא<sup data-n=\"3125\">44</sup> לבחינת לא אדם<sup data-n=\"3126\">45</sup>. ועיקר ההעלאה לבחינת לא אדם הוא בהמרכבה דהאבות (האבות הן הן המרכבה), מרכבה דאצילות. כי העלי' דבחינת אדם לבחינת לא אדם שע\"י מרכבה דבי\"ע היא שהאדם שעל הכסא (אדם דבי\"ע) מתעלה לדרגא שהיא בחינת לא אדם לגבי אדם דבי\"ע, וע\"י המרכבה דהאבות, מרכבה דאצילות, נעשה העלי' דבחי' אדם דאצילות לבחינת לא אדם שלמעלה מאצילות, אריך. וזהו שמעשה מרכבה נקרא דברגדול, כי אדם, <i>זעיר</i> אנפין, הוא בחינת קטנות וצמצום, וע\"י המרכבה הוא מתעלה לבחינת אריך, <i>גדול</i>.\n<b>והטעם</b> שהוויות דאביי ורבא נק' דבר קטן (אף שהוא עיקר בתושבע\"פ) הוא, כי הלכות התורה נתלבשו בדברים קטנים. דנוסף לזה שהמצוות נתלבשו בדברים גשמיים, יש בכל מצוה כמה פרטי דינים, דענין ההתחלקות (פרטים) הוא צמצום והגבלה, קטנות. [ועפ\"ז<sup data-n=\"3127\">46</sup>, החילוק בין מעשה מרכבה להוויות דאביי ורבא הוא מן הקצה אל הקצה. דענין מרכבה הוא היציאה מבחינת הגבלה (אדם) לבחינת בל\"ג (לא אדם) – דבר גדול (דאמיתית ענין הגדלות הוא בדבר שאינו מוגבל<sup data-n=\"3128\">47</sup>), ובהוויות דאביי ורבא הוא להיפך, התלבשות רצון העליון, בלי גבול, בדברים מוגבלים – דבר קטן]. וממשיך בהמאמר עוד טעם על זה שהוויות דאביי ורבא נק' דבר קטן, כי התורה דעכשיו היא דבר קטן לגבי פנימיות התורה שתתגלה לעתיד. וגם לפי שהתורה היא משל ולבוש לאוא\"ס המלובש בה. שלכן נקראת התורה בשם משל הקדמוני<sup data-n=\"3129\">48</sup>, שהיא משל ולבוש לבחי' קדמונו של עולם<sup data-n=\"3130\">49</sup>. ומשל לגבי נמשל הוא דבר קטן.\n<b>ויש</b> לומר דלהטעם שהוויות דאביי ורבא נק' דבר קטן מפני שהתורה נתלבשה בדברים קטנים, התואר דבר קטן הוא מצד הלבושים דתורה. ולכן מוסיף שהתורה דעכשיו היא דבר קטן לגבי פנימיות התורה שתתגלה לע\"ל [וגם שהיא דבר קטן לגבי אוא\"ס המלובש בה], דע\"פ טעם זה, התואר דבר קטן הוא (גם) בנוגע להתורה עצמה. [ומה שמביא גם טעם הראשון שהתורה נתלבשה בדברים קטנים, יש לומר, כי בטעם זה מודגש שהחילוק בין הוויות דאביי ורבא למעשה מרכבה הוא חילוק מן הקצה אל הקצה, כנ\"ל].\nז) <b>וממשיך</b> בהמאמר עוד ביאור בזה שהתורה נק' דבר קטן, שהוא על שם עוצם ביטול ההלכה לגבי אוא\"ס המלובש בה. דכמו שלימוד התורה דהאדם צ\"ל בביטול, תען לשוני אמרתך<sup data-n=\"3131\">50</sup>, כעונה אחר הקורא<sup data-n=\"3132\">51</sup>, עד\"ז הוא בנוגע להלכות התורה עצמם שהם בביטול לאוא\"ס המלובש בהם, כדלקמן. [ויש לומר, דלהפירוש קטן כפשוטו, התואר דבר קטן הוא ביחס לענינים אחרים. ולהפירוש קטן על שם הביטול [ע\"ד קטונתי מכל החסדים<sup data-n=\"3133\">52</sup>], הקטנות (ביטול) הוא בו עצמו]. וצריך להבין (להפירוש ש\"קטן\" הוא על שם הביטול), הרי גם מרכבה היא בביטול להרוכב, ואעפ\"כ נק' דבר גדול.<b>ונקודת</b> הביאור בזה יש לומר, דהביטול שנק' בשם דבר קטן (קטונתי), הוא, שהוא בטל לגמרי ואין בו שום מעלה. וכמ\"ש באגה\"ק ד\"ה קטונתי<sup data-n=\"3134\">53</sup>, שמשים עצמו כשיריים ומותרות ממש שאין בו שום צורך. וכיון שהמרכבה היא מציאות, ועד שיש בה יתרון לגבי הרוכב [וכנ\"ל שע\"י המרכבה יכול הרוכב להגיע למקום שאינו יכול להגיע לשם מצד עצמו], לכן אינה דבר קטן. [ואדרבה מצד העילוי שבה, שעל ידו היא העלי' לבחינת גדול (אריך), נק' גם המרכבה בשם דבר גדול]. והלכות התורה שנתלבשו בדברים גשמיים [פירוש הראשון בדבר קטן], כיון שדברים גשמיים אין להם ערך<sup data-n=\"3135\">54</sup> לחכמתו ורצונו ית' המלובשים בהם, הרי הם בתכלית הביטול, דבר קטן. וע\"י הביטול שבהלכות התורה עצמם, נמשך הביטול גם בהאדם העוסק בתורה, שלימוד התורה שלו יהי' באופן דתען לשוני אמרתך, כעונה אחר הקורא.\nח) <b>וזהו</b> וידבר אלקים את כל הדברים האלה לאמר<sup data-n=\"3136\">55</sup>, ומבואר בחסידות&lt;51&gt;, דבמתן תורה ניתן הכח שלימוד התורה של האדם יהי' באופן דלאמר, לחזור הדברים שהקב\"ה אומר, תען לשוני אמרתך, דלכאורה, הרי גם לפני מתן תורה הקדימו ישראל נעשה לנשמע, דהקדמת נעשה לנשמע הוא ביטול דבעל הרצון, ומהו החידוש בהביטול דלאמר שנתחדש במתן תורה לגבי הביטול דנעשה ונשמע. והביאור בזה, שהביטול דהקדמת נעשה לנשמע יש בו מעלה. דהקדמת נעשה לנשמע הוא קבלת עול מלכות, וע\"י שהעם מקבלים את עול מלכותו נעשה מלך [וע\"ד הביטול דמרכבה, שע\"י הביטול דהמרכבה להרוכב עי\"ז<sup data-n=\"3137\">56</sup> היא נושאת ומגביהה את הרוכב]. והביטול דלאמר שנתחדש במתן תורה הוא ביטול בתכלית.\n<b>ועד\"ז</b> הוא בקיום המצוות, שבמתן תורה ניתן הכח שקיום המצוות של האדם יהי' בתכלית הביטול, היינו שקיום המצוות שלו יהי' (לא מפני שהוא קיבל עליו עול מלכות שמים ועול מצוות, אלא) מפני שציווי הקב\"ה גוזר עליו להיות כפי הציווי. וכמבואר בלקו\"ת<sup data-n=\"3138\">57</sup> בנוגע לעשרת הדברות שנאמרו במתן תורה [ועד\"ז הוא בנוגע כל הציווים שבתורה] שנאמרו בלשון ציווי וגם בלשון עתיד, כי הדיבור עצמו <i>גוזר</i> על האדם והעולם (ומכריח אותם<sup data-n=\"3139\">58</sup>) להיות כן.\n<b>ויש</b> לומר דהיתרון בהביטול דקיום המצוות באופן זה לגבי הביטול דקבלת עול, הוא בשני ענינים. לפי שהביטול דקבלת עול הוא ע\"י <i>שהוא</i> קיבל עליו להיות עבדו של מלך מלכי המלכים הקב\"ה<sup data-n=\"3140\">59</sup>. ויתירה מזו, שהביטול דעבד לאדונו [גםכשהוא <i>נולד</i> עבד] קשור עם מציאותו, שענינו הוא זה שהוא עבד של האדון<sup data-n=\"3141\">60</sup>, והביטול באופן הנ\"ל הוא (לא מצד ענינו של האדם, אלא) שאי אפשר שתהי' מציאות בעולם היפך <i>ציווי הקב\"ה</i><sup data-n=\"3142\">61</sup>.\nט) <b>והנה</b> הגם שהביטול דלימוד התורה וקיום המצוות באופן הנ\"ל הוא ביטול בתכלית, מ\"מ כיון שישראל וקוב\"ה כולא חד<sup data-n=\"3143\">62</sup>, לכן ביטול זה אינו שולל את מציאותם אלא אדרבה זה גופא הוא מציאותם. וזהו אם שמרת את נרי אני משמר את נרך, דהגם שענין אני משמר את נרך הוא שהאדם בא לתכלית הביטול (שלמעלה גם מביטול דמרכבה), מ\"מ אין זה שולל את מציאותו אלא אדרבה <i>משמר</i> את נרך. וזהו גם זה שפירש רש\"י עה\"פ בהעלותך את הנרות שתהא שלהבת עולה מאלי', דהגם שהעלי' דהנשמות (בהעלותך את הנרות) היא שהם באים לתכלית הביטול, מ\"מ, הוא באופן ששייך להנרות (נשמות) עצמם, שלהבת עולה מאלי'. והיינו, שלימוד התורה וקיום המצוות הוא בביטול וביחד עם זה גם בחיות ובשמחה. וכיון ששמחה פורצת גדר<sup data-n=\"3144\">63</sup>, לכן, ע\"י שמחה של תורה ושמחה של מצוה נמשכים כל הענינים הרוחניים והגשמיים בלי הגבלות.\n**********",[["3081","*","יצא לאור ב<b>קונטרס ט\"ו סיון – תנש\"א</b>, \"בקשר עם ט\"ו סיון, יום התחלת מאסרו של כ\"ק אדמו\"ר מהוריי\"צ נ\"ע בשנת תרפ\"ז* . . <i>ג' בהעלותך</i>,<i> טו סיון</i>,<i> ה'תנש\"א</i>\"."],["3082","1","פרשתנו (בהעלותך) ח, ב."],["3083","2","פרשתנו רד\"ה בהעלותך את הנרות (כט, ג)."],["3084","3","משלי כ, כז."],["3085","4","משנת אמירת מאמר זה (תשכ\"ט) – נדפס בסה\"מ תרכ\"ט ע' ריד ואילך. וראה גם ד\"ה בהעלותך תרע\"ח (סה\"מ תרע\"ח ע' שלו ואילך)."],["3086","5","דב\"ר פ\"ד, ד."],["3087","6","משלי ו, כג."],["3088","7","אוה\"ת פרשתנו ד\"ה בהעלותך את הנרות (ע' שכז. שם ע' שלב). ד\"ה זה בסה\"מ עטר\"ת (ע' תעג ואילך). ה'ש\"ת (ע' 127 ואילך). וראה גם ד\"ה זאת תורת הבית תרפ\"ט פ\"ב ואילך (סה\"מ תרפ\"ט ע' 164 ואילך). ובכ\"מ."],["3089","8","ריש פי\"ט."],["3090","9","רמב\"ם הל' יסוה\"ת פ\"ג ה\"י.\n*) <i>וראה לקמן ס\"ע שעא ובהערה 40</i>,<i> שלאחרי הגאולה די\"ב תמוז נתגלה שהמאסר הי' זריעה</i>,<i> בכדי שעי\"ז תהי' צמיחה בריבוי והוספה בהפצת המעיינות</i>."],["3091","10","ירמי' לא, כו. וראה תו\"א ר\"פ משפטים. ובכ\"מ."],["3092","11","קהלת ג, כא."],["3093","12","ראה תו\"א שם \"שהם (נשמות דבי\"ע) כמעט כל הנשמות שבדורותינו, כי נשמות דאצילות הן בני עלי' שהם מועטים כו' אפילו בדורות הראשונים\"."],["3094","13","אוה\"ת פרשתנו שם (ס\"ע שכז ואילך. שם ע' שלב). סה\"מ עטר\"ת שם (ע' תעד-ו)."],["3095","14","תהלים קלג, ב."],["3096","15","ראה גם לקו\"ת פרשתנו שם (ל, ג)."],["3097","16","שמו\"ר פמ\"ח, ב."],["3098","17","בראשית ב, ד."],["3099","18","שמות א, א."],["3100","19","ואתחנן ד, מה."],["3101","20","ראה סה\"מ תרכ\"ט ע' רכ ואילך. וראה גם ד\"ה בהעלותך ה'תשל\"ד ס\"ב (לקמן ע' שסט)."],["3102","21","ועפ\"ז יומתק לשון המדרש אם שמרת את נרי כו' ואם כבית את נרי, שאין זה כפל ענין, אלא הם שני ענינים. \"כבית את נרי\" הוא שהאדם עובר ח\"ו על מצוות התורה [ואז \"אני <i>מכבה</i> את נרך\", שנעשה פגם בהנשמה, כדלקמן בפנים], ו\"שמרת את נרי\" הוא דלא רק שאינו עובר ח\"ו אלא שהוא <i>מקיים</i> מצוות התורה [ואז \"אני <i>משמר</i> את נרך\", <i>שנוסף</i> בהשימור]."],["3103","22","ועפ\"ז יומתק מ\"ש בהמאמר דצריך להבין באם שמרת את נרי אני משמר את נרך, מהו שייכותם כו' – דלכאורה הי' מספיק שיאמר צריך להבין מהו שייכותם כו' ולמה מעתיק עוד פעם לשון המדרש? ויש לומר, שכוונתו בזה היא להדגיש שהדיוק הוא רק ב\"אם שמרת\" כו' (ולא ב\"אם כבית\")."],["3104","23","וכמ\"ש בהמאמר \"שע\"י תרי\"ג מצוות עי\"ז <i>מתעלה</i> האדם כו'\"."],["3105","24","והגם ד\"<i>משמר</i> את נרך\" הוא <i>שנוסף</i> בה שימור (כנ\"ל הערה 21) – הרי ענין השימור הוא שהדבר <i>עצמו</i> נשמר [וע\"ד שמרת את נרי, דהגם שענין שמרת הוא לא רק שאינו עובר אלא שמקיים המצוה, מ\"מ, אין זה הוספה בהמצוה אלא שמקיים המצוה עצמה]."],["3106","25","ח\"ג (פ' בלק) קפז, א."],["3107","26","פל\"ה (מד, א)."],["3108","27","שם (מד, סע\"א ואילך)."],["3109","28","ראה תניא רפי\"ט (כד, ב) \"הגם שתהי' אין ואפס ותתבטל שם במציאות לגמרי\"."],["3110","29","והגם שהביטול שנמשך בהנשמה ע\"י קיום המצוות הוא למעלה מהביטול דהנשמה שמצד עצמה, מ\"מ נקרא בשם שמירה (אני משמר את נרך), דענין השמירה הוא שהדבר עצמו נשמר (כנ\"ל הערה 24), כי גם ביטול זה שייך להנשמה, כדלקמן סעיף ט."],["3111","30","אלא שיש שנים שקוראין גם פ' נשא לאחרי חג השבועות (כבשנה זו – תשכ\"ט). וע\"ד שפרשת במדבר קוראין לעולם בהשבת שלפני חג השבועות ולפעמים גם פ' נשא."],["3112","31","דחג השבועות תרכ\"ט (נדפס בסה\"מ תרכ\"ט ע' קצג ואילך)."],["3113","32","פי\"ח (כג, ב). וראה קיצורים והערות לתניא שם (ע' ק)."],["3114","33","ב\"ר פמ\"ז, ו. פפ\"ב, ו."],["3115","34","המעלה דאהבה זו על אהבה הטבעית – ראה תניא פמ\"א (נז, ב ואילך). ובארוכה – בסה\"מ תר\"ס ע' קמט ואילך.\nובתניא שם (נח, א) דה\"אהבה הטבעית שבלב כל ישראל\" היא (לא רק להיות דבוק בו אלא גם) \"לעשות כל מה שהוא רצון העליון ב\"ה\", ולכן \"יש לכל אדם להרגיל עצמו בכוונה זו\"."],["3116","35","בלקו\"ת פרשתנו (ל, א (הובא בסה\"מ תר\"ס שם)) שאהבה זו היא אהבה דאהרן שלמעלה מאהבה דאברהם. אבל ראה תניא שבהערה הקודמת דענין זה שייך לכל אחד מישראל מצד אהבה המסותרת שבירושה <i>מהאבות</i>. וראה אוה\"ת פרשתנו (ע' שלח) \"והמשכיל יבין שלא שאברהם לא הגיע למדריגת אה\"ר דאהרן ח\"ו, אלא זהו כמו שבמ\"ת נמשך הכח לישראל שיוכלו להמשיך אוא\"ס ע\"י מצוות מעשיות מה שלא זכה לזה אברהם\"."],["3117","36","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["3118","37","ראה לקמן ח\"ד ע' יז."],["3119","38","שבת פח, א."],["3120","39","לקו\"ת במדבר ביאור על בשעה שהקדימו (יד, ד)."],["3121","40","סוכה כח, א."],["3122","41","סה\"מ תרכ\"ט ע' רטז ואילך."],["3123","42","בהבא לקמן ראה גם תו\"א יתרו עא, ב. ובכ\"מ."],["3124","43","ראה בחיי עה\"פ תרומה כה, יא בשם פרדר\"א [ספ\"ד. וראה ברד\"ל שם]. שמו\"ר ספכ\"ג. במדב\"ר ספי\"ד. פיוט \"והחיות\" במוסף לר\"ה (בנוסח הקדושה) נוסח אשכנז."],["3125","44","ראה יחזקאל א, כו."],["3126","45","לשון הכתוב – שמואל-א טו, כט."],["3127","46","בהבא לקמן (בהחצאי ריבוע) ראה ד\"ה בהעלותך תרע\"ח (סה\"מ תרע\"ח ע' שמא)."],["3128","47","דכשאומרים על דבר מוגבל שהוא גדול, הגדלות שלו היא רק לגבי דברים שהם קטנים ממנו, אבל ישנם דברים שהם גדולים ממנו והוא <i>קטן</i>."],["3129","48","שמואל-א כד, יד. וראה פרש\"י עה\"פ. מכות יו\"ד, ב ובפרש\"י שם. פרש\"י עה\"פ משפטים כא, יג."],["3130","49","ראה בארוכה תו\"א מג\"א צח, ב."],["3131","50","תהלים קיט, קעב."],["3132","51","תו\"א יתרו סז, ב. ובכ\"מ. וראה לעיל ס\"ע שלד. וש\"נ."],["3133","52","וישלח לב, יא."],["3134","53","תניא אגה\"ק סימן ב."],["3135","54","ראה המשך תרס\"ו ע' נה."],["3136","55","יתרו כ, א."],["3137","56","ראה תו\"א יתרו עא, ב."],["3138","57","במדבר שם (יג, ג). וראה גם בהנסמן בהתוועדויות תשמ\"ט ח\"ג ס\"ע 235."],["3139","58","היינו שמצד <i>טבע הבריאה</i> מוכרחים להיות כן. אלא שיש להאדם בחירה חפשית לבחור היפך טבע הבריאה."],["3140","59","שלכן, גם לאחרי שנעשה עבד – אינו בטל כ\"כ. ראה לעיל ע' שנז הערה 28. דיש לומר, שזהו הטעם על זה שהשעבוד דעבד שמכרוהו ב\"ד הוא שעבוד גדול יותר מהמוכר עצמו."],["3141","60","שלכן גם העבד מבין דמי שאינו עבד של אדונו אינו מחוייב לקיים הציוויים שלו."],["3142","61","לעיל שם הערה 32, שהביטול דישראל ע\"י <i>שהקב\"ה כפה</i> עליהם הר כגיגית (שבת פח, א) הוא ביטול נעלה יותר מהביטול שלהם ע\"י שהקדימו נעשה לנשמע (וע\"ד החילוק דמכר עצמו ומכרוהו ב\"ד). וע\"פ מ\"ש בפנים, הביטול שנמשך במתן תורה הוא ביטול נעלה יותר גם מהביטול דכפה."],["3143","62","ראה זח\"ג עג, א."],["3144","63","ראה בארוכה ס' מאמרי אדמו\"ר האמצעי – דרושי חתונה ח\"ב ע' תיז ואילך. סה\"מ תרנ\"ז ס\"ע רכג ואילך. ועוד."]]]]});
